prompt --application/shared_components/user_interface/lovs/lov_105_invoice_lov
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(10853633128022957527)
,p_lov_name=>'LOV_105_INVOICE_LOV'
,p_static_id=>'lov-105-invoice-lov'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'       I.INVOICE_NO,',
'',
'       I.INVOICE_CODE,',
'',
'       I.INVOICE_DATE,',
'',
'       i.CUSTOMER_NO,',
'',
'       C.CUSTOMER_NAME,',
'',
'       C.MOBILE_NO,',
'',
'       I.TOTAL_AMOUNT,',
'',
'       (',
'           SELECT NVL(SUM(D.SALES_QTY),0)',
'             FROM TRN_SALES_INVOICE_DTL D',
'            WHERE D.INVOICE_NO = I.INVOICE_NO',
'       ) TOTAL_QTY',
'',
'FROM TRN_SALES_INVOICE_MST I',
'JOIN MST_CUSTOMER C',
'  ON C.CUSTOMER_NO = I.CUSTOMER_NO',
'',
'WHERE (',
'        I.DELIVERY_STATUS IN (''P'',''PD'')',
'     OR EXISTS',
'        (',
'            SELECT 1',
'              FROM TRN_DELIVERY_MST D',
'             WHERE D.DELIVERY_NO = :P105_DELIVERY_NO',
'               AND D.INVOICE_NO = I.INVOICE_NO',
'        )',
'      )',
'',
'ORDER BY I.INVOICE_NO DESC'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_return_column_name=>'INVOICE_NO'
,p_display_column_name=>'INVOICE_CODE'
