'/* Formatted on 9/8/2026 1:00:42 PM (QP5 v5.388) */',
'WITH',
'    CURRENT_PRICE',
'    AS',
'        (SELECT PRODUCT_NO,',
'                UOM_NO,',
'                SALES_RATE,',
'                ROW_NUMBER ()',
'                    OVER (PARTITION BY PRODUCT_NO, UOM_NO',
'                          ORDER BY EFFECTIVE_DATE DESC, SALES_PRICE_NO DESC)    AS RN',
'           FROM MST_SALES_PRICE',
'          WHERE ACTIVE_FLAG = ''1'' AND EFFECTIVE_DATE <= SYSDATE)',
'  SELECT P.PRODUCT_NO,',
'         P.PRODUCT_CODE || '' - '' || P.PRODUCT_NAME     AS PRODUCT_NAME,',
'         P.DESCRIPTION,',
'         P.UOM_NO,',
'         U.UOM_NAME,',
'         P.PURCHASE_RATE,',
'         NVL (CP.SALES_RATE, 0)                        AS SALES_RATE,',
'         NVL (S.STOCK_QTY, 0)                          AS STOCK_QTY',
'    FROM MST_PRODUCT P',
'         JOIN MST_UOM U ON U.UOM_NO = P.UOM_NO AND U.ACTIVE_FLAG = ''1''',
'         LEFT JOIN CURRENT_PRICE CP',
'             ON     CP.PRODUCT_NO = P.PRODUCT_NO',
'                AND CP.UOM_NO = P.UOM_NO',
'                AND CP.RN = 1',
'         LEFT JOIN',
'         (  SELECT PRODUCT_NO,',
'                   SUM (NVL (QTY_IN, 0)) - SUM (NVL (QTY_OUT, 0))    AS STOCK_QTY',
'              FROM TRN_STOCK_LEDGER',
'          GROUP BY PRODUCT_NO) S',
'             ON S.PRODUCT_NO = P.PRODUCT_NO',
'   WHERE P.ACTIVE_FLAG = 1',
'ORDER BY P.PRODUCT_NAME;'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_return_column_name=>'PRODUCT_NO'
,p_display_column_name=>'PRODUCT_NAME'
,p_version_scn=>'SH256:2UlUvPQxwplPzVsKMKB6OcfncrccfajTV17B65nzq5U'
,p_updated_on=>wwv_flow_imp.dz('20260908165332Z')
,p_updated_by=>'ADMIN'
);
