,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
' BEGIN',
'',
'    IF :P2_MENU_NO IS NULL',
'    THEN',
'        INSERT INTO SA_MENU (MENU_NO,',
'                                    MENU_ID,',
'                                    MENU_NAME,',
'                                    DESCRIPTION,',
'                                    PARENT_MENU_NO,',
'                                    SL_NO,',
'                                    APP_ID,',
'                                    SS_CREATOR,',
'                                    SS_CREATED_ON)',
'             VALUES ( S_SA_MENU.NEXTVAL,',
'                     :P2_MENU_ID,',
'                     :P2_MENU_NAME,',
'                     :P2_DESCRIPTION,',
'                     :P2_PARENT_MENU_NO,',
'                     :P2_SL_NO,',
'                     :P2_APP_ID,',
'                     :G_USER_NO,',
'                     --to_date(TO_CHAR (SYSDATE, ''DD-MON-YYYY HH24:MI:SS''))',
'                     SYSDATE',
'                    )',
'                      RETURNING MENU_NO into :P2_MENU_NO;',
'                --   :P1011_GREYFABSEND_NO := V_GREYFABSEND_NO;',
'    ELSE',
'        UPDATE SA_MENU',
'           SET MENU_ID = :P2_MENU_ID,',
'               MENU_NAME = :P2_MENU_NAME,',
'               DESCRIPTION = :P2_DESCRIPTION,',
'               PARENT_MENU_NO =:P2_PARENT_MENU_NO,',
'               SL_NO =:P2_SL_NO,',
'               SS_MODIFIER = :G_USER_NO',
'               WHERE MENU_NO =:P2_MENU_NO;',
'              -- SS_UPLOADED_ON = TO_CHAR (SYSDATE, ''DD-MON-YYYY HH24:MI:SS'');',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_success_message=>'&MENU_ID. Is Created !'
