,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'    v_total        NUMBER := 0;',
'    v_purchase_no  NUMBER;',
'',
'BEGIN',
'',
'    -------------------------------------------------',
'    -- Purchase No Validation',
'    -------------------------------------------------',
