'}',
'',
'.footer{',
'    margin-top:100px;',
'}',
'',
'.sign{',
'    width:30%;',
'    display:inline-block;',
'    text-align:center;',
'}',
'',
'.sign hr{',
'    border:1px solid black;',
'}',
'',
'.watermark{',
'    position:fixed;',
