'        TO_CHAR(',
'            v_total,',
'            ''999G999G999D99''',
'        )||',
'        ''</b>',
'    </td>',
'',
'</tr>',
'',
'</table>',
'',
'<div style="clear:both"></div>',
'',
'<br><br>',
'',
'<div>',
'    <b>Remarks :</b>',
'    Goods received in good condition.',
'</div>',
'',
'<div class="footer">',
'',
'    <div class="sign">',
'        <hr>',
'        Prepared By',
'    </div>',
'',
'    <div class="sign">',
'        <hr>',
'        Checked By',
'    </div>',
'',
'    <div class="sign">',
'        <hr>',
'        Approved By',
'    </div>',
'',
'</div>',
'',
''');',
'',
'END;'))
,p_plug_source_type=>'NATIVE_PLSQL'
);
