wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(24051996300357472165)
,p_plug_name=>'SUBMENU'
,p_static_id=>'submenu'
,p_region_name=>'submenu'
,p_parent_plug_id=>wwv_flow_imp.id(24051996238234472164)
,p_region_template_options=>'#DEFAULT#:margin-top-none:margin-bottom-none'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>30
,p_plug_new_grid_row=>false
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'  S.SUBMENU_NO,',
'  S.SUBMENU_ID,',
'  S.MENU_NO,',
'  S.SUBMENU_NAME,',
'  S.SUBMENU_TYPE,',
'  S.ACTIVE_FLAG,',
'  S.CAN_VIEW,',
'  S.CAN_MODIFY,',
'  S.CAN_REMOVE,',
'  S.CAN_CREATE',
'FROM SA_SUBMENU S',
'WHERE NOT EXISTS (',
'  SELECT 1 ',
'  FROM SA_GRANTOBJECT G',
'  WHERE G.SUBMENU_NO = S.SUBMENU_NO',
'    AND G.USER_NO = TO_NUMBER(REGEXP_SUBSTR(:P4_P_USER_NO, ''\d+''))',
');',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P4_P_USER_NO'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
