wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(8045880511268862421)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'AJX_GRANT_OBJ'
,p_static_id=>'ajx-grant-obj'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    V_MSG               VARCHAR2 (100);',
'    V_CUTDTL_NO_ARRAY   APEX_APPLICATION_GLOBAL.VC_ARR2;',
'    v_pk                NUMBER;',
'',
'    /* CURSOR CUR_EMP IS',
'        SELECT USER_NO',
'          FROM HR_EMP',
'         WHERE INSTR ('','' || APEX_APPLICATION.G_x01, '','' || USER_NO || '','') > 0',
'         AND USER_NO IS NOT NULL; */',
'    CURSOR CUR_EMP IS',
'        SELECT USER_NO',
'          FROM SA_USER',
'         WHERE INSTR ('','' || APEX_APPLICATION.G_x01, '','' || USER_NO || '','') > 0',
'         AND USER_NO IS NOT NULL;',
'',
'    CURSOR CUR_MENU IS',
'        SELECT SUBMENU_NO',
'          FROM SA_SUBMENU',
'         WHERE INSTR ('','' || APEX_APPLICATION.G_x02,'','' || SUBMENU_NO || '','') > 0;',
'',
'BEGIN',
'    APEX_JSON.OPEN_OBJECT;',
'    V_CUTDTL_NO_ARRAY :=',
'        APEX_UTIL.STRING_TO_TABLE (APEX_APPLICATION.G_X01, '','');',
'',
'    FOR I IN CUR_EMP',
'    LOOP',
'            FOR K IN CUR_MENU',
'            LOOP',
'                SELECT NVL (MAX (TO_NUMBER (GR_OBJECT_NO)), 0) + 1',
'                  INTO v_pk',
'                  FROM SA_GRANTOBJECT;',
'',
'                -- v_pk := S_SA_GRANTOBJECT.nextval;',
'                INSERT INTO SA_GRANTOBJECT (GR_OBJECT_NO,',
'                                            SUBMENU_NO,',
'                                            USER_NO,',
'                                            CAN_VIEW,',
'                                            CAN_MODIFY,',
'                                            CAN_REMOVE,',
'                                            CAN_SHARE,',
'                                            CAN_CREATE,',
'                                            --ROLE_NO,',
'                                            ACTIVE_FLAG',
'                                            )',
'                     VALUES (v_pk,',
'                             K.SUBMENU_NO,',
'                             i.USER_NO,',
'                             1,                      --APEX_APPLICATION.G_X03,',
'                             1,                      --APEX_APPLICATION.G_X04,',
'                             1,                      --APEX_APPLICATION.G_X05,',
'                             1,                     -- APEX_APPLICATION.G_X06,',
'                             1,                      --APEX_APPLICATION.G_X07,',
'                             --APEX_APPLICATION.G_X10,',
'                             1                    --APEX_APPLICATION.G_X08,',
'                             );',
'            END LOOP;',
'    END LOOP;',
'',
'    V_MSG := ''Object Garnd Successgully'';',
'    APEX_JSON.WRITE (''stat'', ''200'');',
'    --    APEX_JSON.WRITE (''V_LINEINPUT_NO'', V_LINEINPUT_NO);',
'    APEX_JSON.CLOSE_ALL;',
'EXCEPTION',
'    WHEN OTHERS',
'    THEN',
'        APEX_JSON.WRITE (''stat'', SQLERRM);',
'        APEX_JSON.CLOSE_ALL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>8045880511268862421
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(8045871773392862408)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(24066465249169484981)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GRAND-OBJECT - Save Interactive Grid Data'
,p_static_id=>'grand-object-save-interactive-grid-data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'CASE :APEX$ROW_STATUS WHEN ''C'' THEN NULL;',
'WHEN  ''U'' THEN NULL;',
'WHEN ''D'' THEN ',
'DELETE SA_GRANTOBJECT',
'WHERE GR_OBJECT_NO = :GR_OBJECT_NO;',
'END CASE;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>8045871773392862408
);
end;
