wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(32408091800680006161)
,p_plug_name=>'Product Register'
,p_static_id=>'register'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>30
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    p.product_no,',
'    p.product_code,',
'    p.product_name,',
'',
'    /* CATEGORY */',
'    c.category_name,',
'',
'    /* BRAND */',
'    b.brand_name,',
'',
'    /* UOM */',
'    u.uom_name,',
'',
'    /* PRODUCT DESCRIPTION */',
'    p.description,',
'',
'    /* ACTIVE STATUS */',
'    CASE',
'        WHEN p.active_flag = ''Y'' THEN ''Yes''',
'        ELSE ''No''',
'    END AS active_status,',
'',
'    /* PURCHASE RATE */',
'    NVL(p.purchase_rate, 0) AS purchase_rate,',
'',
'    /* SALES RATE */',
'    NVL(p.sales_rate, 0) AS sales_rate,',
'',
'    /* TOTAL SOLD QTY */',
'    NVL(',
'        (',
'            SELECT SUM(NVL(d.sales_qty, 0))',
'            FROM trn_sales_invoice_dtl d',
'            WHERE d.product_no = p.product_no',
'        ),',
'        0',
'    ) AS units,',
'',
'    /* TOTAL SALES */',
'    NVL(',
'        (',
'            SELECT SUM(NVL(d.total_amount, 0))',
'            FROM trn_sales_invoice_dtl d',
'            WHERE d.product_no = p.product_no',
'        ),',
'        0',
'    ) AS sales,',
'',
'    /* NUMBER OF CUSTOMERS */',
'    NVL(',
'        (',
'            SELECT COUNT(DISTINCT m.customer_no)',
'            FROM trn_sales_invoice_mst m',
'                 JOIN trn_sales_invoice_dtl d',
'                   ON d.invoice_no = m.invoice_no',
'            WHERE d.product_no = p.product_no',
'        ),',
'        0',
'    ) AS customers,',
'',
'    /* LAST SOLD DATE */',
'    (',
'        SELECT MAX(m.invoice_date)',
'        FROM trn_sales_invoice_mst m',
'             JOIN trn_sales_invoice_dtl d',
'               ON d.invoice_no = m.invoice_no',
'        WHERE d.product_no = p.product_no',
'    ) AS last_date_sold,',
'',
'    /* IMAGE ID */',
'    p.product_no AS img,',
'',
'    /* PRODUCT DETAIL LINK */',
'    apex_util.prepare_url(',
'        p_url =>',
'              ''f?p=''',
'           || :APP_ID',
'           || '':31:''',
'           || :APP_SESSION',
'           || ''::::P31_PRODUCT_NO:''',
'           || p.product_no',
'    ) AS icon_link,',
'',
'    /* IMAGE HTML */',
'    CASE',
'        WHEN NVL(DBMS_LOB.getlength(p.product_image), 0) = 0',
'        THEN NULL',
'',
'        ELSE',
'            ''<img alt="''',
'            || apex_escape.html(p.product_name)',
'            || ''" title="''',
'            || apex_escape.html(p.product_name)',
'            || ''" ''',
'            || ''style="border:4px solid #CCC; ''',
'            || ''border-radius:4px;" ''',
'            || ''src="''',
'            || apex_util.get_blob_file_src(',
'                   ''P31_PRODUCT_IMAGE'',',
'                   p.product_no',
'               )',
'            || ''" ''',
'            || ''height="75" width="75" />''',
'    END AS detail_img,',
'',
'    /* IMAGE URL ONLY */',
'    CASE',
'        WHEN NVL(DBMS_LOB.getlength(p.product_image), 0) = 0',
'        THEN NULL',
'',
'        ELSE apex_util.get_blob_file_src(',
'                 ''P31_PRODUCT_IMAGE'',',
'                 p.product_no',
'             )',
'    END AS detail_img_no_style',
'',
'FROM mst_product p',
'',
'LEFT JOIN mst_product_category c',
'       ON c.category_no = p.category_no',
'',
'LEFT JOIN mst_product_brand b',
'       ON b.brand_no = p.brand_no',
'',
'LEFT JOIN mst_uom u',
'       ON u.uom_no = p.uom_no',
'',
'ORDER BY p.product_name;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
