,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'DELETE'
,p_static_id=>'delete'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'',
'    DELETE FROM MST_PRODUCT_CATEGORY',
'     WHERE CATEGORY_NO = :P6_CATEGORY_NO;',
'',
'    apex_application.g_print_success_message :=',
'        ''Product Category has been deleted successfully.'';',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>8121371891415049861
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(8121371439552049860)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form Entry'
,p_static_id=>'process-form-entry'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :P6_PRODUCT_NO IS NULL THEN',
'        INSERT INTO MST_PRODUCT (',
'            PRODUCT_NO,',
'            CATEGORY_NO,',
'            PRODUCT_CODE,',
'            PRODUCT_NAME,',
'            PURCHASE_RATE,',
'            SALES_RATE,',
'            MIN_STOCK_QTY,',
'            ACTIVE_FLAG,',
'            UOM_NO,',
'            CREATED_BY,',
'            CREATED_DATE',
'        )',
'        VALUES (',
'            SEQ_PRODUCT_NO.NEXTVAL,',
'            :P6_PRODUCT_CATEGORY,',
'           ''PRD'' || LPAD(SEQ_PRODUCT_NO.NEXTVAL,4,''0''),',
'            :P6_PRODUCT_NAME,',
'            :P6_PURCHASE_RATE,',
'            :P6_SALES_RATE,',
'            :P6_MIN_STOCK_QTY,',
'            :P6_ACTIVE_FLAG,',
'            :P6_UOM_NO,',
'            :APP_USER,',
'            SYSDATE',
'        );',
'',
'          APEX_APPLICATION.g_print_success_message :=',
'            ''Product has been saved successfully.'';',
'    ELSE',
'        UPDATE MST_PRODUCT',
'           SET CATEGORY_NO   = :P6_CATEGORY_NO,',
'               PRODUCT_NAME  = :P6_PRODUCT_NAME,',
'               PURCHASE_RATE = :P6_PURCHASE_RATE,',
'               SALES_RATE    = :P6_SALES_RATE,',
'               MIN_STOCK_QTY = :P6_MIN_STOCK_QTY,',
'               ACTIVE_FLAG   = :P6_ACTIVE_FLAG,',
'               UOM_NO        = :P6_UOM_NO,',
'               UPDATED_BY    = :APP_USER,',
'               UPDATED_DATE  = SYSDATE',
'         WHERE PRODUCT_NO    = :P6_PRODUCT_NO;',
'',
'         ',
'        APEX_APPLICATION.g_print_success_message :=',
'            ''Product has been updated successfully.'';',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>8121371439552049860
);
end;
