 p_id=>wwv_flow_imp.id(8068832197999255946)
,p_plug_name=>'Supplier Register'
,p_static_id=>'register'
,p_region_name=>'SUPPLIER_REPORT'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc:margin-top-none:margin-bottom-sm'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>20
,p_plug_grid_column_span=>8
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 8/31/2026 11:29:04 AM (QP5 v5.388) */',
'  SELECT s.SUPPLIER_NO,',
'         s.SUPPLIER_CODE,',
'         s.SUPPLIER_NAME,',
'         s.CONTACT_PERSON,',
'         s.MOBILE_NO,',
'         s.EMAIL_ADDRESS,',
'         s.ADDRESS,',
'         S.ACTIVE_FLAG,',
'         DECODE (s.ACTIVE_FLAG,  1, ''Active'',  0, ''Inactive'')     STATUS,',
'         s.CREATED_BY,',
'         s.CREATED_DATE,',
'         s.UPDATED_BY,',
'         s.UPDATED_DATE,',
'         NVL(D.DUE_AMOUNT, 0) AS DUE_AMOUNT,',
'',
'       CASE',
'           WHEN NVL(D.DUE_AMOUNT, 0) > 0',
unistr('           THEN ''\26A0 Due'''),
unistr('           ELSE ''\2713 Clear'''),
'       END AS DUE_STATUS',
'    FROM MST_SUPPLIER s',
'         LEFT JOIN (  SELECT SUPPLIER_NO, SUM (NVL (DUE_AMOUNT, 0)) AS DUE_AMOUNT',
'                        FROM TRN_PURCHASE_MST',
'                    GROUP BY SUPPLIER_NO) D',
'             ON D.SUPPLIER_NO = S.SUPPLIER_NO',
'   WHERE (   :P7_DUE_FILTER IS NULL',
'          OR :P7_DUE_FILTER = ''''',
'          OR ( :P7_DUE_FILTER = ''DUE'' AND NVL (D.DUE_AMOUNT, 0) > 0))',
'ORDER BY S.SUPPLIER_NAME'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P7_DUE_FILTER'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
