wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(11710861980629534)
,p_plug_name=>'CUSTOMER DETAILS SUMMERY'
,p_static_id=>'customer-details-summery'
,p_region_name=>'CUSTOMER_DETAILS'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4502917002193490937
,p_plug_display_sequence=>30
,p_plug_new_grid_row=>false
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 9/1/2026 4:35:07 PM (QP5 v5.388) */',
'/* ============================================================',
'   CUSTOMER DETAILS CARD',
'   ============================================================ */',
'',
'DECLARE',
'    v_html            CLOB;',
'',
'    v_customer_name   VARCHAR2 (300);',
'    v_customer_code   VARCHAR2 (50);',
'    v_mobile          VARCHAR2 (50);',
'    v_email           VARCHAR2 (200);',
'    v_address         VARCHAR2 (500);',
'    v_status          VARCHAR2 (20);',
'    v_since           VARCHAR2 (30);',
'',
'    v_orders          NUMBER := 0;',
'    v_total_sales     NUMBER := 0;',
'    v_due_amount      NUMBER := 0;',
'BEGIN',
'    /* ============================================================',
'       NO CUSTOMER SELECTED',
'       ============================================================ */',
'',
'    IF :P8_CUSTOMER_NO IS NULL',
'    THEN',
'        RETURN ''',
'        <style>',
'            .cust-empty{',
'                height:150px;',
'                display:flex;',
'                flex-direction:column;',
'                align-items:center;',
'                justify-content:center;',
'                color:#9aa5b1;',
'                font-size:13px;',
'                text-align:center;',
'            }',
'',
'            .cust-empty i{',
'                font-size:30px;',
'                margin-bottom:8px;',
'                color:#cbd2da;',
'            }',
'        </style>',
'',
'        <div class="cust-empty">',
'            <i class="fa fa-user"></i>',
'            <div>Select a customer to view details</div>',
'        </div>'';',
'    END IF;',
'',
'',
'    /* ============================================================',
'       CUSTOMER INFORMATION',
'       ============================================================ */',
'',
'    SELECT CUSTOMER_NAME,',
'           CUSTOMER_CODE,',
'           MOBILE_NO,',
'           EMAIL_ADDRESS,',
'           ADDRESS,',
'           CASE WHEN ACTIVE_FLAG = 1 THEN ''ACTIVE'' ELSE ''INACTIVE'' END,',
'           TO_CHAR (CREATED_DATE, ''DD-Mon-YYYY'')',
'      INTO v_customer_name,',
'           v_customer_code,',
'           v_mobile,',
'           v_email,',
'           v_address,',
'           v_status,',
'           v_since',
'      FROM MST_CUSTOMER',
'     WHERE CUSTOMER_NO = :P8_CUSTOMER_NO;',
'',
'',
'    /* ============================================================',
'       SALES SUMMARY',
'       ============================================================ */',
'',
'    SELECT COUNT (*), NVL (SUM (TOTAL_AMOUNT), 0), NVL (SUM (DUE_AMOUNT), 0)',
'      INTO v_orders, v_total_sales, v_due_amount',
'      FROM TRN_SALES_INVOICE_MST',
'     WHERE CUSTOMER_NO = :P8_CUSTOMER_NO;',
'',
'',
'    /* ============================================================',
'       HTML',
'       ============================================================ */',
'',
'    v_html :=',
'           ''<style>',
'',
'        .customer-mini-card{',
'            width:100%;',
'            background:#ffffff;',
'            border:1px solid #e3e7ec;',
'            border-radius:9px;',
'            overflow:hidden;',
'            box-sizing:border-box;',
'            font-family:Arial,sans-serif;',
'        }',
'',
'',
'        /* EMPTY */',
'',
'        .cust-empty{',
'            height:150px;',
'            display:flex;',
'            flex-direction:column;',
'            align-items:center;',
'            justify-content:center;',
'            color:#9aa5b1;',
'            font-size:13px;',
'            text-align:center;',
'        }',
'',
'        .cust-empty i{',
'            font-size:30px;',
'            margin-bottom:8px;',
'            color:#cbd2da;',
'        }',
'',
'',
'        /* HEADER */',
'',
'        .cust-head{',
'            padding:10px 12px;',
'            border-bottom:1px solid #edf0f3;',
'            display:flex;',
'            align-items:center;',
'            justify-content:space-between;',
'            gap:8px;',
'        }',
'',
'',
'        .cust-profile{',
'            display:flex;',
'            align-items:center;',
'            min-width:0;',
'        }',
'',
'',
'        .cust-avatar{',
'            width:38px;',
'            height:38px;',
'            min-width:38px;',
'            border-radius:50%;',
'            background:#e5f7f4;',
'            color:#14877f;',
'            display:flex;',
'            align-items:center;',
'            justify-content:center;',
'            font-size:14px;',
'            font-weight:700;',
'            margin-right:9px;',
'        }',
'',
'',
'        .cust-name{',
'            font-size:14px;',
'            font-weight:700;',
'            color:#172033;',
'            white-space:nowrap;',
'            overflow:hidden;',
'            text-overflow:ellipsis;',
'        }',
'',
'',
'        .cust-code{',
'            font-size:10px;',
'            color:#8a94a3;',
'            margin-top:2px;',
'        }',
'',
'',
'        /* STATUS */',
'',
'        .cust-status{',
'            font-size:9px;',
'            font-weight:700;',
'            padding:4px 8px;',
'            border-radius:10px;',
'            white-space:nowrap;',
'        }',
'',
'',
'        .cust-active{',
'            background:#e5f8ee;',
'            color:#16834b;',
'        }',
'',
'',
'        .cust-inactive{',
'            background:#fdecec;',
'            color:#c93636;',
'        }',
'',
'',
'        /* INFORMATION */',
'',
'        .cust-info{',
'            padding:7px 12px;',
'            border-bottom:1px solid #edf0f3;',
'        }',
'',
'',
'        .cust-info-row{',
'            display:flex;',
'            align-items:center;',
'            gap:8px;',
'            margin:6px 0;',
'            color:#5f6b79;',
'            font-size:11px;',
'        }',
'',
'',
'        .cust-info-row i{',
'            width:15px;',
'            text-align:center;',
'            color:#8c98a7;',
'            font-size:11px;',
'        }',
'',
'',
'        .cust-info-text{',
'            overflow:hidden;',
'            text-overflow:ellipsis;',
'            white-space:nowrap;',
'        }',
'',
'',
'        /* SUMMARY */',
'',
'        .cust-summary{',
'            display:grid;',
'            grid-template-columns:1fr 1fr 1fr;',
'            gap:7px;',
'            padding:8px 12px;',
'        }',
'',
'',
'        .cust-stat{',
'            background:#f7f9fc;',
'            border-radius:6px;',
'            padding:7px 9px;',
'        }',
'',
'',
'        .cust-stat-label{',
'            font-size:8px;',
'            color:#7b8796;',
'            font-weight:700;',
'            text-transform:uppercase;',
'            letter-spacing:.3px;',
'        }',
'',
'',
'        .cust-stat-value{',
'            margin-top:3px;',
'            font-size:13px;',
'            font-weight:700;',
'            color:#172033;',
'            white-space:nowrap;',
'        }',
'',
'',
'        /* TOTAL SALES */',
'',
'        .cust-sales{',
'            color:#286596;',
'        }',
'',
'',
'        /* DUE */',
'',
'        .cust-due{',
'            color:#bd7b16;',
'        }',
'',
'',
'        /* ORDERS */',
'',
'        .cust-orders{',
'            color:#14877f;',
'        }',
'',
'',
'        @media(max-width:600px){',
'',
'            .cust-name{',
'                max-width:140px;',
'            }',
'',
'            .cust-summary{',
'                grid-template-columns:1fr 1fr;',
'            }',
'',
'            .cust-stat:last-child{',
'                grid-column:span 2;',
'            }',
'',
'        }',
'',
'    </style>',
'',
'',
'    <div class="customer-mini-card">',
'',
'',
'        <!-- HEADER -->',
'',
'        <div class="cust-head">',
'',
'            <div class="cust-profile">',
'',
'                <div class="cust-avatar">''',
'        || UPPER (SUBSTR (v_customer_name, 1, 1))',
'        || ''</div>',
'',
'                <div>',
'',
'                    <div class="cust-name">''',
'        || APEX_ESCAPE.HTML (v_customer_name)',
'        || ''</div>',
'',
'                    <div class="cust-code">''',
'        || APEX_ESCAPE.HTML (v_customer_code)',
'        || '' &bull; Since ''',
'        || v_since',
'        || ''</div>',
'',
'                </div>',
'',
'            </div>',
'',
'',
'            <div class="cust-status ''',
'        || CASE',
'               WHEN v_status = ''ACTIVE'' THEN ''cust-active''',
'               ELSE ''cust-inactive''',
'           END',
'        || ''">''',
'        || v_status',
'        || ''</div>',
'',
'        </div>',
'',
'',
'        <!-- CUSTOMER INFORMATION -->',
'',
'        <div class="cust-info">',
'',
'',
'            <div class="cust-info-row">',
'',
'                <i class="fa fa-phone"></i>',
'',
'                <span class="cust-info-text">''',
'        || APEX_ESCAPE.HTML (NVL (v_mobile, ''-''))',
'        || ''</span>',
'',
'            </div>',
'',
'',
'            <div class="cust-info-row">',
'',
'                <i class="fa fa-envelope"></i>',
'',
'                <span class="cust-info-text">''',
'        || APEX_ESCAPE.HTML (NVL (v_email, ''-''))',
'        || ''</span>',
'',
'            </div>',
'',
'',
'            <div class="cust-info-row">',
'',
'                <i class="fa fa-map-marker"></i>',
'',
'                <span class="cust-info-text">''',
'        || APEX_ESCAPE.HTML (NVL (v_address, ''-''))',
'        || ''</span>',
'',
'            </div>',
'',
'',
'        </div>',
'',
'',
'        <!-- SUMMARY -->',
'',
'        <div class="cust-summary">',
'',
'',
'            <!-- TOTAL SALES -->',
'',
'            <div class="cust-stat">',
'',
'                <div class="cust-stat-label">',
'                    Total Sales',
'                </div>',
'',
'                <div class="cust-stat-value cust-sales">',
'',
unistr('                    \09F3 '''),
'        || TO_CHAR (v_total_sales,',
'                    ''FM999999999999990D00'',',
'                    ''NLS_NUMERIC_CHARACTERS=''''.,'''''')',
'        || ''',
'',
'                </div>',
'',
'            </div>',
'',
'',
'            <!-- DUE AMOUNT -->',
'',
'            <div class="cust-stat">',
'',
'                <div class="cust-stat-label">',
'                    Due Amount',
'                </div>',
'',
'                <div class="cust-stat-value cust-due">',
'',
unistr('                    \09F3 '''),
'        || TO_CHAR (v_due_amount,',
'                    ''FM999999999999990D00'',',
'                    ''NLS_NUMERIC_CHARACTERS=''''.,'''''')',
'        || ''',
'',
'                </div>',
'',
'            </div>',
'',
'',
'            <!-- TOTAL ORDERS -->',
'',
'            <div class="cust-stat">',
'',
'                <div class="cust-stat-label">',
'                    Total Orders',
'                </div>',
'',
'                <div class="cust-stat-value cust-orders">',
'',
'                    ''',
'        || TO_CHAR (v_orders, ''FM999999999999990'')',
'        || ''',
'',
'                </div>',
'',
'            </div>',
'',
'',
'        </div>',
'',
'',
'    </div>'';',
'',
'',
'    RETURN v_html;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND',
'    THEN',
'        RETURN ''',
'        <div class="cust-empty">',
'',
'            <i class="fa fa-user-times"></i>',
'',
'            <div>Customer not found</div>',
'',
'        </div>'';',
'    WHEN OTHERS',
'    THEN',
'        RETURN ''',
'        <div class="cust-empty">',
'',
'            <i class="fa fa-exclamation-circle"></i>',
'',
'            <div>Unable to load customer details</div>',
'',
'        </div>'';',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P8_CUSTOMER_NO'
,p_created_on=>wwv_flow_imp.dz('20260828214920Z')
,p_updated_on=>wwv_flow_imp.dz('20260901163518Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(11710654151629532)
,p_plug_name=>'SUMMERY'
,p_static_id=>'summery'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4502917002193490937
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 9/1/2026 4:16:59 PM (QP5 v5.388) */',
'/* ============================================================',
'   CUSTOMER KPI SUMMARY',
'   ============================================================ */',
'',
'DECLARE',
'    v_html                CLOB;',
'',
'    v_total_customer      NUMBER := 0;',
'    v_active_customer     NUMBER := 0;',
'    v_inactive_customer   NUMBER := 0;',
'    v_total_due           NUMBER := 0;',
'    v_total_received      NUMBER := 0;',
'BEGIN',
'    /* ============================================================',
'       CUSTOMER COUNT',
'       ============================================================ */',
'',
'    SELECT COUNT (*),',
'           NVL (SUM (CASE WHEN ACTIVE_FLAG = 1 THEN 1 ELSE 0 END), 0),',
'           NVL (SUM (CASE WHEN ACTIVE_FLAG = 0 THEN 1 ELSE 0 END), 0)',
'      INTO v_total_customer, v_active_customer, v_inactive_customer',
'      FROM MST_CUSTOMER;',
'',
'',
'    /* ============================================================',
'       TOTAL DUE & TOTAL RECEIVED',
'       ============================================================ */',
'',
'    SELECT NVL (SUM (DUE_AMOUNT), 0), NVL (SUM (RECEIVED_AMOUNT), 0)',
'      INTO v_total_due, v_total_received',
'      FROM TRN_SALES_INVOICE_MST;',
'',
'',
'    /* ============================================================',
'       HTML',
'       ============================================================ */',
'',
'    v_html :=',
'           ''<style>',
'',
'        .cust-kpi-wrapper {',
'            display:grid;',
'            grid-template-columns:repeat(5,1fr);',
'            gap:12px;',
'            width:100%;',
'            box-sizing:border-box;',
'        }',
'',
'        .cust-kpi-card {',
'            height:64px;',
'            min-height:64px;',
'            border:1px solid #dfe5eb;',
