'        }',
'',
'        .cust-kpi-icon {',
'            width:34px;',
'            height:34px;',
'            min-width:34px;',
'',
'            border-radius:7px;',
'',
'            display:flex;',
'            align-items:center;',
'            justify-content:center;',
'',
'            font-size:15px;',
'        }',
'',
'        .cust-kpi-content {',
'            min-width:0;',
'        }',
'',
'        .cust-kpi-title {',
'            font-size:12px;',
'            line-height:15px;',
'            color:#6b7a8c;',
'            margin:0 0 2px 0;',
