'        }',
'',
'        .cust-kpi-value {',
'            font-size:19px;',
'            line-height:21px;',
'            font-weight:700;',
'            margin:0;',
'        }',
'',
'',
'        /* TOTAL CUSTOMERS */',
'',
'        .cust-total {',
'            background:#f7fafc;',
'        }',
'',
'        .cust-total .cust-kpi-icon {',
'            background:#e8f1fa;',
'            color:#286596;',
'        }',
'',
'        .cust-total .cust-kpi-value {',
'            color:#286596;',
'        }',
'',
'',
'        /* ACTIVE CUSTOMERS */',
'',
'        .cust-active {',
'            background:#f7fbf8;',
'        }',
'',
'        .cust-active .cust-kpi-icon {',
'            background:#e8f6ec;',
'            color:#21894d;',
'        }',
'',
'        .cust-active .cust-kpi-value {',
'            color:#21894d;',
'        }',
'',
'',
'        /* INACTIVE CUSTOMERS */',
'',
'        .cust-inactive {',
'            background:#fff8f8;',
'        }',
'',
'        .cust-inactive .cust-kpi-icon {',
'            background:#fdeaea;',
'            color:#d03930;',
'        }',
'',
'        .cust-inactive .cust-kpi-value {',
'            color:#d03930;',
'        }',
'',
'',
'        /* TOTAL DUE */',
'',
'        .cust-due {',
'            background:#fffdf7;',
'        }',
'',
'        .cust-due .cust-kpi-icon {',
'            background:#fff3d6;',
'            color:#bd7b16;',
'        }',
'',
'        .cust-due .cust-kpi-value {',
'            color:#bd7b16;',
'        }',
'',
'',
'        /* TOTAL RECEIVED */',
'',
'        .cust-received {',
'            background:#f7f9ff;',
'        }',
'',
'        .cust-received .cust-kpi-icon {',
'            background:#e9edff;',
'            color:#4b5fc4;',
'        }',
'',
'        .cust-received .cust-kpi-value {',
'            color:#4b5fc4;',
'        }',
'',
'',
'        /* RESPONSIVE */',
