'            PRODUCT_NO,',
'            OPENING_QTY,',
'            REMARKS,',
'            CREATED_BY,',
'            CREATED_DATE',
'        )',
'        VALUES',
'        (',
'            SEQ_OPENING_NO.NEXTVAL,',
'            :P9_OPENING_DATE,',
'            :P9_PRODUCT_NO,',
'            :P9_OPENING_QTY,',
'            :P9_REMARKS,',
'            :APP_USER,',
'            SYSDATE',
'        )',
'        RETURNING OPENING_NO',
'             INTO :P9_OPENING_NO;',
'',
'        /* STOCK LEDGER POSTING */',
'',
'        INSERT INTO TRN_STOCK_LEDGER',
'        (',
'            LEDGER_NO,',
'            TRAN_DATE,',
'            TRAN_TYPE,',
'            REF_NO,',
'            PRODUCT_NO,',
'            QTY_IN,',
'            QTY_OUT,',
'            REMARKS,',
'            CREATED_BY,',
'            CREATED_DATE',
'        )',
'        VALUES',
'        (',
'            SEQ_LEDGER_NO.NEXTVAL,',
'            :P9_OPENING_DATE,',
'            ''OPENING'',',
'            :P9_OPENING_NO,',
'            :P9_PRODUCT_NO,',
'            :P9_OPENING_QTY,',
'            0,',
'            :P9_REMARKS,',
'            :APP_USER,',
'            SYSDATE',
'        );',
'',
'        apex_application.g_print_success_message :=',
'            ''Opening stock saved successfully.'';',
'',
'    ELSE',
'',
'        UPDATE TRN_OPENING_STOCK',
'           SET OPENING_DATE = :P9_OPENING_DATE,',
'               PRODUCT_NO   = :P9_PRODUCT_NO,',
'               OPENING_QTY  = :P9_OPENING_QTY,',
'               REMARKS      = :P9_REMARKS,',
'               UPDATED_BY   = :APP_USER,',
'               UPDATED_DATE = SYSDATE',
'         WHERE OPENING_NO = :P9_OPENING_NO;',
'',
'        /* LEDGER UPDATE */',
'',
'        UPDATE TRN_STOCK_LEDGER',
'           SET TRAN_DATE   = :P9_OPENING_DATE,',
'               PRODUCT_NO  = :P9_PRODUCT_NO,',
'               QTY_IN      = :P9_OPENING_QTY,',
'               REMARKS     = :P9_REMARKS',
'         WHERE TRAN_TYPE = ''OPENING''',
'           AND REF_NO    = :P9_OPENING_NO;',
'',
'        apex_application.g_print_success_message :=',
'            ''Opening stock updated successfully.'';',
'',
'    END IF;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(8265785915508035)
,p_internal_uid=>8129065283753016243
,p_updated_on=>wwv_flow_imp.dz('20260907165752Z')
,p_updated_by=>'ADMIN'
);
end;
