wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(25854766141375286014)
,p_plug_name=>'Stock Ledger'
,p_static_id=>'register'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--removeHeader js-removeLandmark:t-Form--slimPadding:margin-top-none:margin-bottom-none'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>50
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT * FROM (SELECT',
'       L.LEDGER_NO,',
'',
'       L.TRAN_DATE,',
'',
'       P.PRODUCT_CODE,',
'',
'       P.PRODUCT_NAME,',
'',
'       L.TRAN_TYPE,',
'',
'       CASE L.TRAN_TYPE',
'            WHEN ''OPENING'' THEN ''Opening Stock''',
'            WHEN ''PURCHASE'' THEN ''Purchase''',
'            WHEN ''SALES'' THEN ''Sales''',
'            WHEN ''DELIVERY'' THEN ''Sales Delivery''',
'            WHEN ''CUSTOMER_RETURN'' THEN ''Customer Return''',
'       END TRANSACTION_NAME,',
'',
'       L.REF_NO,',
'',
'       L.QTY_IN,',
'',
'       L.QTY_OUT,',
'',
'       SUM(',
'            NVL(L.QTY_IN,0)',
'            -',
'            NVL(L.QTY_OUT,0)',
'       )',
'       OVER',
'       (',
'            PARTITION BY L.PRODUCT_NO',
'            ORDER BY L.TRAN_DATE,',
'                     L.LEDGER_NO',
'       ) BALANCE,',
'',
'       L.CREATED_BY,',
'',
'       L.CREATED_DATE',
'',
'FROM TRN_STOCK_LEDGER L',
'',
'JOIN MST_PRODUCT P',
'  ON P.PRODUCT_NO = L.PRODUCT_NO',
'',
'WHERE (:P11_PRODUCT_NO IS NULL',
'       OR L.PRODUCT_NO = :P11_PRODUCT_NO)',
'',
'AND (:P11_DATE_FROM IS NULL',
'     OR L.TRAN_DATE >= :P11_DATE_FROM)',
'',
'AND (:P11_DATE_TO IS NULL',
'     OR L.TRAN_DATE <= :P11_DATE_TO)',
'',
'AND (:P11_TRAN_TYPE IS NULL',
'     OR L.TRAN_TYPE = :P11_TRAN_TYPE)',
'',
'ORDER BY',
'       L.PRODUCT_NO,',
'       L.TRAN_DATE,',
'       L.LEDGER_NO);'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P11_PRODUCT_NO,P11_DATE_FROM,P11_DATE_TO,P11_TRAN_TYPE'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
,p_prn_body_font_family=>'Helvetica'
,p_prn_body_font_weight=>'normal'
