,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT *',
'FROM',
'(',
'    SELECT',
'           D.PURCHASE_DTL_NO,',
'           D.PURCHASE_NO,',
'           D.PRODUCT_NO,',
'',
'           --P.PRODUCT_CODE,',
'          -- P.PRODUCT_NAME,',
'           P.DESCRIPTION,',
'           P.BRAND_NO,',
'',
'           D.UOM_NO,',
'           U.UOM_NAME,',
'',
'           D.PACK_QTY,',
'           D.PURCHASE_QTY,',
'           D.PURCHASE_RATE,',
'           D.BASE_QTY,',
'           D.BASE_RATE,',
'           D.TOTAL_AMOUNT,',
'',
'           D.RECEIVED_QTY,',
'           D.BALANCE_QTY,',
'',
'           D.REMARKS',
'',
'      FROM TRN_PURCHASE_DTL D',
'',
'      JOIN MST_PRODUCT P',
'        ON P.PRODUCT_NO = D.PRODUCT_NO',
'',
' LEFT JOIN MST_UOM U',
'        ON U.UOM_NO = D.UOM_NO',
'',
'     WHERE D.PURCHASE_NO = :P12_PURCHASE_NO',
'',
'  ORDER BY D.PURCHASE_DTL_NO',
');'))
