wwv_flow_imp_page.create_region_column(
 p_id=>wwv_flow_imp.id(18574585158713404009)
,p_name=>'UOM_NO'
,p_source_type=>'DB_COLUMN'
,p_source_expression=>'UOM_NO'
,p_data_type=>'NUMBER'
,p_session_state_data_type=>'VARCHAR2'
,p_is_query_only=>false
,p_item_type=>'NATIVE_SELECT_LIST'
,p_heading=>'Market UOM'
,p_heading_alignment=>'LEFT'
,p_display_sequence=>150
,p_value_alignment=>'LEFT'
,p_is_required=>false
,p_lov_type=>'SQL_QUERY'
,p_lov_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT UOM_NAME D,',
'       UOM_NO   R',
'FROM',
'(',
'    -- Base UOM',
'    SELECT U.UOM_NAME,',
'           U.UOM_NO,',
'           1 ORD',
'      FROM MST_PRODUCT P',
'      JOIN MST_UOM U',
'        ON U.UOM_NO = P.UOM_NO',
'     WHERE P.PRODUCT_NO = :PRODUCT_NO',
'',
'    UNION ALL',
'',
'    -- Conversion UOM',
'    SELECT U.UOM_NAME,',
'           C.CONVERT_UOM_NO,',
'           2 ORD',
'      FROM MST_UOM_CONVERSION C',
'      JOIN MST_UOM U',
'        ON U.UOM_NO = C.CONVERT_UOM_NO',
'     WHERE C.PRODUCT_NO = :PRODUCT_NO',
'       AND C.ACTIVE_FLAG = ''1''',
')',
'ORDER BY ORD, D;'))
,p_lov_display_extra=>false
,p_lov_display_null=>false
,p_lov_cascade_parent_items=>'PRODUCT_NO'
,p_ajax_items_to_submit=>'PRODUCT_NO'
,p_ajax_optimize_refresh=>false
,p_static_id=>'UOM_NO'
,p_use_as_row_header=>false
,p_enable_hide=>true
,p_is_primary_key=>false
,p_duplicate_value=>true
,p_include_in_export=>true
,p_help_text=>'Unit Of majerment'
,p_updated_on=>wwv_flow_imp.dz('20260902120203Z')
,p_updated_by=>'ADMIN'
);
