wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(16705327962349162305)
,p_plug_name=>'PURCHASE-REGISTER'
,p_static_id=>'register'
,p_region_name=>'purchase-register'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--removeHeader js-removeLandmark:t-Form--slimPadding:margin-top-none:margin-bottom-none'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT * FROM (SELECT M.PURCHASE_NO,',
'       M.PURCHASE_CODE,',
'       M.PURCHASE_DATE,',
'       S.SUPPLIER_NAME,',
'       (',
'           SELECT SUM(D.TOTAL_AMOUNT)',
'             FROM TRN_PURCHASE_DTL D',
'            WHERE D.PURCHASE_NO = M.PURCHASE_NO',
'       ) TOTAL_AMOUNT,',
'       CASE M.APPROVAL_STATUS',
'            WHEN ''P'' THEN ''Pending''',
'            WHEN ''A'' THEN ''Approved''',
'            WHEN ''R'' THEN ''Rejected''',
'       END APPROVAL_STATUS,',
'       M.CREATED_BY,',
'       M.CREATED_DATE',
'FROM TRN_PURCHASE_MST M',
'JOIN MST_SUPPLIER S',
'  ON S.SUPPLIER_NO = M.SUPPLIER_NO',
'  WHERE APPROVAL_STATUS  = ''P''',
'ORDER BY M.PURCHASE_NO DESC);'))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
