 p_id=>wwv_flow_imp.id(8427741704912207848)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'REJECT_PURCHASE'
,p_static_id=>'reject-purchase'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'',
'    UPDATE TRN_PURCHASE_MST',
'       SET APPROVAL_STATUS = ''R'',',
'           APPROVED_BY     = :APP_USER,',
'           APPROVED_DATE   = SYSDATE',
'     WHERE PURCHASE_NO = APEX_APPLICATION.G_X01;',
'',
'    COMMIT;',
'',
'    HTP.P(''SUCCESS'');',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        HTP.P(SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>8427741704912207848
);
end;
