,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--scrollBody:t-Form--slimPadding:t-Form--large:t-Form--stretchInputs:margin-top-none:margin-bottom-none'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>555
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 7/17/2026 6:02:07 PM (QP5 v5.287) */',
'SELECT O.ORDER_NO,',
'       O.ORDER_CODE,',
'       O.ORDER_DATE,',
'       O.CUSTOMER_NO,',
'       C.CUSTOMER_CODE,',
'       C.CUSTOMER_NAME,',
'       C.MOBILE_NO,',
'       C.ADDRESS,',
'       O.ORDER_STATUS,',
'       CASE O.ORDER_STATUS',
'          WHEN ''P'' THEN ''Pending''',
'          WHEN ''PI'' THEN ''Partially Invoiced''',
'          WHEN ''I'' THEN ''Invoiced''',
'          WHEN ''PD'' THEN ''Partially Delivered''',
'          WHEN ''D'' THEN ''Delivered''',
'       END',
'          ORDER_STATUS_NAME,',
'       O.DELIVERY_ADDRESS,',
'       O.CONTACT_NO,',
'       O.EXPECTED_DATE,',
'       O.REMARKS,',
'       O.CREATED_BY,',
'       O.CREATED_DATE,',
'       O.UPDATED_BY,',
'       O.UPDATED_DATE,',
'       O.DELIVERY_BY,',
'       O.DELIVERY_DATE,',
'       O.TOTAL_AMOUNT,',
'       O.TOTAL_QTY,',
'       I.INVOICE_CNT,',
'       I.INVOICE_NO,',
'       I.INVOICE_CODE',
'  FROM TRN_SALES_ORDER_MST O',
'       , MST_CUSTOMER C ,',
'        (SELECT COUNT (*) INVOICE_CNT,INVOICE_NO  ,INVOICE_CODE,ORDER_NO',
'          FROM TRN_SALES_INVOICE_MST ',
'         GROUP BY INVOICE_CODE, INVOICE_NO,ORDER_NO) I',
'          ',
'       WHERE  C.CUSTOMER_NO = O.CUSTOMER_NO AND I.ORDER_NO = O.ORDER_NO',
' AND  O.ORDER_NO = :P17_ORDER_NO;'))
,p_is_editable=>true
,p_edit_operations=>'i:u:d'
,p_lost_update_check_type=>'VALUES'
,p_plug_source_type=>'NATIVE_FORM'
,p_updated_on=>wwv_flow_imp.dz('20260909131730Z')
,p_updated_by=>'ADMIN'
);
