,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'items_to_return', 'P17_CUSTOMER_NO,P17_CUSTOMER_NAME,P17_ADDRESS',
  'items_to_submit', 'P17_MOBILE_NO',
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'BEGIN',
    '',
    '    -- First clear old values',
    '    :P17_CUSTOMER_NO      := NULL;',
    '    :P17_CUSTOMER_NAME    := NULL;',
    '    :P17_DELIVERY_ADDRESS := NULL;',
    '',
    '    BEGIN',
    '        SELECT CUSTOMER_NO,',
    '               CUSTOMER_NAME,',
    '               ADDRESS',
    '          INTO :P17_CUSTOMER_NO,',
    '               :P17_CUSTOMER_NAME,',
    '               :P17_DELIVERY_ADDRESS',
    '          FROM (',
    '                SELECT CUSTOMER_NO,',
    '                       CUSTOMER_NAME,',
    '                       ADDRESS',
    '                  FROM MST_CUSTOMER',
    '                 WHERE MOBILE_NO = :P17_MOBILE_NO',
    '                   AND NVL(ACTIVE_FLAG, 1) = 1',
    '                 ORDER BY CUSTOMER_NO DESC',
    '               )',
    '         WHERE ROWNUM = 1;',
    '',
    '    EXCEPTION',
    '        WHEN NO_DATA_FOUND THEN',
    '            NULL;',
    '    END;',
    '',
    'END;')),
  'show_processing', 'N',
  'suppress_change_event', 'N')).to_clob
,p_wait_for_result=>'Y'
,p_updated_on=>wwv_flow_imp.dz('20260909130010Z')
