,p_execute_on_page_init=>'N'
,p_static_id=>'native-javascript-code'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'setTimeout(function () {',
    '',
    '    var model = apex.region(''sales_dtl'')',
    '        .widget()',
    '        .interactiveGrid(''getViews'', ''grid'')',
    '        .model;',
    '',
    '    var totalAmount = 0;',
    '    var totalDiscount = 0;',
    '',
    '    model.forEach(function (record) {',
    '',
    '        var rate = parseFloat(',
    '            model.getValue(record, ''SALES_RATE'')',
    '        ) || 0;',
    '',
    '        var qty = parseFloat(',
    '            model.getValue(record, ''ORDER_QTY'')',
    '        ) || 0;',
    '',
    '        var discount = parseFloat(',
    '            model.getValue(record, ''DISCOUNT_AMOUNT'')',
    '        ) || 0;',
    '',
    unistr('        // Rate \00D7 Qty'),
    '        totalAmount += rate * qty;',
    '',
    '        // Total Discount',
    '        totalDiscount += discount;',
    '    });',
    '',
    '    var payableAmount = totalAmount - totalDiscount;',
    '',
    '    $s(',
    '        ''P17_TOTAL_ORDER_AMOUNT'',',
    '        totalAmount.toFixed(2)',
    '    );',
    '',
    '    $s(',
    '        ''P17_TOTAL_DISCOUNT'',',
    '        totalDiscount.toFixed(2)',
    '    );',
    '',
    '    $s(',
    '        ''P17_PAYABLE_AMOUNT'',',
    '        payableAmount.toFixed(2)',
    '    );',
    '',
    '}, 100);')))).to_clob
,p_created_on=>wwv_flow_imp.dz('20260909125221Z')
,p_updated_on=>wwv_flow_imp.dz('20260909125221Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
