wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(15309683437803527)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'ADD_TO_CART_PRODUCT'
,p_static_id=>'add-to-cart-product'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 9/8/2026 5:08:07 PM (QP5 v5.388) */',
'DECLARE',
'    V_DATA   CLOB;',
'BEGIN',
'    SELECT JSON_ARRAYAGG (',
'               JSON_OBJECT (',
'                   /* =========================================',
'                      PRODUCT INFORMATION',
'                   ========================================= */',
'',
'                   ''PRODUCT_NO'' VALUE P.PRODUCT_NO,',
'                   ''PRODUCT_CODE'' VALUE P.PRODUCT_CODE,',
'                   ''PRODUCT_NAME'' VALUE P.PRODUCT_NAME,',
'                   ''DESCRIPTION'' VALUE P.DESCRIPTION,',
'                   /* =========================================',
'                      UOM',
'                   ========================================= */',
'',
'                   ''UOM_NO'' VALUE P.UOM_NO,',
'                   ''UOM_NAME'' VALUE U.UOM_NAME,',
'                   /* =========================================',
'                      QUANTITY',
'                   ========================================= */',
'',
'                   ''ORDER_QTY'' VALUE 1,',
'                   ''PACK_QTY'' VALUE  1,',
'                  ''BASE_QTY'' VALUE 1,',
'                   /* =========================================',
'                      SALES RATE',
'                   ========================================= */',
'',
'                   ''SALES_RATE'' VALUE NVL (CP.SALES_RATE, 0),',
'                   ''BASE_RATE'' VALUE NVL (CP.SALES_RATE, 0),',
'',
'                   /* =========================================',
'                      STOCK',
'                   ========================================= */',
'',
'                   ''STOCK_QTY'' VALUE NVL (S.STOCK_QTY, 0),',
'                   /* =========================================',
'                      DISCOUNT %',
'                   ========================================= */',
'',
'                   ''DISCOUNT_PERCENT'' VALUE',
'                       NVL (',
'                           (SELECT DISCOUNT_PERCENT',
'                             FROM (  SELECT D.DISCOUNT_PERCENT',
'                                       FROM MST_DISCOUNT_CONFIG D',
'                                      WHERE     D.ACTIVE_FLAG = 1',
'                                            AND SYSDATE >= D.EFFECTIVE_FROM',
'                                            AND (   D.EFFECTIVE_TO IS NULL',
'                                                 OR SYSDATE <= D.EFFECTIVE_TO)',
'                                            AND (   D.PRODUCT_NO IS NULL',
'                                                 OR D.PRODUCT_NO = P.PRODUCT_NO)',
'                                            AND (   D.CATEGORY_NO IS NULL',
'                                                 OR D.CATEGORY_NO =',
'                                                    P.CATEGORY_NO)',
'                                            AND (   D.CUSTOMER_NO IS NULL',
'                                                 OR D.CUSTOMER_NO =',
'                                                    APEX_APPLICATION.G_X02)',
'                                   ORDER BY D.PRIORITY DESC,',
'                                            D.DISCOUNT_CONFIG_NO DESC)',
'                            WHERE ROWNUM = 1),',
'                           0),',
'                   /* =========================================',
'                      DISCOUNT AMOUNT',
'',
unistr('                      Gross = ORDER_QTY \00D7 SALES_RATE'),
unistr('                      Discount = Gross \00D7 Discount% / 100'),
'                   ========================================= */',
'',
'                   ''DISCOUNT_AMOUNT'' VALUE',
'                       ROUND (',
'                             (1 * NVL (CP.SALES_RATE, 0))',
'                           * NVL (',
'                                 (SELECT DISCOUNT_PERCENT',
'                                   FROM (  SELECT D.DISCOUNT_PERCENT',
'                                             FROM MST_DISCOUNT_CONFIG D',
'                                            WHERE     D.ACTIVE_FLAG = 1',
'                                                  AND SYSDATE >=',
'                                                      D.EFFECTIVE_FROM',
'                                                  AND (   D.EFFECTIVE_TO',
'                                                              IS NULL',
'                                                       OR SYSDATE <=',
'                                                          D.EFFECTIVE_TO)',
'                                                  AND (   D.PRODUCT_NO IS NULL',
'                                                       OR D.PRODUCT_NO =',
'                                                          P.PRODUCT_NO)',
'                                                  AND (   D.CATEGORY_NO IS NULL',
'                                                       OR D.CATEGORY_NO =',
'                                                          P.CATEGORY_NO)',
'                                                  AND (   D.CUSTOMER_NO IS NULL',
'                                                       OR D.CUSTOMER_NO =',
'                                                          APEX_APPLICATION.G_X02)',
'                                         ORDER BY D.PRIORITY DESC,',
'                                                  D.DISCOUNT_CONFIG_NO DESC)',
'                                  WHERE ROWNUM = 1),',
'                                 0)',
'                           / 100,',
'                           2),',
'                   /* =========================================',
'                      TOTAL AMOUNT',
'',
'                      Gross - Discount',
'                   ========================================= */',
'',
'                   ''TOTAL_AMOUNT'' VALUE',
'                       ROUND (',
'                             (1 * NVL (CP.SALES_RATE, 0))',
'                           - (  (1 * NVL (CP.SALES_RATE, 0))',
'                              * NVL (',
'                                    (SELECT DISCOUNT_PERCENT',
'                                      FROM (  SELECT D.DISCOUNT_PERCENT',
'                                                FROM MST_DISCOUNT_CONFIG D',
'                                               WHERE     D.ACTIVE_FLAG = 1',
'                                                     AND SYSDATE >=',
'                                                         D.EFFECTIVE_FROM',
'                                                     AND (   D.EFFECTIVE_TO',
'                                                                 IS NULL',
'                                                          OR SYSDATE <=',
'                                                             D.EFFECTIVE_TO)',
'                                                     AND (   D.PRODUCT_NO',
'                                                                 IS NULL',
'                                                          OR D.PRODUCT_NO =',
'                                                             P.PRODUCT_NO)',
'                                                     AND (   D.CATEGORY_NO',
'                                                                 IS NULL',
'                                                          OR D.CATEGORY_NO =',
'                                                             P.CATEGORY_NO)',
'                                                     AND (   D.CUSTOMER_NO',
'                                                                 IS NULL',
'                                                          OR D.CUSTOMER_NO =',
'                                                             APEX_APPLICATION.G_X02)',
'                                            ORDER BY D.PRIORITY DESC,',
'                                                     D.DISCOUNT_CONFIG_NO DESC)',
'                                     WHERE ROWNUM = 1),',
'                                    0)',
'                              / 100),',
'                           2)',
'                   RETURNING CLOB)',
'               RETURNING CLOB)',
'      INTO V_DATA',
'      FROM MST_PRODUCT  P',
'           JOIN MST_UOM U ON U.UOM_NO = P.UOM_NO AND U.ACTIVE_FLAG = ''1''',
'           /* =========================================',
'              CURRENT SALES PRICE',
'           ========================================= */',
'',
'           LEFT JOIN',
'           (SELECT PRODUCT_NO,',
'                   UOM_NO,',
'                   SALES_RATE,',
'                   ROW_NUMBER ()',
'                       OVER (',
'                           PARTITION BY PRODUCT_NO, UOM_NO',
'                           ORDER BY EFFECTIVE_DATE DESC, SALES_PRICE_NO DESC)    RN',
'              FROM MST_SALES_PRICE',
'             WHERE ACTIVE_FLAG = ''1'' AND EFFECTIVE_DATE <= SYSDATE) CP',
'               ON     CP.PRODUCT_NO = P.PRODUCT_NO',
'                  AND CP.UOM_NO = P.UOM_NO',
'                  AND CP.RN = 1',
'           /* =========================================',
'              CURRENT STOCK',
'           ========================================= */',
'',
'           LEFT JOIN',
'           (  SELECT PRODUCT_NO,',
'                     SUM (NVL (QTY_IN, 0)) - SUM (NVL (QTY_OUT, 0))    AS STOCK_QTY',
'                FROM TRN_STOCK_LEDGER',
'            GROUP BY PRODUCT_NO) S',
'               ON S.PRODUCT_NO = P.PRODUCT_NO',
'     WHERE P.PRODUCT_NO = APEX_APPLICATION.G_X01 AND P.ACTIVE_FLAG = 1;',
'',
'    HTP.PRN (NVL (V_DATA, ''[]''));',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>15309683437803527
,p_created_on=>wwv_flow_imp.dz('20260908154817Z')
,p_updated_on=>wwv_flow_imp.dz('20260908171450Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(15160183944336121)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_PRODUCT_DISCOUNT'
,p_static_id=>'get-product-discount'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 9/7/2026 2:43:29 PM (QP5 v5.388) */',
'DECLARE',
'    V_DISCOUNT_PERCENT   NUMBER := 0;',
'BEGIN',
'    SELECT DISCOUNT_PERCENT',
'      INTO V_DISCOUNT_PERCENT',
'      FROM (  SELECT D.DISCOUNT_PERCENT',
'                FROM MST_DISCOUNT_CONFIG D',
'                     JOIN MST_PRODUCT P',
'                         ON P.PRODUCT_NO = APEX_APPLICATION.G_X01',
'               WHERE     D.ACTIVE_FLAG = 1',
'                     AND SYSDATE >= D.EFFECTIVE_FROM',
'                     AND (D.EFFECTIVE_TO IS NULL OR SYSDATE <= D.EFFECTIVE_TO)',
'                     AND (   D.PRODUCT_NO IS NULL',
'                          OR D.PRODUCT_NO = APEX_APPLICATION.G_X01)',
'                     AND (   D.CATEGORY_NO IS NULL',
'                          OR D.CATEGORY_NO = P.CATEGORY_NO)',
'                     AND (   D.CUSTOMER_NO IS NULL',
'                          OR D.CUSTOMER_NO = APEX_APPLICATION.G_X02)',
'            ORDER BY D.PRIORITY DESC, D.DISCOUNT_CONFIG_NO DESC)',
'     WHERE ROWNUM = 1;',
'',
'    HTP.P (V_DISCOUNT_PERCENT);',
'EXCEPTION',
'    WHEN NO_DATA_FOUND',
'    THEN',
'        HTP.P (''0'');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>15160183944336121
,p_created_on=>wwv_flow_imp.dz('20260907144557Z')
,p_updated_on=>wwv_flow_imp.dz('20260907144557Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
