 p_id=>wwv_flow_imp.id(12958453123941850809)
,p_plug_name=>'Delivery Challan Print'
,p_static_id=>'delivery-challan-print'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4502917002193490937
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'    v_total NUMBER := 0;',
'',
'BEGIN',
'',
'FOR h IN',
'(',
'    SELECT D.DELIVERY_CODE,',
'           TO_CHAR(D.DELIVERY_DATE,''DD-MON-YYYY'') DELIVERY_DATE,',
'           I.INVOICE_CODE,',
'           C.CUSTOMER_NAME,',
'           D.DELIVERY_ADDRESS,',
'           D.CONTACT_NO,',
'           D.VEHICLE_NO,',
'           D.DELIVERY_PERSON,',
'           D.REMARKS',
'      FROM TRN_DELIVERY_MST D',
'      JOIN TRN_SALES_INVOICE_MST I',
'        ON I.INVOICE_NO = D.INVOICE_NO',
'      JOIN MST_CUSTOMER C',
'        ON C.CUSTOMER_NO = D.CUSTOMER_NO',
'     WHERE D.DELIVERY_NO = :P20_DELIVERY_NO',
')',
'LOOP',
'',
'HTP.P(q''~',
'',
'<style>',
'',
'body{',
'    font-family:Segoe UI,Arial;',
'    font-size:13px;',
'    margin:25px;',
'    color:#222;',
'}',
'',
'.toolbar{',
'    text-align:right;',
'    margin-bottom:15px;',
'}',
'',
'.btn{',
'    border:none;',
'    padding:6px 12px;',
'    border-radius:4px;',
'    color:#fff;',
'    cursor:pointer;',
'    font-size:12px;',
'    font-weight:600;',
'}',
'',
'.print-btn{',
'    background:#1f4e79;',
'}',
'',
'.close-btn{',
'    background:#6b7280;',
'}',
'',
