 p_id=>wwv_flow_imp.id(15523754058055431214)
,p_name=>'CONVERT_UOM_NO'
,p_source_type=>'DB_COLUMN'
,p_source_expression=>'CONVERT_UOM_NO'
,p_data_type=>'NUMBER'
,p_session_state_data_type=>'VARCHAR2'
,p_is_query_only=>false
,p_item_type=>'NATIVE_SELECT_LIST'
,p_heading=>'Convert Uom No'
,p_heading_alignment=>'LEFT'
,p_display_sequence=>60
,p_value_alignment=>'LEFT'
,p_is_required=>false
,p_lov_type=>'SQL_QUERY'
,p_lov_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT U.UOM_NAME D,',
'       U.UOM_NO   R',
'FROM MST_UOM U',
'WHERE U.ACTIVE_FLAG = ''1''',
'  AND U.UOM_NO <>',
'      (',
'          SELECT P.UOM_NO',
'            FROM MST_PRODUCT P',
'           WHERE P.PRODUCT_NO = :P24_PRODUCT_NO',
'      )',
'--   AND NOT EXISTS',
'--       (',
'--           SELECT 1',
'--             FROM MST_UOM_CONVERSION C',
'--            WHERE C.PRODUCT_NO = :P24_PRODUCT_NO',
'--              AND C.CONVERT_UOM_NO = U.UOM_NO',
'--              AND C.CONVERSION_NO <> NVL(:CONVERSION_NO,0)',
'--       )',
'ORDER BY U.UOM_NAME;'))
,p_lov_display_extra=>false
,p_lov_display_null=>true
,p_lov_null_text=>'--Select--'
,p_lov_cascade_parent_items=>'P24_PRODUCT_NO'
