wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(15523475483239392654)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form Entry'
,p_static_id=>'process-form-entry'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :P24_PRODUCT_NO IS NULL THEN',
'        INSERT INTO MST_PRODUCT (',
'            PRODUCT_NO,',
'            CATEGORY_NO,',
'            PRODUCT_CODE,',
'            PRODUCT_NAME,',
'            PURCHASE_RATE,',
'            SALES_RATE,',
'            MIN_STOCK_QTY,',
'            ACTIVE_FLAG,',
'            UOM_NO,',
'            CREATED_BY,',
'            CREATED_DATE',
'        )',
'        VALUES (',
'            SEQ_PRODUCT_NO.NEXTVAL,',
'            :P24_CATEGORY_NO,',
'           ''PRD'' || LPAD(SEQ_PRODUCT_NO.NEXTVAL,4,''0''),',
'            :P24_PRODUCT_NAME,',
'            :P24_PURCHASE_RATE,',
'            :P24_SALES_RATE,',
'            :P24_MIN_STOCK_QTY,',
'            :P24_ACTIVE_FLAG,',
'            :P24_UOM_NO,',
'            :APP_USER,',
'            SYSDATE',
'        );',
'',
'          APEX_APPLICATION.g_print_success_message :=',
'            ''Product has been saved successfully.'';',
'    ELSE',
'        UPDATE MST_PRODUCT',
'           SET CATEGORY_NO   = :P24_CATEGORY_NO,',
'               PRODUCT_NAME  = :P24_PRODUCT_NAME,',
'               PURCHASE_RATE = :P24_PURCHASE_RATE,',
'               SALES_RATE    = :P24_SALES_RATE,',
'               MIN_STOCK_QTY = :P24_MIN_STOCK_QTY,',
'               ACTIVE_FLAG   = :P24_ACTIVE_FLAG,',
'               UOM_NO        = :P24_UOM_NO,',
'               UPDATED_BY    = :APP_USER,',
'               UPDATED_DATE  = SYSDATE',
'         WHERE PRODUCT_NO    = :P24_PRODUCT_NO;',
'',
'         ',
'        APEX_APPLICATION.g_print_success_message :=',
'            ''Product has been updated successfully.'';',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(15523348804850748168)
,p_internal_uid=>15523475483239392654
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(15523754958297431223)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(15523753538955431209)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'UOM Conversion - Save Interactive Grid Data'
,p_static_id=>'uom-conversion-save-interactive-grid-data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 9/2/2026 11:53:28 AM (QP5 v5.388) */',
'BEGIN',
'    ---------------------------------------------------',
'    -- PRODUCT VALIDATION',
'    ---------------------------------------------------',
'',
'    IF :P24_PRODUCT_NO IS NULL',
'    THEN',
'        RAISE_APPLICATION_ERROR (-20001,',
'                                 ''Please save product information first.'');',
'    END IF;',
'',
'',
'    ---------------------------------------------------',
'    -- DELETE',
'    ---------------------------------------------------',
unistr('    -- Delete \0995\09B0\09BE\09B0 \09B8\09AE\09DF \0985\09A8\09CD\09AF validation \0995\09B0\09BE\09B0 \09A6\09B0\0995\09BE\09B0 \09A8\09C7\0987.'),
'    ---------------------------------------------------',
'',
'    IF :APEX$ROW_STATUS = ''D''',
'    THEN',
'        DELETE FROM MST_UOM_CONVERSION',
'              WHERE CONVERSION_NO = :CONVERSION_NO;',
'',
'        RETURN;',
'    END IF;',
'',
'',
'    ---------------------------------------------------',
'    -- UOM VALIDATION',
'    ---------------------------------------------------',
'',
'    IF :CONVERT_UOM_NO IS NULL',
'    THEN',
'        RAISE_APPLICATION_ERROR (-20001, ''Please select UOM.'');',
'    END IF;',
'',
'',
'    ---------------------------------------------------',
'    -- CONVERSION FACTOR VALIDATION',
'    ---------------------------------------------------',
'',
'    IF NVL ( :CONVERSION_FACTOR, 0) <= 0',
'    THEN',
'        RAISE_APPLICATION_ERROR (',
'            -20001,',
'            ''Conversion factor must be greater than zero.'');',
'    END IF;',
'',
'',
'    ---------------------------------------------------',
'    -- GET BASE UOM',
'    ---------------------------------------------------',
'',
'    DECLARE',
'        V_BASE_UOM   NUMBER;',
'    BEGIN',
'        SELECT UOM_NO',
'          INTO V_BASE_UOM',
'          FROM MST_PRODUCT',
'         WHERE PRODUCT_NO = :P24_PRODUCT_NO;',
'',
'',
'        ---------------------------------------------------',
'        -- BASE UOM CANNOT BE CONVERSION UOM',
'        ---------------------------------------------------',
'',
'        IF :CONVERT_UOM_NO = V_BASE_UOM',
'        THEN',
'            RAISE_APPLICATION_ERROR (',
'                -20001,',
'                ''Base UOM cannot be added as conversion UOM.'');',
'        END IF;',
'',
'',
'        ---------------------------------------------------',
'        -- INSERT',
'        ---------------------------------------------------',
'',
'        IF :APEX$ROW_STATUS = ''C''',
'        THEN',
'            DECLARE',
'                V_CNT   NUMBER;',
'            BEGIN',
'                SELECT COUNT (*)',
'                  INTO V_CNT',
'                  FROM MST_UOM_CONVERSION',
'                 WHERE     PRODUCT_NO = :P24_PRODUCT_NO',
'                       AND CONVERT_UOM_NO = :CONVERT_UOM_NO;',
'',
'                IF V_CNT > 0',
'                THEN',
'                    RAISE_APPLICATION_ERROR (',
'                        -20001,',
'                        ''This UOM already exists for the selected product.'');',
'                END IF;',
'            END;',
'',
'',
'            INSERT INTO MST_UOM_CONVERSION (CONVERSION_NO,',
'                                            PRODUCT_NO,',
'                                            BASE_UOM_NO,',
'                                            CONVERT_UOM_NO,',
'                                            CONVERSION_FACTOR,',
'                                            ACTIVE_FLAG,',
'                                            CREATED_BY,',
'                                            CREATED_DATE)',
'                 VALUES (SEQ_UOM_CONVERSION_NO.NEXTVAL,',
'                         :P24_PRODUCT_NO,',
'                         V_BASE_UOM,',
'                         :CONVERT_UOM_NO,',
'                         :CONVERSION_FACTOR,',
'                         ''1'',',
'                         :APP_USER,',
'                         SYSDATE)',
'              RETURNING CONVERSION_NO',
'                   INTO :CONVERSION_NO;',
'        ---------------------------------------------------',
'        -- UPDATE',
'        ---------------------------------------------------',
'',
'        ELSIF :APEX$ROW_STATUS = ''U''',
'        THEN',
'            DECLARE',
'                V_CNT   NUMBER;',
'            BEGIN',
'                /*',
'                   Check duplicate UOM excluding',
'                   the current row being updated.',
'                */',
'',
'                SELECT COUNT (*)',
'                  INTO V_CNT',
'                  FROM MST_UOM_CONVERSION',
'                 WHERE     PRODUCT_NO = :P24_PRODUCT_NO',
'                       AND CONVERT_UOM_NO = :CONVERT_UOM_NO',
'                       AND CONVERSION_NO <> :CONVERSION_NO;',
'',
'',
'                IF V_CNT > 0',
'                THEN',
'                    RAISE_APPLICATION_ERROR (',
'                        -20001,',
'                        ''This UOM already exists for the selected product.'');',
'                END IF;',
'            END;',
'',
'',
'            UPDATE MST_UOM_CONVERSION',
'               SET BASE_UOM_NO = V_BASE_UOM,',
'                   CONVERT_UOM_NO = :CONVERT_UOM_NO,',
'                   CONVERSION_FACTOR = :CONVERSION_FACTOR,',
'                   UPDATED_BY = :APP_USER,',
'                   UPDATED_DATE = SYSDATE',
'             WHERE CONVERSION_NO = :CONVERSION_NO;',
'        END IF;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND',
'        THEN',
'            RAISE_APPLICATION_ERROR (-20001,',
'                                     ''Product information not found.'');',
'    END;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>15523754958297431223
);
end;
/
