wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(11768569861204325)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'DELETE'
,p_static_id=>'delete'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 8/29/2026 3:47:44 PM (QP5 v5.388) */',
'BEGIN',
'    DECLARE',
'        l_due_count   NUMBER := 0;',
'        l_dep_count   NUMBER := 0;',
'    BEGIN',
'        SELECT COUNT (*)',
'          INTO l_due_count',
'          FROM TRN_SALES_INVOICE_MST',
'         WHERE CUSTOMER_NO = :P25_CUSTOMER_NO AND NVL (DUE_AMOUNT, 0) > 0;',
'',
'        IF l_due_count > 0',
'        THEN',
'            RAISE_APPLICATION_ERROR (',
'                -20001,',
'                ''Customer cannot be deleted because an outstanding due amount exists.'');',
'        END IF;',
'',
'        SELECT COUNT (*)',
'          INTO l_dep_count',
'          FROM (SELECT 1',
'                  FROM TRN_SALES_ORDER_MST',
'                 WHERE CUSTOMER_NO = :P25_CUSTOMER_NO',
'                UNION ALL',
'                SELECT 1',
'                  FROM TRN_SALES_INVOICE_MST',
'                 WHERE CUSTOMER_NO = :P25_CUSTOMER_NO',
'                UNION ALL',
'                SELECT 1',
'                  FROM TRN_CUSTOMER_RETURN_MST',
'                 WHERE CUSTOMER_NO = :P25_CUSTOMER_NO);',
'',
'        IF l_dep_count > 0',
'        THEN',
'            RAISE_APPLICATION_ERROR (',
'                -20002,',
'                ''Customer cannot be deleted because related sales/return data exists.'');',
'        END IF;',
'',
'        DELETE FROM MST_CUSTOMER',
'              WHERE CUSTOMER_NO = :P25_CUSTOMER_NO;',
'',
'        APEX_APPLICATION.g_print_success_message :=',
'            ''Customer information has been deleted successfully.'';',
'',
'        :P25_CUSTOMER_NO := NULL;',
'    END;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(11753917149204285)
,p_internal_uid=>11768569861204325
,p_created_on=>wwv_flow_imp.dz('20260828205916Z')
,p_updated_on=>wwv_flow_imp.dz('20260829154820Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
