wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(11768145005204325)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form Entry'
,p_static_id=>'process-form-entry'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 8/29/2026 3:49:40 PM (QP5 v5.388) */',
'BEGIN',
'    IF :P25_CUSTOMER_NO IS NULL',
'    THEN',
'        INSERT INTO MST_CUSTOMER (CUSTOMER_NO,',
'                                  CUSTOMER_CODE,',
'                                  CUSTOMER_NAME,',
'                                  CONTACT_PERSON,',
'                                  MOBILE_NO,',
'                                  EMAIL_ADDRESS,',
'                                  ADDRESS,',
'                                  ACTIVE_FLAG,',
'                                  CREATED_BY,',
'                                  CREATED_DATE)',
'             VALUES (SEQ_CUSTOMER_NO.NEXTVAL,',
'                     ''CUS'' || LPAD (SEQ_CUSTOMER_NO.NEXTVAL, 4, ''0''),',
'                     :P25_CUSTOMER_NAME,',
'                     :P25_CONTACT_PERSON,',
'                     :P25_MOBILE_NO,',
'                     :P25_EMAIL_ADDRESS,',
'                     :P25_ADDRESS,',
'                     NVL ( :P25_ACTIVE_FLAG, ''Y''),',
'                     :APP_USER,',
'                     SYSDATE);',
'',
'        APEX_APPLICATION.g_print_success_message :=',
'            ''Customer information has been saved successfully.'';',
'    ELSE',
'        DECLARE',
'            l_due_count   NUMBER := 0;',
'            l_dep_count   NUMBER := 0;',
'        BEGIN',
'            -- Prevent inactive if customer still has due or dependent records',
'            IF NVL ( :P25_ACTIVE_FLAG, ''1'') =''0''',
'            THEN',
'                SELECT COUNT (*)',
'                  INTO l_due_count',
'                  FROM TRN_SALES_INVOICE_MST',
'                 WHERE     CUSTOMER_NO = :P25_CUSTOMER_NO',
'                       AND NVL (DUE_AMOUNT, 0) > 0;',
'',
'                IF l_due_count > 0',
'                THEN',
'                    RAISE_APPLICATION_ERROR (',
'                        -20001,',
'                        ''Customer cannot be made inactive because an outstanding due amount exists.'');',
'                END IF;',
'',
'                SELECT COUNT (*)',
'                  INTO l_dep_count',
'                  FROM (SELECT 1',
'                          FROM TRN_SALES_ORDER_MST',
'                         WHERE CUSTOMER_NO = :P25_CUSTOMER_NO',
'                        UNION ALL',
'                        SELECT 1',
'                          FROM TRN_SALES_INVOICE_MST',
'                         WHERE CUSTOMER_NO = :P25_CUSTOMER_NO',
'                        UNION ALL',
'                        SELECT 1',
'                          FROM TRN_CUSTOMER_RETURN_MST',
'                         WHERE CUSTOMER_NO = :P25_CUSTOMER_NO);',
'',
'                IF l_dep_count > 0',
'                THEN',
'                    RAISE_APPLICATION_ERROR (',
'                        -20002,',
'                        ''Customer cannot be made inactive because related sales/return records exist.'');',
'                END IF;',
'            END IF;',
'',
'            UPDATE MST_CUSTOMER',
'               SET CUSTOMER_NAME = :P25_CUSTOMER_NAME,',
'                   CONTACT_PERSON = :P25_CONTACT_PERSON,',
'                   MOBILE_NO = :P25_MOBILE_NO,',
'                   EMAIL_ADDRESS = :P25_EMAIL_ADDRESS,',
'                   ADDRESS = :P25_ADDRESS,',
'                   ACTIVE_FLAG = :P25_ACTIVE_FLAG,',
'                   UPDATED_BY = :APP_USER,',
'                   UPDATED_DATE = SYSDATE',
'             WHERE CUSTOMER_NO = :P25_CUSTOMER_NO;',
'',
'            APEX_APPLICATION.g_print_success_message :=',
'                ''Customer information has been updated successfully.'';',
'        END;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(11754364653204285)
,p_internal_uid=>11768145005204325
,p_created_on=>wwv_flow_imp.dz('20260828205916Z')
,p_updated_on=>wwv_flow_imp.dz('20260829155109Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
end;
/
