wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(24146358014197685)
,p_plug_name=>'ADDRESS'
,p_static_id=>'address'
,p_parent_plug_id=>wwv_flow_imp.id(23088337779184023)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4502917002193490937
,p_plug_display_sequence=>1
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_html CLOB := '''';',
'    l_url  VARCHAR2(4000);',
'',
'    l_customer_name MST_CUSTOMER.CUSTOMER_NAME%TYPE;',
'    l_customer_code MST_CUSTOMER.CUSTOMER_CODE%TYPE;',
'    l_mobile_no     MST_CUSTOMER.MOBILE_NO%TYPE;',
'    l_address       MST_CUSTOMER.ADDRESS%TYPE;',
'BEGIN',
'',
'    /* =====================================================',
'       GET CUSTOMER INFORMATION',
'       ===================================================== */',
'',
'    SELECT',
'        SUPPLIER_NAME,',
'        SUPPLIER_CODE,',
'        MOBILE_NO,',
'        ADDRESS',
'    INTO',
'        l_customer_name,',
'        l_customer_code,',
'        l_mobile_no,',
'        l_address',
'    FROM MST_SUPPLIER',
'    WHERE SUPPLIER_NO = :P27_PARTY_NO',
'      AND ACTIVE_FLAG = ''1'';',
'',
'',
'    /* =====================================================',
'       PAGE 25 URL',
'       ===================================================== */',
'',
'    l_url := apex_page.get_url(',
'        p_page   => 25,',
'        p_items  => ''P25_CUSTOMER_NO'',',
'        p_values => :P27_PARTY_NO',
'    );',
'',
'',
'    /* =====================================================',
'       HTML',
'       ===================================================== */',
'',
'    l_html := ''',
'',
'    <div class="receive-card">',
'',
'',
'        <!-- =================================================',
'             LEFT : SUPPLIER / ADDRESS',
'             ================================================= -->',
'',
'        <div class="customer-section">',
'',
'            <div class="customer-main">',
'',
'',
'                <!-- HOME -->',
'',
'                <div class="home-badge">',
'',
'                    <i class="fa fa-home"></i>',
'',
'                    <span>',
'                        Home',
'                    </span>',
'',
'                </div>',
'',
'',
'                <!-- CUSTOMER INFO -->',
'',
'                <div class="customer-info">',
'',
'                    <div class="customer-name">',
'                        '' ||',
'                        apex_escape.html(l_customer_name) ||',
'                        ''',
'                    </div>',
'',
'                    <div class="customer-phone">',
'                        '' ||',
'                        apex_escape.html(l_mobile_no) ||',
'                        ''',
'                    </div>',
'',
'                </div>',
'',
'            </div>',
'',
'',
'            <!-- ADDRESS -->',
'',
'            <div class="address-bottom">',
'',
'                <span class="customer-address">',
'',
'                    '' ||',
'                    apex_escape.html(',
'                        NVL(',
'                            l_address,',
'                            ''No delivery address available''',
'                        )',
'                    ) ||',
'                    ''',
'',
'                </span>',
'',
'',
'                <a href="'' ||',
'                    apex_escape.html_attribute(l_url) ||',
'                    ''"',
'                   class="change-address">',
'',
'                    Change address &gt;',
'',
'                </a>',
'',
'            </div>',
'',
'        </div>',
'',
'',
'',
'        <!-- =================================================',
'             MIDDLE : SUPPLIER RECEIVE',
'             ================================================= -->',
'',
'        <div class="receive-section">',
'',
'            <div class="receive-title">',
'                Supplier Payment',
'            </div>',
'',
'            <div class="receive-subtitle">',
'                Payment Supplier Against Purchase Invoice',
'            </div>',
'',
'        </div>',
'',
'',
'',
'        <!-- =================================================',
'             RIGHT : DELIVERY ADDRESS',
'             ================================================= -->',
'',
'        <div class="delivery-section">',
'',
'',
'            <div class="delivery-title">',
'',
'                <i class="fa fa-map-marker"></i>',
'',
'                <span>',
'                    Select a delivery address',
'                </span>',
'',
'            </div>',
'',
'',
'            <a href="'' ||',
'                apex_escape.html_attribute(l_url) ||',
'                ''"',
'               class="add-address-btn">',
'',
'                <span class="add-icon">+</span>',
'',
'                <span>',
'                    Add address',
'                </span>',
'',
'            </a>',
'',
'        </div>',
'',
'',
'    </div>'';',
'',
'',
'',
'    RETURN l_html;',
'',
'',
'',
'EXCEPTION',
'',
'    WHEN NO_DATA_FOUND THEN',
'',
'        RETURN ''',
'',
'        <div class="receive-card">',
'',
'',
'            <!-- LEFT -->',
'',
'            <div class="customer-section">',
'',
'                <div class="customer-main">',
'',
'                    <div class="home-badge">',
'',
'                        <i class="fa fa-home"></i>',
'',
'                        <span>',
'                            Home',
'                        </span>',
'',
'                    </div>',
'',
'                    <div class="customer-info">',
'',
'                        <div class="customer-name">',
'                            No Supplier',
'                        </div>',
'',
'                        <div class="customer-phone">',
'                            -',
'                        </div>',
'',
'                    </div>',
'',
'                </div>',
'',
'',
'                <div class="address-bottom">',
'',
'                    <span class="customer-address">',
'                        Please select a Supplier',
'                    </span>',
'',
'                </div>',
'',
'            </div>',
'',
'',
'',
'            <!-- MIDDLE -->',
'',
'            <div class="receive-section">',
'',
'                <div class="receive-title">',
'                   Supplier Payment',
'                </div>',
'',
'                <div class="receive-subtitle">',
'                    Payment Supplier Against Purchase Invoice',
'                </div>',
'',
'            </div>',
'',
'',
'',
'            <!-- RIGHT -->',
'',
'            <div class="delivery-section">',
'',
'                <div class="delivery-title">',
'',
'                    <i class="fa fa-map-marker"></i>',
'',
'                    <span>',
'                        Select a delivery address',
'                    </span>',
'',
'                </div>',
'',
'                <span class="add-address-btn disabled">',
'',
'                    <span class="add-icon">+</span>',
'',
'                    Add address',
'',
'                </span>',
'',
'            </div>',
'',
'',
'        </div>'';',
'',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P27_PARTY_NO'
,p_created_on=>wwv_flow_imp.dz('20260830173052Z')
,p_updated_on=>wwv_flow_imp.dz('20260830182540Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
