,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT * FROM (SELECT',
'       M.VOUCHER_NO,',
'',
'       M.VOUCHER_CODE,',
'',
'       M.VOUCHER_DATE,',
'',
'       M.VOUCHER_TYPE,',
'',
'       M.NARRATION,',
'',
'       (',
'           SELECT NVL(SUM(DEBIT_AMOUNT),0)',
'           FROM ACC_VOUCHER_DTL D',
'           WHERE D.VOUCHER_NO = M.VOUCHER_NO',
'       ) TOTAL_DEBIT,',
'',
'       (',
'           SELECT NVL(SUM(CREDIT_AMOUNT),0)',
'           FROM ACC_VOUCHER_DTL D',
'           WHERE D.VOUCHER_NO = M.VOUCHER_NO',
'       ) TOTAL_CREDIT,',
'',
'       CASE M.APPROVAL_STATUS',
'',
'           WHEN ''A'' THEN',
'               ''<span class="t-Badge t-Badge--success">',
'                Approved',
'                </span>''',
'',
'           WHEN ''P'' THEN',
'               ''<span class="t-Badge t-Badge--warning">',
'                Pending',
'                </span>''',
'',
'           WHEN ''R'' THEN',
'               ''<span class="t-Badge t-Badge--danger">',
'                Rejected',
'                </span>''',
'',
'       END STATUS,',
'',
'       M.CREATED_BY,',
'',
'       M.CREATED_DATE,',
'NULL VIEW_BTN',
'',
'FROM ACC_VOUCHER_MST M',
'',
'WHERE (:P28_FROM_DATE IS NULL',
'       OR M.VOUCHER_DATE >= :P28_FROM_DATE)',
'',
'AND (:P28_TO_DATE IS NULL',
'     OR M.VOUCHER_DATE <= :P28_TO_DATE)',
'',
'AND (:P28_VOUCHER_TYPE IS NULL',
'     OR M.VOUCHER_TYPE = :P28_VOUCHER_TYPE)',
'',
'AND (:P28_STATUS IS NULL',
'     OR M.APPROVAL_STATUS = :P28_STATUS)',
'',
'ORDER BY M.VOUCHER_NO DESC)'))
