wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(14055405033039314971)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Debit and Credit amount must be equal.'
,p_static_id=>'debit-and-credit-amount-must-be-equal'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'    v_dr NUMBER;',
'    v_cr NUMBER;',
'',
'BEGIN',
'',
'    SELECT NVL(SUM(DEBIT_AMOUNT),0),',
'           NVL(SUM(CREDIT_AMOUNT),0)',
'      INTO v_dr,',
'           v_cr',
'      FROM ACC_VOUCHER_DTL',
'     WHERE VOUCHER_NO =',
'           :P28_VOUCHER_NO;',
'',
'    IF v_dr <> v_cr THEN',
'',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Debit and Credit amount must be equal.''',
'        );',
'',
'    END IF;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>14055405033039314971
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(14055404689295314970)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form VOUCHER MST'
,p_static_id=>'process-form-voucher-mst'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'    v_code VARCHAR2(30);',
'',
'BEGIN',
'',
'    IF :P28_VOUCHER_DATE IS NULL THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Please enter voucher date.''',
'        );',
'    END IF;',
'',
'    IF :P28_VOUCHER_TYPE IS NULL THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Please select voucher type.''',
'        );',
'    END IF;',
'',
'    --------------------------------------------------',
'    -- INSERT',
'    --------------------------------------------------',
'',
'    IF :P28_VOUCHER_NO IS NULL THEN',
'',
'        :P28_VOUCHER_NO :=',
'            SEQ_VOUCHER_NO.NEXTVAL;',
'',
'        v_code :=',
'            :P28_VOUCHER_TYPE',
'            || ''-''',
'            || LPAD(:P28_VOUCHER_NO,6,''0'');',
'',
'        INSERT INTO ACC_VOUCHER_MST',
'        (',
'            VOUCHER_NO,',
'            VOUCHER_CODE,',
'            VOUCHER_DATE,',
'            VOUCHER_TYPE,',
'            NARRATION,',
'            APPROVAL_STATUS,',
'            CREATED_BY,',
'            CREATED_DATE',
'        )',
'        VALUES',
'        (',
'            :P28_VOUCHER_NO,',
'            v_code,',
'            :P28_VOUCHER_DATE,',
'            :P28_VOUCHER_TYPE,',
'            :P28_NARRATION,',
'            ''P'',',
'            :APP_USER,',
'            SYSDATE',
'        ) RETURNING VOUCHER_NO INTO :P28_VOUCHER_NO ;',
'',
'    --------------------------------------------------',
'    -- UPDATE',
'    --------------------------------------------------',
'',
'    ELSE',
'',
'        UPDATE ACC_VOUCHER_MST',
'           SET VOUCHER_DATE = :P28_VOUCHER_DATE,',
'               VOUCHER_TYPE = :P28_VOUCHER_TYPE,',
'               NARRATION    = :P28_NARRATION,',
'               UPDATED_BY   = :APP_USER,',
'               UPDATED_DATE = SYSDATE',
'         WHERE VOUCHER_NO = :P28_VOUCHER_NO;',
'',
'    END IF;',
'',
'    apex_application.g_print_success_message :=',
'        ''Voucher saved successfully.'';',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(14055391959712314934)
,p_internal_uid=>14055404689295314970
);
end;
