wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(16717675257233108623)
,p_plug_name=>'SALES-REGISTER'
,p_static_id=>'register'
,p_region_name=>'purchase-register'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--removeHeader js-removeLandmark:t-Form--slimPadding:margin-top-none:margin-bottom-none'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT * FROM (SELECT M.INVOICE_NO,',
'       M.INVOICE_CODE,',
'       M.INVOICE_DATE,',
'       C.CUSTOMER_NAME,',
'       NVL(',
'           (SELECT SUM(D.TOTAL_AMOUNT)',
'              FROM TRN_SALES_INVOICE_DTL D',
'             WHERE D.INVOICE_NO = M.INVOICE_NO),',
'           0',
'       ) AS TOTAL_AMOUNT,',
'',
'       CASE M.APPROVAL_STATUS',
'            WHEN ''P'' THEN ''Pending''',
'            WHEN ''A'' THEN ''Approved''',
'            WHEN ''R'' THEN ''Rejected''',
'       END AS APPROVAL_STATUS,',
'',
'       M.CREATED_BY,',
'       M.CREATED_DATE',
'',
'FROM TRN_SALES_INVOICE_MST M',
'',
'JOIN MST_CUSTOMER C',
'  ON C.CUSTOMER_NO = M.CUSTOMER_NO',
'',
'WHERE M.APPROVAL_STATUS = ''P''',
'',
'ORDER BY M.INVOICE_NO DESC);'))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
