wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(12361468142946451)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'APPROVE_INVOICE'
,p_static_id=>'approve-purchase'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_status NUMBER;',
'    v_exists NUMBER;',
'BEGIN',
'',
'    ------------------------------------------------',
'    -- Already Approved',
'    ------------------------------------------------',
'    SELECT COUNT(*)',
'      INTO v_status',
'      FROM TRN_SALES_INVOICE_MST',
'     WHERE INVOICE_NO = APEX_APPLICATION.G_X01',
'       AND APPROVAL_STATUS = ''A'';',
'',
'    IF v_status > 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Invoice already approved.''',
'        );',
'    END IF;',
'',
'',
'    ------------------------------------------------',
'    -- Detail Exists',
'    ------------------------------------------------',
'    SELECT COUNT(*)',
'      INTO v_exists',
'      FROM TRN_SALES_INVOICE_DTL',
'     WHERE INVOICE_NO = APEX_APPLICATION.G_X01;',
'',
'    IF v_exists = 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Invoice details not found.''',
'        );',
'    END IF;',
'',
'',
'    ------------------------------------------------',
'    -- Stock Already Posted',
'    ------------------------------------------------',
'    SELECT COUNT(*)',
'      INTO v_exists',
'      FROM TRN_STOCK_LEDGER',
'     WHERE TRAN_TYPE = ''SALES''',
'       AND REF_NO = APEX_APPLICATION.G_X01;',
'',
'    IF v_exists > 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Stock already posted.''',
'        );',
'    END IF;',
'',
'',
'    ------------------------------------------------',
'    -- Approve Sales Invoice',
'    ------------------------------------------------',
'    UPDATE TRN_SALES_INVOICE_MST',
'       SET APPROVAL_STATUS = ''A'',',
'           APPROVED_BY     = :APP_USER,',
'           APPROVED_DATE   = SYSDATE,',
'           UPDATED_BY      = :APP_USER,',
'           UPDATED_DATE    = SYSDATE',
'     WHERE INVOICE_NO = APEX_APPLICATION.G_X01;',
'',
'',
'    ------------------------------------------------',
'    -- Stock Ledger Posting',
'    -- SALES = Stock OUT',
'    ------------------------------------------------',
'    -- INSERT INTO TRN_STOCK_LEDGER',
'    -- (',
'    --     LEDGER_NO,',
'    --     TRAN_DATE,',
'    --     TRAN_TYPE,',
'    --     REF_NO,',
'    --     PRODUCT_NO,',
'    --     QTY_IN,',
'    --     QTY_OUT,',
'    --     CREATED_BY,',
'    --     CREATED_DATE',
'    -- )',
'    -- SELECT',
'    --     SEQ_LEDGER_NO.NEXTVAL,',
'    --     M.INVOICE_DATE,',
'    --     ''SALES'',',
'    --     D.INVOICE_NO,',
'    --     D.PRODUCT_NO,',
'    --     0,',
'    --     D.BASE_QTY,',
'    --     :APP_USER,',
'    --     SYSDATE',
'    -- FROM TRN_SALES_INVOICE_DTL D',
'    -- JOIN TRN_SALES_INVOICE_MST M',
'    --   ON M.INVOICE_NO = D.INVOICE_NO',
'    -- WHERE D.INVOICE_NO = APEX_APPLICATION.G_X01;',
'',
'',
'    ------------------------------------------------',
'    -- Finance Voucher Posting',
'    ------------------------------------------------',
'    PKG_FINANCE.POST_SALES(',
'        P_INVOICE_NO => APEX_APPLICATION.G_X01',
'    );',
'',
'',
'    ------------------------------------------------',
'    -- Commit',
'    ------------------------------------------------',
'    COMMIT;',
'',
'    HTP.P(''Sales invoice approved successfully.'');',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        ROLLBACK;',
'',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            SQLERRM',
'        );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>12361468142946451
,p_created_on=>wwv_flow_imp.dz('20260901180421Z')
,p_updated_on=>wwv_flow_imp.dz('20260901181905Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(12361833212946454)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'REJECT_INVOICE'
,p_static_id=>'reject-purchase'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'',
'    UPDATE TRN_SALES_INVOICE_MST',
'       SET APPROVAL_STATUS = ''R'',',
'           APPROVED_BY     = :APP_USER,',
'           APPROVED_DATE   = SYSDATE,',
'           UPDATED_BY      = :APP_USER,',
'           UPDATED_DATE    = SYSDATE',
'     WHERE INVOICE_NO = APEX_APPLICATION.G_X01;',
'',
'    COMMIT;',
'',
'    HTP.P(''SUCCESS'');',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        ROLLBACK;',
'        HTP.P(SQLERRM);',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>12361833212946454
,p_created_on=>wwv_flow_imp.dz('20260901180421Z')
,p_updated_on=>wwv_flow_imp.dz('20260901181615Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
end;
