 p_id=>wwv_flow_imp.id(15308618574803517)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form PRICE SETUP'
,p_static_id=>'process-form-price-setup'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_purchase_rate MST_PRODUCT.PURCHASE_RATE%TYPE;',
'BEGIN',
'    SELECT PURCHASE_RATE',
'      INTO l_purchase_rate',
'      FROM MST_PRODUCT',
'     WHERE PRODUCT_NO = :P35_PRODUCT_NO;',
'',
'    IF :P35_SALES_RATE < l_purchase_rate THEN',
'        raise_application_error(',
'            -20001,',
'            ''Sales rate cannot be less than purchase rate.''',
'        );',
'    END IF;',
'',
'    INSERT INTO MST_SALES_PRICE (',
'        SALES_PRICE_NO,',
'        PRODUCT_NO,',
'        UOM_NO,',
'        SALES_RATE,',
'        EFFECTIVE_DATE,',
'        ACTIVE_FLAG,',
'        CREATED_BY,',
'        CREATED_DATE',
'    )',
'    VALUES (',
'        SEQ_SALES_PRICE.NEXTVAL,',
'        :P35_PRODUCT_NO,',
'        :P35_UOM_NO,',
'        :P35_SALES_RATE,',
'        NVL(:P35_EFFECTIVE_DATE, SYSDATE),',
'        ''1'',',
'        :APP_USER,',
'        SYSDATE',
'    );',
'',
'    apex_application.g_print_success_message :=',
'        ''New sales price saved successfully.'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(15333525578820600)
,p_process_success_message=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
''))
