,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SAVE'
,p_static_id=>'save'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :P41_ROLE_NO IS NOT NULL THEN',
'',
'        INSERT INTO SA_ROLE (',
'            ROLE_NO,',
'            ROLE_CODE,',
'            ROLE_NAME,',
'            ACTIVE_FLAG,',
'            CREATED_BY,',
'            CREATED_DATE',
'        )',
'        VALUES (',
'            S_SA_ROLE.NEXTVAL,',
'            :P41_ROLE_CODE,',
'            :P41_ROLE_NAME,',
'            NVL(:P41_ACTIVE_FLAG, 1),',
'            :APP_USER,',
'            SYSDATE',
'        );',
'',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(14273503943490879)
