,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT PRODUCT_NAME,',
'       CURRENT_STOCK,',
'       MIN_STOCK_QTY',
'FROM (',
'    SELECT P.PRODUCT_NAME,',
'           P.MIN_STOCK_QTY,',
'           NVL(SUM(L.QTY_IN),0)',
'           -',
'           NVL(SUM(L.QTY_OUT),0) CURRENT_STOCK',
'    FROM MST_PRODUCT P',
'    LEFT JOIN TRN_STOCK_LEDGER L',
'      ON L.PRODUCT_NO = P.PRODUCT_NO',
'    GROUP BY',
'        P.PRODUCT_NAME,',
'        P.MIN_STOCK_QTY',
')',
'WHERE CURRENT_STOCK <= MIN_STOCK_QTY;'))
