,p_parent_plug_id=>wwv_flow_imp.id(26860312980343219788)
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>30
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT *',
'FROM',
'(',
'    SELECT',
'',
'           D.RETURN_DTL_NO,',
'',
'           D.INVOICE_DTL_NO,',
'',
'           D.ORDER_DTL_NO,',
'',
'           D.PRODUCT_NO,',
'',
'           P.PRODUCT_CODE,',
'',
'           P.PRODUCT_NAME,',
'',
'           P.DESCRIPTION,',
'',
'           P.BRAND_NO,',
'',
'           D.UOM_NO,',
'',
'           U.UOM_NAME,',
'',
'           D.PACK_QTY,',
'',
'           D.BASE_QTY,',
'',
'           D.BASE_RATE,',
'',
'           D.INVOICE_QTY,',
'',
'           D.PREVIOUS_RETURN_QTY,',
'',
'           D.BALANCE_QTY,',
'',
'           D.RETURN_QTY,',
'',
'           D.SALES_RATE,',
'',
'           D.TOTAL_AMOUNT,',
'',
'           D.REMARKS,',
'',
'           CASE',
'               WHEN M.APPROVAL_STATUS = ''A''',
'               THEN ''X''',
'               ELSE ''U''',
'           END ROW_STATUS',
'',
'    FROM TRN_CUSTOMER_RETURN_DTL D',
'',
'         JOIN TRN_CUSTOMER_RETURN_MST M',
'           ON M.RETURN_NO = D.RETURN_NO',
'',
'         JOIN MST_PRODUCT P',
'           ON P.PRODUCT_NO = D.PRODUCT_NO',
'',
'         LEFT JOIN MST_UOM U',
'           ON U.UOM_NO = D.UOM_NO',
'',
'    WHERE D.RETURN_NO = :P102_RETURN_NO',
'    ',
'ORDER BY RETURN_DTL_NO',
');'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P102_RETURN_NO,P102_INVOICE_NO'
,p_prn_units=>'INCHES'
