wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9054124808534761049)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(9054123871183761039)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CUSTOMER RETURN DETAIL - Save Interactive Grid Data'
,p_static_id=>'customer-return-detail-save-interactive-grid-data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_count NUMBER;',
'BEGIN',
'',
'    -------------------------------------------------',
'    -- Header Validation',
'    -------------------------------------------------',
'    IF :P102_RETURN_NO IS NULL THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Please save Return Master first.''',
'        );',
'    END IF;',
'',
'    -------------------------------------------------',
'    -- Product Validation',
'    -------------------------------------------------',
'    IF :PRODUCT_NO IS NULL THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Product is required.''',
'        );',
'    END IF;',
'',
'    -------------------------------------------------',
'    -- Return Qty Validation',
'    -------------------------------------------------',
'    IF NVL(:RETURN_QTY,0) <= 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Return quantity must be greater than zero.''',
'        );',
'    END IF;',
'',
'    -------------------------------------------------',
'    -- Balance Validation',
'    -------------------------------------------------',
'    IF NVL(:RETURN_QTY,0) > NVL(:BALANCE_QTY,0) THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Return quantity exceeds balance quantity.''',
'        );',
'    END IF;',
'',
'    -------------------------------------------------',
'    -- Duplicate Product Validation',
'    -------------------------------------------------',
'    IF :APEX$ROW_STATUS = ''C'' THEN',
'',
'        SELECT COUNT(*)',
'          INTO v_count',
'          FROM TRN_CUSTOMER_RETURN_DTL',
'         WHERE RETURN_NO  = :P102_RETURN_NO',
'           AND PRODUCT_NO = :PRODUCT_NO;',
'',
'        IF v_count > 0 THEN',
'            RAISE_APPLICATION_ERROR(',
'                -20001,',
'                ''Product already exists.''',
'            );',
'        END IF;',
'',
'    END IF;',
'',
'    -------------------------------------------------',
'    -- Approved Return Validation',
'    -------------------------------------------------',
'    IF :APEX$ROW_STATUS IN (''U'',''D'') THEN',
'',
'        SELECT COUNT(*)',
'          INTO v_count',
'          FROM TRN_CUSTOMER_RETURN_MST',
'         WHERE RETURN_NO = :P102_RETURN_NO',
'           AND APPROVAL_STATUS = ''A'';',
'',
'        IF v_count > 0 THEN',
'            RAISE_APPLICATION_ERROR(',
'                -20001,',
'                ''Approved return cannot be modified.''',
'            );',
'        END IF;',
'',
'    END IF;',
'',
'    -------------------------------------------------',
'    -- INSERT',
'    -------------------------------------------------',
'    IF :APEX$ROW_STATUS = ''C'' THEN',
'',
'        INSERT INTO TRN_CUSTOMER_RETURN_DTL',
'        (',
'            RETURN_DTL_NO,',
'            RETURN_NO,',
'            PRODUCT_NO,',
'            INVOICE_DTL_NO,',
'            ORDER_DTL_NO,',
'            UOM_NO,',
'            PACK_QTY,',
'            BASE_QTY,',
'            BASE_RATE,',
'            INVOICE_QTY,',
'            PREVIOUS_RETURN_QTY,',
'            BALANCE_QTY,',
'            RETURN_QTY,',
'            SALES_RATE,',
'            TOTAL_AMOUNT,',
'            REMARKS,',
'            CREATED_BY,',
'            CREATED_DATE',
'        )',
'        VALUES',
'        (',
'            SEQ_RETURN_DTL_NO.NEXTVAL,',
'            :P102_RETURN_NO,',
'            :PRODUCT_NO,',
'            :INVOICE_DTL_NO,',
'            :ORDER_DTL_NO,',
'            :UOM_NO,',
'            :PACK_QTY,',
'            :BASE_QTY,',
'            :BASE_RATE,',
'            :INVOICE_QTY,',
'            :PREVIOUS_RETURN_QTY,',
'            :BALANCE_QTY,',
'            :RETURN_QTY,',
'            :SALES_RATE,',
'            NVL(:RETURN_QTY,0) * NVL(:SALES_RATE,0),',
'            :REMARKS,',
'            :APP_USER,',
'            SYSDATE',
'        )',
'        RETURNING RETURN_DTL_NO',
'        INTO :RETURN_DTL_NO;',
'',
'    -------------------------------------------------',
'    -- UPDATE',
'    -------------------------------------------------',
'    ELSIF :APEX$ROW_STATUS = ''U'' THEN',
'',
'        UPDATE TRN_CUSTOMER_RETURN_DTL',
'           SET RETURN_QTY   = :RETURN_QTY,',
'               SALES_RATE   = :SALES_RATE,',
'               TOTAL_AMOUNT = NVL(:RETURN_QTY,0) * NVL(:SALES_RATE,0),',
'               REMARKS      = :REMARKS,',
'               UPDATED_BY   = :APP_USER,',
'               UPDATED_DATE = SYSDATE',
'         WHERE RETURN_DTL_NO = :RETURN_DTL_NO;',
'',
'    -------------------------------------------------',
'    -- DELETE',
'    -------------------------------------------------',
'    ELSIF :APEX$ROW_STATUS = ''D'' THEN',
'',
'        DELETE',
'          FROM TRN_CUSTOMER_RETURN_DTL',
'         WHERE RETURN_DTL_NO = :RETURN_DTL_NO;',
'',
'    END IF;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(9093637667389698777)
,p_internal_uid=>9054124808534761049
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(11193746980423922946)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'DELETE RETURN'
,p_static_id=>'delete-return'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_status VARCHAR2(1);',
'BEGIN',
'',
'    SELECT APPROVAL_STATUS',
'      INTO v_status',
'      FROM TRN_CUSTOMER_RETURN_MST',
'     WHERE RETURN_NO = :P102_RETURN_NO;',
'',
'    IF v_status <> ''P'' THEN',
'',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Approved return cannot be deleted.''',
'        );',
'',
'    END IF;',
'',
'    DELETE FROM TRN_CUSTOMER_RETURN_DTL',
'     WHERE RETURN_NO = :P102_RETURN_NO;',
'',
'    DELETE FROM TRN_CUSTOMER_RETURN_MST',
'     WHERE RETURN_NO = :P102_RETURN_NO;',
'',
'    apex_application.g_print_success_message :=',
'        ''Customer return deleted successfully.'';',
'',
'        :P102_RETURN_NO := NULL;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(9093636879111698776)
,p_internal_uid=>11193746980423922946
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9054121472305761015)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_region_id=>wwv_flow_imp.id(43882750435722370787)
,p_process_type=>'NATIVE_FORM_INIT'
,p_process_name=>'Initialize form Customer Return'
,p_static_id=>'initialize-form-customer-return'
,p_internal_uid=>9054121472305761015
