wwv_flow_imp_page.create_page(
 p_id=>103
,p_name=>'Sales Return Approval'
,p_alias=>'SALES-RETURN-APPROVAL'
,p_step_title=>'Sales Return Approval'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function f_openModal (returnNo){',
'  $s(''P103_RETURN_NO'',returnNo);',
'  openModal (''return_approve'');',
'  apex.region(''return-detail'').refresh();',
'}',
'',
'function approveReturn(returnNo) {',
'',
'    apex.message.confirm(',
'        "Are you sure you want to approve this Customer Return?",',
'        function (okPressed) {',
'',
'            if (okPressed) {',
'',
'                apex.server.process(',
'                    "APPROVE_RETURN",',
'                    {',
'                        x01: returnNo',
'                    },',
'                    {',
'                        dataType: "json",',
'',
'                        success: function (pData) {',
'',
'                            if (pData.status === "SUCCESS") {',
'',
'                                apex.message.showPageSuccess(pData.message);',
'',
'                                apex.region("return_list").refresh();',
'',
'                            } else {',
'',
'                                apex.message.alert(pData.message);',
'',
'                            }',
'                        },',
'',
'                        error: function (xhr, status, error) {',
'',
'                            apex.message.alert(',
'                                "Approval failed.<br>" + error',
'                            );',
'',
'                        }',
'                    }',
'                );',
'',
'            }',
'',
'        }',
'    );',
'',
'}',
'function rejectReturn(returnNo) {',
'',
'    apex.message.confirm(',
'        "Are you sure you want to reject this Customer Return?",',
'        function (okPressed) {',
'',
'            if (!okPressed) {',
'                return;',
'            }',
'',
'            apex.server.process(',
'                "RETURN_REJECT",',
'                {',
'                    x01: returnNo',
'                },',
'                {',
'                    dataType: "json",',
'',
'                    success: function (pData) {',
'',
'                        if (pData.status === "SUCCESS") {',
'',
'                            apex.message.showPageSuccess(pData.message);',
'',
'                            apex.region("return_list").refresh();',
'',
'                        } else {',
'',
'                            apex.message.alert(pData.message);',
'',
'                        }',
'                    },',
'',
'                    error: function (jqXHR) {',
'',
'                        apex.message.alert(',
'                            "Error: " + jqXHR.responseText',
'                        );',
'',
'                    }',
'                }',
'            );',
'',
'        }',
'    );',
'',
'}'))
,p_step_template=>4073832297226169690
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'18'
,p_last_updated_on=>wwv_flow_imp.dz('20260823162810Z')
,p_last_updated_by=>'ADMIN'
);
