wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(19381228087036679543)
,p_plug_name=>'DELIVERY DTL'
,p_static_id=>'customer-return-detail'
,p_region_name=>'customer-return'
,p_parent_plug_id=>wwv_flow_imp.id(37187417196196138292)
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>30
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT * FROM (SELECT D.DELIVERY_DTL_NO,',
'       D.INVOICE_DTL_NO,',
'       D.ORDER_DTL_NO,',
'',
'       D.PRODUCT_NO,',
'       P.PRODUCT_CODE,',
'       P.PRODUCT_NAME,',
'       P.DESCRIPTION,',
'       P.BRAND_NO,',
'',
'       D.UOM_NO,',
'       U.UOM_NAME,',
'',
'       D.PACK_QTY,',
'       D.ORDER_QTY,',
'       D.INVOICE_QTY,',
'       D.BASE_QTY,',
'       D.BASE_RATE,',
'',
'       NVL(D.PREVIOUS_DELIVERY_QTY, 0)',
'           AS PREVIOUS_DELIVERY_QTY,',
'',
'       D.BALANCE_QTY,',
'       D.DELIVERY_QTY,',
'       D.SALES_RATE,',
'',
'       NVL(I.DISCOUNT_PERCENT, 0)',
'           AS DISCOUNT_PERCENT,',
'',
'       NVL(I.DISCOUNT_AMOUNT, 0)',
'           AS DISCOUNT_AMOUNT,',
'',
'       D.TOTAL_AMOUNT,',
'       D.REMARKS',
'',
'  FROM TRN_DELIVERY_DTL D',
'',
'       JOIN MST_PRODUCT P',
'         ON P.PRODUCT_NO = D.PRODUCT_NO',
'',
'       LEFT JOIN MST_UOM U',
'         ON U.UOM_NO = D.UOM_NO',
'',
'       LEFT JOIN TRN_SALES_INVOICE_DTL I',
'         ON I.INVOICE_DTL_NO = D.INVOICE_DTL_NO',
'',
' WHERE D.DELIVERY_NO = :P105_DELIVERY_NO',
'',
' ORDER BY D.DELIVERY_DTL_NO)'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P105_INVOICE_NO,P105_DELIVERY_NO'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
