wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(54209854651575289291)
,p_plug_name=>'DELIVERY MST'
,p_static_id=>'register_1'
,p_region_name=>'invoice_list'
,p_parent_plug_id=>wwv_flow_imp.id(37187417196196138292)
,p_region_template_options=>'#DEFAULT#:t-IRR-region--removeHeader js-removeLandmark:t-Form--slimPadding:margin-top-none:margin-bottom-none'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'       M.DELIVERY_NO,',
'       M.DELIVERY_CODE,',
'       M.DELIVERY_DATE,',
'       M.INVOICE_NO,',
'       I.INVOICE_DATE,',
'       M.CUSTOMER_NO,',
'       C.CUSTOMER_NAME,',
'       C.MOBILE_NO,',
'       M.DELIVERY_ADDRESS,',
'       M.DELIVERY_PERSON,',
'       M.VEHICLE_NO,',
'       M.CONTACT_NO,',
'',
'       M.REMARKS,',
'',
'       M.APPROVAL_STATUS,',
'       M.APPROVED_BY,',
'       M.APPROVED_DATE,',
'',
'       M.CREATED_BY,',
'       M.CREATED_DATE,',
'',
'       M.UPDATED_BY,',
'       M.UPDATED_DATE',
'',
'FROM TRN_DELIVERY_MST M',
'LEFT JOIN TRN_SALES_INVOICE_MST I',
'       ON I.INVOICE_NO = M.INVOICE_NO',
'LEFT JOIN MST_CUSTOMER C',
'       ON C.CUSTOMER_NO = M.CUSTOMER_NO',
'WHERE M.DELIVERY_NO = :P105_DELIVERY_NO'))
,p_is_editable=>true
,p_edit_operations=>'i:u:d'
,p_lost_update_check_type=>'VALUES'
,p_plug_source_type=>'NATIVE_FORM'
);
