,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CHALLAN_APPROVED'
,p_static_id=>'challan-approved'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'    v_invoice_no      NUMBER;',
'    v_order_no        NUMBER;',
'    v_total_invoice   NUMBER;',
'    v_total_delivery  NUMBER;',
'    v_stock           NUMBER;',
'    v_exists          NUMBER;',
'',
'    v_delivery_no NUMBER := :P105_DELIVERY_NO;',
'',
'BEGIN',
'',
'    ----------------------------------------------------',
'    -- Only Pending Delivery Can Approve',
'    ----------------------------------------------------',
'',
'    SELECT COUNT(*)',
'      INTO v_exists',
'      FROM TRN_DELIVERY_MST',
'     WHERE DELIVERY_NO = v_delivery_no',
'       AND APPROVAL_STATUS = ''P'';',
'',
'    IF v_exists = 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Only pending delivery can be approved.''',
'        );',
'    END IF;',
'',
'    ----------------------------------------------------',
'    -- Already Approved',
'    ----------------------------------------------------',
'',
'    SELECT COUNT(*)',
'      INTO v_exists',
'      FROM TRN_DELIVERY_MST',
'     WHERE DELIVERY_NO = v_delivery_no',
'       AND APPROVAL_STATUS = ''A'';',
'',
'    IF v_exists > 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Delivery already approved.''',
'        );',
'    END IF;',
'',
'    ----------------------------------------------------',
'    -- Detail Exists',
'    ----------------------------------------------------',
'',
'    SELECT COUNT(*)',
'      INTO v_exists',
'      FROM TRN_DELIVERY_DTL',
'     WHERE DELIVERY_NO = v_delivery_no;',
'',
'    IF v_exists = 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Delivery details not found.''',
'        );',
'    END IF;',
'',
'    ----------------------------------------------------',
'    -- Stock Already Posted',
'    ----------------------------------------------------',
'',
'    SELECT COUNT(*)',
'      INTO v_exists',
'      FROM TRN_STOCK_LEDGER',
'     WHERE TRAN_TYPE = ''DELIVERY''',
'       AND REF_NO = v_delivery_no;',
'',
'    IF v_exists > 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Stock already posted.''',
'        );',
'    END IF;',
'',
'    ----------------------------------------------------',
'    -- Stock Validation',
'    ----------------------------------------------------',
'',
'    FOR r IN',
'    (',
'        SELECT PRODUCT_NO,',
'               BASE_QTY',
'          FROM TRN_DELIVERY_DTL',
'         WHERE DELIVERY_NO = v_delivery_no',
'    )',
'    LOOP',
'',
'        SELECT NVL(SUM(QTY_IN) - SUM(QTY_OUT),0)',
'          INTO v_stock',
'          FROM TRN_STOCK_LEDGER',
'         WHERE PRODUCT_NO = r.PRODUCT_NO;',
'',
'        IF r.BASE_QTY > v_stock THEN',
'',
'            RAISE_APPLICATION_ERROR(',
'                -20001,',
'                ''Insufficient stock for product : ''',
'                || r.PRODUCT_NO',
'            );',
'',
'        END IF;',
'',
'    END LOOP;',
'',
'    ----------------------------------------------------',
'    -- Approve Delivery',
'    ----------------------------------------------------',
'',
'    UPDATE TRN_DELIVERY_MST',
'       SET APPROVAL_STATUS = ''A'',',
'           APPROVED_BY     = :APP_USER,',
'           APPROVED_DATE   = SYSDATE',
'     WHERE DELIVERY_NO = v_delivery_no;',
'',
'    ----------------------------------------------------',
'    -- Stock Ledger Posting',
'    ----------------------------------------------------',
'',
'    INSERT INTO TRN_STOCK_LEDGER',
'    (',
'        LEDGER_NO,',
'        TRAN_DATE,',
'        TRAN_TYPE,',
'        REF_NO,',
'        PRODUCT_NO,',
'        QTY_IN,',
'        QTY_OUT,',
'        CREATED_BY,',
'        CREATED_DATE',
'    )',
'    SELECT',
'        SEQ_LEDGER_NO.NEXTVAL,',
'        SYSDATE,',
'        ''DELIVERY'',',
'        DELIVERY_NO,',
'        PRODUCT_NO,',
'        0,',
'        BASE_QTY,',
'        :APP_USER,',
'        SYSDATE',
'    FROM TRN_DELIVERY_DTL',
'    WHERE DELIVERY_NO = v_delivery_no;',
'',
'    ----------------------------------------------------',
'    -- Get Invoice No',
'    ----------------------------------------------------',
'',
'    SELECT INVOICE_NO',
'      INTO v_invoice_no',
'      FROM TRN_DELIVERY_MST',
'     WHERE DELIVERY_NO = v_delivery_no;',
'',
'    ----------------------------------------------------',
'    -- Get Order No',
'    ----------------------------------------------------',
'',
'    SELECT ORDER_NO',
'      INTO v_order_no',
'      FROM TRN_SALES_INVOICE_MST',
'     WHERE INVOICE_NO = v_invoice_no;',
'',
'    ----------------------------------------------------',
'    -- Update Invoice Detail',
'    ----------------------------------------------------',
'',
'    UPDATE TRN_SALES_INVOICE_DTL I',
'       SET DELIVERED_QTY =',
'           (',
'               SELECT NVL(SUM(D.DELIVERY_QTY),0)',
'                 FROM TRN_DELIVERY_DTL D',
'                 JOIN TRN_DELIVERY_MST M',
'                   ON M.DELIVERY_NO = D.DELIVERY_NO',
'                WHERE D.INVOICE_DTL_NO = I.INVOICE_DTL_NO',
'                  AND M.APPROVAL_STATUS = ''A''',
'           )',
'     WHERE I.INVOICE_NO = v_invoice_no;',
'',
'    ----------------------------------------------------',
'    -- Update Order Detail',
'    ----------------------------------------------------',
'',
'    UPDATE TRN_SALES_ORDER_DTL O',
'       SET DELIVERED_QTY =',
'           (',
'               SELECT NVL(SUM(D.DELIVERY_QTY),0)',
'                 FROM TRN_DELIVERY_DTL D',
'                 JOIN TRN_DELIVERY_MST M',
'                   ON M.DELIVERY_NO = D.DELIVERY_NO',
'                WHERE D.ORDER_DTL_NO = O.ORDER_DTL_NO',
'                  AND M.APPROVAL_STATUS = ''A''',
'           ),',
'',
'           BALANCE_QTY =',
'               ORDER_QTY -',
'               (',
'                   SELECT NVL(SUM(D.DELIVERY_QTY),0)',
'                     FROM TRN_DELIVERY_DTL D',
'                     JOIN TRN_DELIVERY_MST M',
'                       ON M.DELIVERY_NO = D.DELIVERY_NO',
'                    WHERE D.ORDER_DTL_NO = O.ORDER_DTL_NO',
'                      AND M.APPROVAL_STATUS = ''A''',
'               )',
'',
'     WHERE O.ORDER_NO = v_order_no;',
'',
'    ----------------------------------------------------',
'    -- Total Invoice Qty',
'    ----------------------------------------------------',
'',
'    SELECT NVL(SUM(SALES_QTY),0)',
'      INTO v_total_invoice',
'      FROM TRN_SALES_INVOICE_DTL',
'     WHERE INVOICE_NO = v_invoice_no;',
'',
'    ----------------------------------------------------',
'    -- Total Delivered Qty',
'    ----------------------------------------------------',
'',
'    SELECT NVL(SUM(DELIVERED_QTY),0)',
'      INTO v_total_delivery',
'      FROM TRN_SALES_INVOICE_DTL',
'     WHERE INVOICE_NO = v_invoice_no;',
'',
'    ----------------------------------------------------',
'    -- Update Invoice Status',
'    ----------------------------------------------------',
'',
'    UPDATE TRN_SALES_INVOICE_MST',
'       SET DELIVERY_STATUS =',
'           CASE',
'               WHEN v_total_delivery = 0 THEN ''P''',
'               WHEN v_total_delivery < v_total_invoice THEN ''PD''',
'               ELSE ''D''',
'           END',
'     WHERE INVOICE_NO = v_invoice_no;',
'',
'    ----------------------------------------------------',
'    -- Update Order Status',
'    ----------------------------------------------------',
'',
'    UPDATE TRN_SALES_ORDER_MST',
'       SET ORDER_STATUS =',
'           CASE',
'               WHEN v_total_delivery = 0 THEN ''I''',
'               WHEN v_total_delivery < v_total_invoice THEN ''PD''',
'               ELSE ''D''',
'           END,',
'           DELIVERY_BY   = :APP_USER,',
'           DELIVERY_DATE = SYSDATE',
'     WHERE ORDER_NO = v_order_no;',
'',
'    ----------------------------------------------------',
'    -- Finance Voucher',
'    ----------------------------------------------------',
'',
'    PKG_FINANCE.POST_SALES',
'    (',
'        P_INVOICE_NO => v_invoice_no',
'    );',
'',
'    COMMIT;',
'',
'EXCEPTION',
'',
'    WHEN OTHERS THEN',
'        ROLLBACK;',
'        RAISE;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(8055882896475317)
,p_internal_uid=>8056012925475319
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(11193744205550922919)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CHALLAN_POPULATE'
,p_static_id=>'challan-populate'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 9/7/2026 3:18:50 PM (QP5 v5.388) */',
'DECLARE',
'    V_DATA   CLOB;',
'BEGIN',
'    SELECT JSON_ARRAYAGG (',
'               JSON_OBJECT (',
'                   ''SL_NUMBER'' VALUE ROWNUM,',
'                   ''INVOICE_DTL_NO'' VALUE D.INVOICE_DTL_NO,',
'                   ''ORDER_DTL_NO'' VALUE D.ORDER_DTL_NO,',
'                   ''PRODUCT_NO'' VALUE D.PRODUCT_NO,',
'                   ''PRODUCT_CODE'' VALUE PR.PRODUCT_CODE,',
'                   ''PRODUCT_NAME'' VALUE PR.PRODUCT_NAME,',
'                   ''DESCRIPTION'' VALUE PR.DESCRIPTION,',
'                   ''BRAND_NO'' VALUE PR.BRAND_NO,',
'                   ''UOM_NO'' VALUE D.UOM_NO,',
'                   ''PACK_QTY'' VALUE NVL (D.PACK_QTY, 1),',
'                   --------------------------------------------------',
'                   -- Invoice Qty',
'                   --------------------------------------------------',
'',
'                   ''ORDER_QTY'' VALUE D.ORDER_QTY,',
'                   ''INVOICE_QTY'' VALUE D.SALES_QTY,',
'                   ''PREVIOUS_DELIVERY_QTY'' VALUE NVL (D.DELIVERED_QTY, 0),',
'                   ''BALANCE_QTY'' VALUE',
'                       (D.SALES_QTY - NVL (D.DELIVERED_QTY, 0)),',
'                   ''DELIVERY_QTY'' VALUE',
'                       (D.SALES_QTY - NVL (D.DELIVERED_QTY, 0)),',
'                   --------------------------------------------------',
'                   -- Base Qty',
'                   --------------------------------------------------',
'',
'                   ''BASE_QTY'' VALUE',
'                       (  (D.SALES_QTY - NVL (D.DELIVERED_QTY, 0))',
'                        * NVL (D.PACK_QTY, 1)),',
'                   ''PREVIOUS_DELIVERY_BASE_QTY'' VALUE',
'                       (NVL (D.DELIVERED_QTY, 0) * NVL (D.PACK_QTY, 1)),',
'                   ''BALANCE_BASE_QTY'' VALUE',
'                       (  (D.SALES_QTY - NVL (D.DELIVERED_QTY, 0))',
'                        * NVL (D.PACK_QTY, 1)),',
'                   --------------------------------------------------',
'                   -- Rate',
'                   --------------------------------------------------',
'',
'                   ''SALES_RATE'' VALUE D.SALES_RATE,',
'                   ''BASE_RATE'' VALUE D.BASE_RATE,',
'                   --------------------------------------------------',
'                   -- Discount',
'                   --------------------------------------------------',
'',
'                   ''DISCOUNT_PERCENT'' VALUE NVL (D.DISCOUNT_PERCENT, 0),',
'                   ''DISCOUNT_AMOUNT'' VALUE',
'                       ROUND (',
'                             (D.SALES_QTY - NVL (D.DELIVERED_QTY, 0))',
'                           * NVL (D.SALES_RATE, 0)',
'                           * NVL (D.DISCOUNT_PERCENT, 0)',
'                           / 100,',
'                           2),',
'                   --------------------------------------------------',
'                   -- Net Amount',
'                   --------------------------------------------------',
'',
'                   ''TOTAL_AMOUNT'' VALUE',
'                       ROUND (',
'                             (D.SALES_QTY - NVL (D.DELIVERED_QTY, 0))',
'                           * NVL (D.SALES_RATE, 0)',
'                           * (1 - NVL (D.DISCOUNT_PERCENT, 0) / 100),',
'                           2)',
'                   RETURNING CLOB)',
'               RETURNING CLOB)',
'      INTO V_DATA',
'      FROM TRN_SALES_INVOICE_DTL  D',
'           JOIN MST_PRODUCT PR ON PR.PRODUCT_NO = D.PRODUCT_NO',
'     WHERE     D.INVOICE_NO = APEX_APPLICATION.G_X01',
'           AND NVL (D.SALES_QTY, 0) > NVL (D.DELIVERED_QTY, 0);',
'',
'    IF V_DATA IS NULL',
'    THEN',
'        V_DATA := ''[]'';',
'    END IF;',
'',
'    HTP.PRN (V_DATA);',
'EXCEPTION',
'    WHEN OTHERS',
'    THEN',
'        HTP.PRN (''[]'');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>11193744205550922919
,p_updated_on=>wwv_flow_imp.dz('20260907151933Z')
,p_updated_by=>'ADMIN'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(10327111591808918532)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(19381228087036679543)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'DELIVERY DTL - Save Interactive Grid Data'
,p_static_id=>'customer-return-detail-save-interactive-grid-data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 9/7/2026 3:26:55 PM (QP5 v5.388) */',
'DECLARE',
'    V_DISCOUNT_PERCENT   NUMBER := 0;',
'    V_GROSS_AMOUNT       NUMBER := 0;',
'    V_NET_AMOUNT         NUMBER := 0;',
'BEGIN',
'    ------------------------------------------------',
'    -- Header Validation',
'    ------------------------------------------------',
'',
'    IF :P105_INVOICE_NO IS NULL',
'    THEN',
'        RAISE_APPLICATION_ERROR (-20001, ''Please select invoice.'');',
'    END IF;',
'',
'',
'    ------------------------------------------------',
'    -- Quantity Validation',
'    ------------------------------------------------',
'',
'    IF :APEX$ROW_STATUS IN (''C'', ''U'') AND NVL ( :DELIVERY_QTY, 0) <= 0',
'    THEN',
'        RAISE_APPLICATION_ERROR (',
'            -20001,',
'            ''Delivery quantity must be greater than zero.'');',
'    END IF;',
'',
'',
'    ------------------------------------------------',
'    -- Balance Validation',
'    ------------------------------------------------',
'',
'    IF     :APEX$ROW_STATUS IN (''C'', ''U'')',
'       AND NVL ( :DELIVERY_QTY, 0) > NVL ( :BALANCE_QTY, 0)',
'    THEN',
'        RAISE_APPLICATION_ERROR (',
'            -20001,',
'            ''Delivery quantity exceeds balance quantity.'');',
'    END IF;',
'',
'',
'    ------------------------------------------------',
'    -- Get Discount From Invoice Detail',
'    ------------------------------------------------',
'',
'    IF :APEX$ROW_STATUS IN (''C'', ''U'')',
'    THEN',
'        SELECT NVL (DISCOUNT_PERCENT, 0)',
'          INTO V_DISCOUNT_PERCENT',
'          FROM TRN_SALES_INVOICE_DTL',
'         WHERE INVOICE_DTL_NO = :INVOICE_DTL_NO;',
'',
'',
'        V_GROSS_AMOUNT := NVL ( :DELIVERY_QTY, 0) * NVL ( :SALES_RATE, 0);',
'',
'',
'        V_NET_AMOUNT := V_GROSS_AMOUNT * (1 - V_DISCOUNT_PERCENT / 100);',
'',
'',
'        IF V_NET_AMOUNT < 0',
'        THEN',
'            RAISE_APPLICATION_ERROR (',
'                -20001,',
'                ''Discount cannot be greater than delivery amount.'');',
'        END IF;',
'    END IF;',
'',
'',
'    ------------------------------------------------',
'    -- INSERT',
'    ------------------------------------------------',
'',
'    IF :APEX$ROW_STATUS = ''C''',
'    THEN',
'        INSERT INTO TRN_DELIVERY_DTL (DELIVERY_DTL_NO,',
'                                      DELIVERY_NO,',
'                                      INVOICE_DTL_NO,',
'                                      ORDER_DTL_NO,',
'                                      PRODUCT_NO,',
'                                      UOM_NO,',
'                                      PACK_QTY,',
'                                      ORDER_QTY,',
'                                      INVOICE_QTY,',
'                                      PREVIOUS_DELIVERY_QTY,',
'                                      DELIVERY_QTY,',
'                                      BALANCE_QTY,',
'                                      BASE_QTY,',
'                                      SALES_RATE,',
'                                      BASE_RATE,',
'                                      TOTAL_AMOUNT,',
'                                      REMARKS,',
'                                      CREATED_BY,',
'                                      CREATED_DATE)',
'             VALUES (SEQ_DELIVERY_DTL_NO.NEXTVAL,',
'                     :P105_DELIVERY_NO,',
'                     :INVOICE_DTL_NO,',
'                     :ORDER_DTL_NO,',
'                     :PRODUCT_NO,',
'                     :UOM_NO,',
'                     :PACK_QTY,',
'                     :ORDER_QTY,',
'                     :INVOICE_QTY,',
'                     :PREVIOUS_DELIVERY_QTY,',
'                     :DELIVERY_QTY,',
'                     :BALANCE_QTY,',
'                     :BASE_QTY,',
'                     :SALES_RATE,',
'                     :BASE_RATE,',
'                     V_NET_AMOUNT,',
'                     :REMARKS,',
'                     :APP_USER,',
'                     SYSDATE)',
'          RETURNING DELIVERY_DTL_NO',
'               INTO :DELIVERY_DTL_NO;',
'    ------------------------------------------------',
'    -- UPDATE',
'    ------------------------------------------------',
'',
'    ELSIF :APEX$ROW_STATUS = ''U''',
'    THEN',
'        UPDATE TRN_DELIVERY_DTL',
'           SET UOM_NO = :UOM_NO,',
'               PACK_QTY = :PACK_QTY,',
'               ORDER_QTY = :ORDER_QTY,',
'               INVOICE_QTY = :INVOICE_QTY,',
'               DELIVERY_QTY = :DELIVERY_QTY,',
'               BALANCE_QTY = :BALANCE_QTY,',
'               BASE_QTY = :BASE_QTY,',
'               SALES_RATE = :SALES_RATE,',
'               BASE_RATE = :BASE_RATE,',
'               TOTAL_AMOUNT = V_NET_AMOUNT,',
'               REMARKS = :REMARKS,',
'               UPDATED_BY = :APP_USER,',
'               UPDATED_DATE = SYSDATE',
'         WHERE DELIVERY_DTL_NO = :DELIVERY_DTL_NO;',
'    ------------------------------------------------',
'    -- DELETE',
'    ------------------------------------------------',
'',
'    ELSIF :APEX$ROW_STATUS = ''D''',
'    THEN',
'        IF :P105_APPROVAL_STATUS = ''A''',
'        THEN',
'            RAISE_APPLICATION_ERROR (-20001,',
'                                     ''Approved delivery cannot be deleted.'');',
'        END IF;',
'',
'        DELETE FROM TRN_DELIVERY_DTL',
'              WHERE DELIVERY_DTL_NO = :DELIVERY_DTL_NO;',
'    END IF;',
'',
'',
'    APEX_APPLICATION.g_print_success_message :=',
'        ''Delivery details saved successfully.'';',
'EXCEPTION',
'    WHEN NO_DATA_FOUND',
'    THEN',
'        RAISE_APPLICATION_ERROR (-20001, ''Invoice detail not found.'');',
'    WHEN OTHERS',
'    THEN',
'        RAISE_APPLICATION_ERROR (-20001, SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(10327105834897918512)
,p_internal_uid=>10327111591808918532
,p_updated_on=>wwv_flow_imp.dz('20260907152716Z')
,p_updated_by=>'ADMIN'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(10654189275544424047)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'DELETE DELIVERY CHALLAN'
,p_static_id=>'delete-delivery-challan'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'',
'',
'    IF :P105_APPROVAL_STATUS = ''A'' THEN',
'    RAISE_APPLICATION_ERROR(',
'        -20001,',
'        ''Approved delivery cannot be deleted.''',
'    );',
'END IF;',
