'          FROM TRN_DELIVERY_MST',
'         WHERE DELIVERY_NO = :P105_DELIVERY_NO;',
'',
'        :P105_DELIVERY_NO := NULL;',
'',
'        apex_application.g_print_success_message :=',
'            ''Delivery deleted successfully.'';',
'',
'    END IF;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(10327105019743918510)
,p_internal_uid=>10654189275544424047
);
