wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(27359480314749251993)
,p_plug_name=>'Delivery Challan Report'
,p_static_id=>'register'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--removeHeader js-removeLandmark:t-Form--slimPadding:margin-top-none:margin-bottom-none'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 9/7/2026 3:29:07 PM (QP5 v5.388) */',
'  SELECT M.DELIVERY_NO,',
'         M.DELIVERY_CODE,',
'         M.DELIVERY_DATE,',
'         I.INVOICE_CODE,',
'         I.INVOICE_DATE,',
'         C.CUSTOMER_NAME,',
'         C.MOBILE_NO,',
'         M.DELIVERY_PERSON,',
'         M.VEHICLE_NO,',
'         NVL (X.TOTAL_QTY, 0)                AS TOTAL_QTY,',
'         NVL (X.GROSS_AMOUNT, 0)             AS GROSS_AMOUNT,',
'         NVL (X.TOTAL_DISCOUNT_AMOUNT, 0)    AS TOTAL_DISCOUNT_AMOUNT,',
'         NVL (X.TOTAL_AMOUNT, 0)             AS TOTAL_AMOUNT,',
'         CASE M.APPROVAL_STATUS',
'             WHEN ''P'' THEN ''<span style="',
'                    background:#f59e0b;',
'                    color:white;',
'                    padding:3px 8px;',
'                    border-radius:12px;',
'                    font-size:11px;',
'                    font-weight:600;">',
'                    Pending',
'                </span>''',
'             WHEN ''A'' THEN ''<span style="',
'                    background:#22c55e;',
'                    color:white;',
'                    padding:3px 8px;',
'                    border-radius:12px;',
'                    font-size:11px;',
'                    font-weight:600;">',
'                    Approved',
'                </span>''',
'             WHEN ''R'' THEN ''<span style="',
'                    background:#ef4444;',
'                    color:white;',
'                    padding:3px 8px;',
'                    border-radius:12px;',
'                    font-size:11px;',
'                    font-weight:600;">',
'                    Rejected',
'                </span>''',
'         END                                 AS APPROVAL_STATUS,',
'         NULL                                AS DETAILS,',
'         M.CREATED_BY,',
'         M.CREATED_DATE',
'    FROM TRN_DELIVERY_MST M',
'         JOIN TRN_SALES_INVOICE_MST I ON I.INVOICE_NO = M.INVOICE_NO',
'         JOIN MST_CUSTOMER C ON C.CUSTOMER_NO = M.CUSTOMER_NO',
'         LEFT JOIN',
'         (  SELECT D.DELIVERY_NO,',
'                   SUM (NVL (D.DELIVERY_QTY, 0))',
'                       AS TOTAL_QTY,',
'                   SUM (NVL (D.DELIVERY_QTY, 0) * NVL (D.SALES_RATE, 0))',
'                       AS GROSS_AMOUNT,',
'                   SUM (',
'                         NVL (D.DELIVERY_QTY, 0)',
'                       * NVL (D.SALES_RATE, 0)',
'                       * NVL (ID.DISCOUNT_PERCENT, 0)',
'                       / 100)',
'                       AS TOTAL_DISCOUNT_AMOUNT,',
'                   SUM (NVL (D.TOTAL_AMOUNT, 0))',
'                       AS TOTAL_AMOUNT',
'              FROM TRN_DELIVERY_DTL D',
'                   LEFT JOIN TRN_SALES_INVOICE_DTL ID',
'                       ON ID.INVOICE_DTL_NO = D.INVOICE_DTL_NO',
'          GROUP BY D.DELIVERY_NO) X',
'             ON X.DELIVERY_NO = M.DELIVERY_NO',
'   WHERE M.APPROVAL_STATUS = ''P''',
'ORDER BY M.DELIVERY_NO DESC'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header_font_color=>'#000000'
