,p_created_on=>wwv_flow_imp.dz('20260906113346Z')
,p_updated_on=>wwv_flow_imp.dz('20260906113346Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
end;
/
prompt --application/pages/page_00207
begin
wwv_flow_imp_page.create_page(
 p_id=>207
,p_name=>'Daily Invoice'
,p_alias=>'DAILY-INVOICE1'
,p_step_title=>'Daily Invoice'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function printSingleInvoice(btn) {',
'',
'    var invoice = btn.closest(".inv-report-card");',
'',
'    if (!invoice) return;',
'',
'    var printWindow = window.open("", "_blank", "width=950,height=750");',
'',
'    if (!printWindow) {',
'        apex.message.alert("Please allow pop-ups for this site.");',
'        return;',
'    }',
'',
'    var styles = "";',
'',
'    document.querySelectorAll("link[rel=''stylesheet''], style")',
'        .forEach(function(el) {',
'            styles += el.outerHTML;',
'        });',
'',
'    printWindow.document.write(`',
'        <html>',
'        <head>',
'            <title>Invoice</title>',
'',
'            ${styles}',
'',
'            <style>',
'                @page {',
'                    size: A4;',
'                    margin: 10mm;',
'                }',
'',
'                .invoice-print-btn {',
'                    display: none !important;',
'                }',
'            </style>',
'        </head>',
'',
'        <body>',
'            ${invoice.outerHTML}',
'        </body>',
'        </html>',
'    `);',
'',
'    printWindow.document.close();',
'',
'    setTimeout(function () {',
'        printWindow.print();',
'        printWindow.close();',
'    }, 700);',
'}'))
,p_step_template=>4073832297226169690
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'25'
,p_created_on=>wwv_flow_imp.dz('20260829130906Z')
,p_last_updated_on=>wwv_flow_imp.dz('20260907160457Z')
,p_created_by=>'ADMIN'
,p_last_updated_by=>'ADMIN'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(43627045570751417171)
,p_plug_name=>'Breadcrumb'
,p_static_id=>'breadcrumb-2'
,p_region_css_classes=>'breadcrumb'
,p_region_template_options=>'#DEFAULT#:t-ButtonRegion--stickToBottom:t-ButtonRegion--slimPadding:t-ButtonRegion--noBorder:t-Form--slimPadding:margin-top-none:margin-bottom-none'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2127905476394690047
,p_plug_display_sequence=>30
,p_plug_display_point=>'REGION_POSITION_01'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_menu_id=>wwv_flow_imp.id(8032859741578477854)
,p_plug_source_type=>'NATIVE_BREADCRUMB'
,p_menu_template_id=>4073839682315169711
,p_created_on=>wwv_flow_imp.dz('20260829130906Z')
,p_updated_on=>wwv_flow_imp.dz('20260829130906Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(11824008772848532)
,p_plug_name=>'Invoice Preview'
,p_static_id=>'invoice-preview'
,p_parent_plug_id=>wwv_flow_imp.id(11823868235848530)
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>90
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 9/7/2026 3:56:48 PM (QP5 v5.388) */',
'DECLARE',
'    v_html            CLOB := '''';',
'    v_invoice_count   NUMBER := 0;',
'BEGIN',
'    FOR H',
'        IN (  SELECT I.INVOICE_NO,',
'                     I.INVOICE_CODE,',
'                     I.INVOICE_DATE,',
'                     O.ORDER_CODE,',
'                     C.CUSTOMER_NO,',
'                     C.CUSTOMER_CODE,',
'                     C.CUSTOMER_NAME,',
'                     C.MOBILE_NO,',
'                     C.EMAIL_ADDRESS,',
'                     C.ADDRESS,',
'                     NVL (I.TOTAL_AMOUNT, 0)        AS TOTAL_AMOUNT,',
'                     NVL (I.RECEIVED_AMOUNT, 0)     AS RECEIVED_AMOUNT,',
'                     NVL (I.DUE_AMOUNT, 0)          AS DUE_AMOUNT,',
'                     I.PAYMENT_STATUS,',
'                     I.DELIVERY_STATUS,',
'                     I.DELIVERY_BY,',
'                     I.DELIVERY_DATE,',
'                     I.CREATED_BY,',
'                     I.CREATED_DATE',
'               FROM TRN_SALES_INVOICE_MST I',
'                    LEFT JOIN MST_CUSTOMER C ON C.CUSTOMER_NO = I.CUSTOMER_NO',
'                    LEFT JOIN TRN_SALES_ORDER_MST O ON O.ORDER_NO = I.ORDER_NO',
'              --   WHERE     /* =========================',
'              --                FROM DATE',
'              --                ========================= */',
'',
'              --             (   :P207_FROM_DATE IS NULL',
'              --              OR I.INVOICE_DATE >=',
'              --                 TO_DATE ( :P207_FROM_DATE, ''MM/DD/YYYY''))',
'              /* =========================',
'                 TO DATE',
'                 ========================= */',
'',
'              -- WHERE (   :P207_TO_DATE IS NULL',
'              --      OR I.INVOICE_DATE <',
'              --         TO_DATE ( :P207_TO_DATE, ''MM/DD/YYYY'') + 1)',
'              /* =========================',
'                 CUSTOMER FILTER',
'                 ========================= */',
'',
'              WHERE (                     -- :P207_CUSTOMER_NO_PREVIEW IS NULL',
'                        --  OR',
'                        I.CUSTOMER_NO = :P207_CUSTOMER_NO_PREVIEW',
'                     OR I.INVOICE_NO = :P207_INVOICE_NO_PREVIEW)',
'           /* =========================',
'              INVOICE FILTER',
'              ========================= */',
'',
'           -- AND (  :P207_INVOICE_NO_PREVIEW IS NULL',
'           --      OR',
'           --       I.INVOICE_NO = :P207_INVOICE_NO_PREVIEW)',
'           ORDER BY I.INVOICE_DATE DESC, I.INVOICE_NO DESC)',
'    LOOP',
'        v_invoice_count := v_invoice_count + 1;',
'',
'        v_html := v_html || ''<div class="inv-report-card">'';',
'        v_html := v_html || ''<div class="invoice-print-btn">',
'',
'                <button',
'                    type="button"',
'                    onclick="printSingleInvoice(this)"',
'                    title="Print Invoice">',
'',
'                    <span class="fa fa-print"></span>',
'',
'                </button>',
'',
'            </div>'';',
'',
'        v_html := v_html || ''<div class="inv-header">',
'                <div class="inv-company">',
'',
'                    <div class="inv-company-name">',
'',
'                        <span class="fa fa-bolt"></span>',
'',
'                        Dealer Inventory &amp; Sales',
'',
'                    </div>',
'',
'                    <div class="inv-company-sub">',
'                        Sales Invoice',
'                    </div>',
'',
'                </div>',
'                <div class="inv-title">',
'',
'                    <div class="inv-title-main">',
'',
'                        <span class="fa fa-file-text-o"></span>',
'',
'                        INVOICE',
'',
'                    </div>',
'',
'                    <div class="inv-copy">',
'                        Original for Customer',
'                    </div>',
'',
'                </div>',
'',
'',
'            </div>',
'',
'',
'            <div class="inv-line"></div>'';',
'',
'        v_html :=',
'               v_html',
'            || ''<div class="inv-info">',
'',
'',
'                <div class="inv-left">',
'',
'',
'                    <div>',
'',
'                        <span class="fa fa-hashtag"></span>',
'',
'                        <b>Invoice No:</b>',
'',
'                        ''',
'            || APEX_ESCAPE.HTML (H.INVOICE_CODE)',
'            || ''',
'',
'                    </div>',
'                    <div>',
'',
'                        <span class="fa fa-calendar"></span>',
'',
'                        <b>Invoice Date:</b>',
'',
'                        ''',
'            || TO_CHAR (H.INVOICE_DATE, ''DD-MON-YYYY'')',
'            || ''',
'',
'                    </div>'';',
'',
'',
'        /* ORDER */',
'',
'        IF H.ORDER_CODE IS NOT NULL',
'        THEN',
'            v_html := v_html || ''<div>',
'',
'                    <span class="fa fa-shopping-cart"></span>',
'',
'                    <b>Order No:</b>',
'',
'                    '' || APEX_ESCAPE.HTML (H.ORDER_CODE) || ''',
'',
'                </div>'';',
'        END IF;',
'',
'',
'        /* CUSTOMER */',
'',
'        v_html :=',
'               v_html',
'            || ''<div>',
'',
'                <span class="fa fa-user"></span>',
'',
'                <b>Customer:</b>',
'',
'                ''',
'            || APEX_ESCAPE.HTML (H.CUSTOMER_NAME)',
'            || ''',
'',
'            </div>',
'',
'',
'            <div>',
'',
'                <span class="fa fa-phone"></span>',
'',
'                <b>Mobile:</b>',
'',
'                ''',
'            || APEX_ESCAPE.HTML (H.MOBILE_NO)',
'            || ''',
'',
'            </div>',
'',
'',
'            </div>',
'',
'',
'            <div class="inv-right">',
'',
'',
'                <!-- PAYMENT -->',
'',
'                <div>',
'',
'                    <span class="fa fa-credit-card"></span>',
'',
'                    <b>Payment:</b>'';',
'',
'',
'        /* =====================================================',
'           PAYMENT STATUS',
'           P  = PAID',
'           PP = PARTIAL PAID',
'           UP  = UNPAID',
'           ===================================================== */',
'',
'        IF UPPER (NVL (H.PAYMENT_STATUS, ''UP'')) = ''P''',
'        THEN',
'            v_html := v_html || ''<span class="status-badge status-paid">',
'',
'                    <span class="fa fa-check-circle"></span>',
'',
'                    Paid',
'',
'                </span>'';',
'        ELSIF UPPER (NVL (H.PAYMENT_STATUS, ''UP'')) = ''PP''',
'        THEN',
'            v_html := v_html || ''<span class="status-badge status-partial">',
'',
'                    <span class="fa fa-adjust"></span>',
'',
'                    Partial Paid',
'',
'                </span>'';',
'        ELSE',
'            v_html := v_html || ''<span class="status-badge status-unpaid">',
'',
'                    <span class="fa fa-exclamation-circle"></span>',
'',
'                    Unpaid',
'',
'                </span>'';',
'        END IF;',
'',
'',
'        v_html := v_html || ''</div>',
'',
'',
'            <!-- DELIVERY -->',
'',
'            <div>',
'',
'                <span class="fa fa-truck"></span>',
'',
'                <b>Delivery:</b>'';',
'',
'',
'        /* =====================================================',
'           DELIVERY STATUS',
'           D = DELIVERED',
'           P = PENDING',
'           ===================================================== */',
'',
'        IF UPPER (NVL (H.DELIVERY_STATUS, ''P'')) = ''D''',
'        THEN',
'            v_html :=',
'                v_html || ''<span class="status-badge status-delivered">',
'',
'                    <span class="fa fa-check"></span>',
'',
'                    Delivered',
'',
'                </span>'';',
'        ELSE',
'            v_html := v_html || ''<span class="status-badge status-pending">',
'',
'                    <span class="fa fa-clock-o"></span>',
'',
'                    Pending',
'',
'                </span>'';',
'        END IF;',
'',
'',
'        v_html :=',
'            v_html || ''</div>',
'',
'',
'            <!-- DUE -->',
'',
'            <div>',
'',
'                <span class="fa fa-money"></span>',
'',
'                <b>Due:</b>',
'',
'                <span class="due-value">',
'',
unistr('                    \09F3 '' || TO_CHAR (H.DUE_AMOUNT, ''FM9999999990.00'') || '''),
'',
'                </span>',
'',
'            </div>',
'',
'',
'            </div>',
'',
'',
'            </div>'';',
'',
'',
'        /* =====================================================',
'           PRODUCT TABLE',
'           ===================================================== */',
'',
'        v_html := v_html || ''<table class="inv-table">',
'',
'',
'                <thead>',
'',
'                    <tr>',
'',
'                        <th class="sl">#</th>',
'',
'                        <th>Product</th>',
'',
'                        <th class="num">Qty</th>',
'',
'                        <th class="num">Delivered</th>',
'',
'                        <th class="num">Return</th>',
'',
'                        <th class="num">Balance</th>',
'',
'                        <th class="num">Rate</th>',
'                        <th class="num">Discount %</th>',
'',
'                        <th class="num">Amount</th>',
'',
'                    </tr>',
'',
'                </thead>',
'',
'',
'                <tbody>'';',
'',
'',
'        /* =====================================================',
'           PRODUCT DETAILS',
'           ===================================================== */',
'',
'        DECLARE',
'            v_sl   NUMBER := 0;',
'        BEGIN',
'            FOR D',
'                IN (  SELECT D.INVOICE_DTL_NO,',
'                             P.PRODUCT_CODE,',
'                             P.PRODUCT_NAME,',
'                             PC.CATEGORY_NAME,',
'                             NVL (D.SALES_QTY, 0)',
'                                 AS SALES_QTY,',
'                             NVL (D.DELIVERED_QTY, 0)',
'                                 AS DELIVERED_QTY,',
'                             NVL (D.SALES_QTY, 0) - NVL (D.DELIVERED_QTY, 0)',
'                                 AS BALANCE_QTY,',
'                             NVL (D.SALES_RATE, 0)',
'                                 AS SALES_RATE,',
'                             NVL (D.TOTAL_AMOUNT, 0)',
'                                 AS TOTAL_AMOUNT,',
'                             NVL (R.RETURN_QTY, 0)',
'                                 AS RETURN_QTY,',
'                                   NVL (D.DISCOUNT_PERCENT, 0)',
'                                 AS DISCOUNT_PERCENT',
'                                 ',
'                       FROM TRN_SALES_INVOICE_DTL D',
'                            LEFT JOIN MST_PRODUCT P',
'                                ON P.PRODUCT_NO = D.PRODUCT_NO',
'                            LEFT JOIN MST_PRODUCT_CATEGORY PC',
'                                ON PC.CATEGORY_NO = P.CATEGORY_NO',
'                            LEFT JOIN',
'                            (  SELECT RD.INVOICE_DTL_NO,',
'                                      SUM (NVL (RD.RETURN_QTY, 0))    AS RETURN_QTY',
'                                 FROM TRN_CUSTOMER_RETURN_DTL RD',
'                                      JOIN TRN_CUSTOMER_RETURN_MST RM',
'                                          ON RM.RETURN_NO = RD.RETURN_NO',
'                                WHERE RM.APPROVAL_STATUS = ''A''',
'                             GROUP BY RD.INVOICE_DTL_NO) R',
'                                ON R.INVOICE_DTL_NO = D.INVOICE_DTL_NO',
'                      WHERE D.INVOICE_NO = H.INVOICE_NO',
'                   ORDER BY D.INVOICE_DTL_NO)',
'            LOOP',
'                v_sl := v_sl + 1;',
'',
'',
'                v_html :=',
'                       v_html',
'                    || ''<tr>',
'',
'',
'                        <td class="sl">',
'',
'                            ''',
'                    || v_sl',
'                    || ''',
'',
'                        </td>',
'',
'',
'                        <td>',
'',
'                            <div class="product-name">',
'',
'                                ''',
'                    || APEX_ESCAPE.HTML (D.PRODUCT_NAME)',
'                    || ''',
'',
'                            </div>',
'',
'',
'                            <div class="product-code">',
'',
'                                ''',
'                    || APEX_ESCAPE.HTML (D.PRODUCT_CODE)',
'                    || ''',
'',
'                            </div>',
'',
'                        </td>',
'',
'',
'                        <td class="num">',
'',
'                            ''',
'                    || TO_CHAR (D.SALES_QTY, ''FM999999990.00'')',
'                    || ''',
'',
'                        </td>',
'',
'',
'                        <td class="num">',
'',
'                            ''',
'                    || TO_CHAR (D.DELIVERED_QTY, ''FM999999990.00'')',
'                    || ''',
'',
'                        </td>',
'',
'',
'                        <td class="num return-value">',
'',
'                            ''',
'                    || TO_CHAR (D.RETURN_QTY, ''FM999999990.00'')',
'                    || ''',
'',
'                        </td>',
'',
'',
'                        <td class="num">',
'',
'                            ''',
'                    || TO_CHAR (D.BALANCE_QTY, ''FM999999990.00'')',
'                    || ''',
'',
'                        </td>',
'',
'',
'                        <td class="num">',
'',
'                            ''',
'                    || TO_CHAR (D.SALES_RATE, ''FM999999990.00'')',
'                    || ''',
'',
'                        </td>',
'                        ',
'                          <td class="num">',
'',
'                            ''',
'                    || TO_CHAR (D.DISCOUNT_PERCENT, ''FM999999990.00'')',
'                    || ''',
'',
'                        </td>',
'',
'',
'                        <td class="num amount">',
'',
'                            ''',
'                    || TO_CHAR (D.TOTAL_AMOUNT, ''FM9999999990.00'')',
'                    || ''',
'',
'                        </td>',
'',
'',
'                    </tr>'';',
'            END LOOP;',
'        END;',
'',
'',
'        v_html := v_html || ''</tbody>',
'',
'            </table>'';',
'',
'',
'        /* =====================================================',
'           TOTAL SECTION',
'           ===================================================== */',
'',
'        v_html := v_html || ''<div class="inv-total-area">',
'',
'',
'                <div class="inv-total-left">',
'',
'                    <div class="small-note">',
'',
'                        <span class="fa fa-info-circle"></span>',
'',
'                        Payment Status:',
'',
'                        <b>'';',
'',
'',
'        /* PAYMENT TEXT */',
'',
'        IF UPPER (NVL (H.PAYMENT_STATUS, ''UP'')) = ''P''',
'        THEN',
'            v_html := v_html || ''Paid'';',
'        ELSIF UPPER (NVL (H.PAYMENT_STATUS, ''UP'')) = ''PP''',
'        THEN',
'            v_html := v_html || ''Partial Paid'';',
'        ELSE',
'            v_html := v_html || ''Unpaid'';',
'        END IF;',
'',
'',
'        v_html :=',
'               v_html',
'            || ''</b>',
'',
'                    </div>',
'',
'                </div>',
'',
'',
'                <div class="inv-total-right">',
'',
'',
'                    <div class="total-row">',
'',
'                        <span>',
'',
'                            <span class="fa fa-calculator"></span>',
'',
'                            Invoice Total',
'',
'                        </span>',
'',
'                        <b>',
'',
unistr('                            \09F3 '''),
'            || TO_CHAR (H.TOTAL_AMOUNT, ''FM9999999990.00'')',
'            || ''',
'',
'                        </b>',
'',
'                    </div>',
'',
'',
'                    <div class="total-row received-row">',
'',
'                        <span>',
'',
'                            <span class="fa fa-check-circle"></span>',
'',
'                            Received',
'',
'                        </span>',
'',
'                        <b>',
'',
unistr('                            \09F3 '''),
'            || TO_CHAR (H.RECEIVED_AMOUNT, ''FM9999999990.00'')',
'            || ''',
'',
'                        </b>',
'',
'                    </div>',
'',
'',
'                    <div class="total-row due-row">',
'',
'                        <span>',
'',
'                            <span class="fa fa-exclamation-circle"></span>',
'',
'                            Due',
'',
'                        </span>',
'',
'                        <b>',
'',
unistr('                            \09F3 '''),
'            || TO_CHAR (H.DUE_AMOUNT, ''FM9999999990.00'')',
'            || ''',
'',
'                        </b>',
'',
'                    </div>',
'',
'',
'                </div>',
'',
'',
'            </div>'';',
'',
'',
'        /* =====================================================',
'           PAID WATERMARK',
'           ===================================================== */',
'',
'        IF UPPER (NVL (H.PAYMENT_STATUS, ''UP'')) = ''P''',
'        THEN',
'            v_html := v_html || ''<div class="paid-watermark">',
'',
'                    <span class="fa fa-check-circle"></span>',
'',
'                    PAID',
'',
'                </div>'';',
'        END IF;',
'',
'',
'        /* =====================================================',
'           FOOTER',
'           ===================================================== */',
'',
'        v_html :=',
'               v_html',
'            || ''<div class="inv-footer">',
'',
'',
'                <span>',
'',
'                    <span class="fa fa-user"></span>',
'',
'                    Prepared By:',
'',
'                    ''',
'            || NVL (APEX_ESCAPE.HTML (H.CREATED_BY), ''-'')',
'            || ''',
'',
'                </span>',
'',
'',
'                <span>',
'',
'                    <span class="fa fa-clock-o"></span>',
'',
'                    ''',
'            || TO_CHAR (H.CREATED_DATE, ''DD-MON-YYYY HH24:MI'')',
'            || ''',
'',
'                </span>',
'',
'',
'            </div>',
'',
'',
'            </div>'';',
'    END LOOP;',
'',
'',
'    /* =========================================================',
'       NO DATA',
'       ========================================================= */',
'',
'    IF v_invoice_count = 0',
'    THEN',
'        v_html := ''<div class="no-invoice">',
'',
'',
'                <div class="no-invoice-icon">',
'',
'                    <span class="fa fa-file-text-o"></span>',
'',
'                </div>',
'',
'',
'                <div class="no-invoice-title">',
'',
'                    No Invoice Found',
'',
'                </div>',
'',
'',
'                <div class="no-invoice-text">',
'',
'                    No invoice matches the selected filter.',
'',
'                </div>',
'',
'',
'            </div>'';',
'    END IF;',
'',
'',
'    /* =========================================================',
'       CSS',
'       ========================================================= */',
'',
'    v_html := ''<style>',
'',
'',
'        /* =========================================',
'           INVOICE CARD',
'           ========================================= */',
'',
