,p_last_updated_by=>'ADMIN'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(44017655840765066450)
,p_plug_name=>'Breadcrumb'
,p_static_id=>'breadcrumb'
,p_region_css_classes=>'breadcrumb'
,p_region_template_options=>'#DEFAULT#:t-ButtonRegion--stickToBottom:t-ButtonRegion--slimPadding:t-ButtonRegion--noBorder:t-Form--slimPadding:margin-top-none:margin-bottom-none'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2127905476394690047
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_01'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_menu_id=>wwv_flow_imp.id(8032859741578477854)
,p_plug_source_type=>'NATIVE_BREADCRUMB'
,p_menu_template_id=>4073839682315169711
,p_created_on=>wwv_flow_imp.dz('20260819181712Z')
,p_updated_on=>wwv_flow_imp.dz('20260819181712Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(27209247358893360012)
,p_plug_name=>'General Ledger'
,p_static_id=>'voucher-mst'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>50
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_html              CLOB;',
'',
'    v_last_account      VARCHAR2(100) := NULL;',
'    v_account_type      VARCHAR2(10)  := NULL;',
'    v_account_code      VARCHAR2(100) := NULL;',
'    v_account_name      VARCHAR2(500) := NULL;',
'',
'    v_account_opening   NUMBER := 0;',
'    v_account_total_dr  NUMBER := 0;',
'    v_account_total_cr  NUMBER := 0;',
'    v_account_closing   NUMBER := 0;',
'',
'BEGIN',
'',
'    /* =========================================================',
'       HTML HEADER + CSS',
'       ========================================================= */',
'',
'    v_html := q''[',
'<style>',
'',
'.gl-container {',
'    width:100%;',
'    box-sizing:border-box;',
'    font-family:Arial,sans-serif;',
'    background:#fff;',
'    border:1px solid #e1e5e9;',
'    border-radius:8px;',
'    overflow:hidden;',
'}',
'',
'.gl-header {',
'    padding:15px 18px;',
'    background:#fafbfc;',
'    border-bottom:1px solid #e5e9ed;',
'}',
'',
'.gl-title {',
'    font-size:20px;',
'    font-weight:700;',
'    color:#26343f;',
'}',
'',
'.gl-subtitle {',
'    margin-top:4px;',
'    font-size:11px;',
'    color:#7a8793;',
'}',
'',
'.gl-account {',
'    margin:12px;',
'    border:1px solid #dce4ea;',
'    border-radius:7px;',
'    overflow:hidden;',
'}',
'',
'.gl-account-header {',
'    padding:10px 12px;',
'    background:#f1f4f7;',
'    border-bottom:1px solid #dce4ea;',
'}',
'',
'.gl-account-code {',
'    font-size:10px;',
'    color:#71808d;',
'}',
'',
'.gl-account-name {',
'    margin-top:2px;',
'    font-size:14px;',
'    font-weight:700;',
'    color:#26343f;',
'}',
'',
'.gl-opening {',
'    margin-top:4px;',
'    font-size:11px;',
'    color:#526170;',
'}',
'',
'.gl-table-wrapper {',
'    width:100%;',
'    overflow-x:auto;',
'}',
'',
'.gl-table {',
'    width:100%;',
'    min-width:900px;',
'    border-collapse:collapse;',
'    table-layout:fixed;',
'}',
'',
'.gl-table th {',
'    padding:8px 7px;',
'    background:#f8fafb;',
'    border-bottom:1px solid #e5e9ed;',
'    font-size:10px;',
'    color:#526170;',
'    font-weight:700;',
'    text-align:left;',
'}',
'',
'.gl-table td {',
'    padding:7px;',
'    border-bottom:1px solid #f0f2f4;',
'    font-size:10px;',
'    color:#34424d;',
'    vertical-align:top;',
'}',
'',
'.gl-table .right {',
'    text-align:right;',
'}',
'',
'.gl-table .center {',
'    text-align:center;',
'}',
'',
'.gl-date {',
'    white-space:nowrap;',
'    color:#667684;',
'}',
'',
'.gl-voucher {',
'    font-weight:600;',
'    color:#286090;',
'}',
'',
'.gl-particular {',
'    line-height:1.35;',
'}',
'',
'.gl-ref {',
'    margin-top:2px;',
'    font-size:9px;',
'    color:#7a8793;',
'}',
'',
'.gl-dr {',
'    color:#286090 !important;',
'    font-weight:600;',
'}',
'',
'.gl-cr {',
'    color:#c0392b !important;',
'    font-weight:600;',
'}',
'',
'.gl-balance {',
'    font-weight:700;',
'}',
'',
'.gl-total {',
'    background:#fafbfc;',
'}',
'',
'.gl-total td {',
'    padding:8px 7px;',
'    border-top:1px solid #dfe5ea;',
'    font-weight:700;',
'}',
'',
'.gl-footer {',
'    padding:8px 12px;',
'    background:#fafbfc;',
'    border-top:1px solid #e5e9ed;',
'    font-size:10px;',
'    color:#71808d;',
'    text-align:right;',
'}',
'',
'.gl-no-data {',
'    padding:35px 15px;',
'    text-align:center;',
'    color:#7a8793;',
'    font-size:12px;',
'}',
'',
'@media(max-width:768px) {',
'',
'    .gl-container {',
'        border-radius:5px;',
'    }',
'',
'    .gl-account {',
'        margin:7px;',
'    }',
'',
'    .gl-title {',
'        font-size:17px;',
'    }',
'',
'}',
'',
'</style>',
'',
'<div class="gl-container">',
'',
'    <div class="gl-header">',
'',
'        <div class="gl-title">',
'            General Ledger',
'        </div>',
'',
'        <div class="gl-subtitle">',
'            Account Transaction Statement',
']'';',
'',
'',
'    /* =========================================================',
'       DATE',
'       ========================================================= */',
'',
'    IF :P303_FROM_DATE IS NOT NULL',
'    THEN',
'',
'        v_html :=',
'            v_html',
'            || '' | From: ''',
'            || APEX_ESCAPE.HTML(',
'                   TO_CHAR(:P303_FROM_DATE)',
'               );',
'',
'    END IF;',
'',
'',
'    IF :P303_TO_DATE IS NOT NULL',
'    THEN',
'',
'        v_html :=',
'            v_html',
'            || '' | To: ''',
'            || APEX_ESCAPE.HTML(',
'                   TO_CHAR(:P303_TO_DATE)',
'               );',
'',
'    END IF;',
'',
'',
'    v_html :=',
'        v_html',
'        || q''[',
'        </div>',
'',
'    </div>',
']'';',
'',
'',
'    /* =========================================================',
'       MAIN LOOP',
'       ========================================================= */',
'',
'    FOR R IN',
'    (',
'        WITH TXN AS',
'        (',
'            SELECT',
'                D.VOUCHER_DTL_NO,',
'                D.ACCOUNT_NO,',
'',
'                H.ACCOUNT_CODE,',
'                H.ACCOUNT_NAME,',
'                H.ACCOUNT_TYPE,',
'',
'                M.VOUCHER_NO,',
'                M.VOUCHER_DATE,',
'                M.VOUCHER_CODE,',
'                M.VOUCHER_TYPE,',
'',
'                D.REF_TYPE,',
'                D.REF_NO,',
'                D.PARTICULARS,',
'',
'                NVL(D.DEBIT_AMOUNT,0) AS DEBIT_AMOUNT,',
'                NVL(D.CREDIT_AMOUNT,0) AS CREDIT_AMOUNT',
'',
'            FROM ACC_VOUCHER_MST M',
'',
'            JOIN ACC_VOUCHER_DTL D',
'              ON D.VOUCHER_NO = M.VOUCHER_NO',
'',
'            JOIN MST_ACCOUNT_HEAD H',
'              ON H.ACCOUNT_NO = D.ACCOUNT_NO',
'',
'            WHERE M.APPROVAL_STATUS = ''A''',
'',
'              /* ============================================',
'                 ACCOUNT FILTER',
'                 Explicit character comparison',
'                 ============================================ */',
'',
'              AND',
'              (',
'                  :P303_ACCOUNT_NO IS NULL',
'                  OR TO_CHAR(D.ACCOUNT_NO) =',
'                     TO_CHAR(:P303_ACCOUNT_NO)',
'              )',
'',
'              /* ============================================',
'                 FROM DATE',
'                 ============================================ */',
'',
'              AND',
'              (',
'                  :P303_FROM_DATE IS NULL',
'',
'                  OR M.VOUCHER_DATE >=',
'                     TO_DATE(',
'                         :P303_FROM_DATE,',
'                         ''DD-MON-YYYY''',
'                     )',
'              )',
'',
'              /* ============================================',
'                 TO DATE',
'                 ============================================ */',
'',
'              AND',
'              (',
'                  :P303_TO_DATE IS NULL',
'',
'                  OR M.VOUCHER_DATE <',
'                     TO_DATE(',
'                         :P303_TO_DATE,',
'                         ''DD-MON-YYYY''',
'                     ) + 1',
'              )',
'',
'              /* ============================================',
'                 VOUCHER TYPE',
'                 ============================================ */',
'',
'              AND',
'              (',
'                  :P303_VOUCHER_TYPE IS NULL',
'                  OR M.VOUCHER_TYPE =',
'                     :P303_VOUCHER_TYPE',
'              )',
'        ),',
'',
'',
'        /* =====================================================',
'           OPENING BALANCE',
'           ===================================================== */',
'',
'        OPENING AS',
'        (',
'            SELECT',
'                ACCOUNT_NO,',
'                ACCOUNT_TYPE,',
'',
'                SUM(OPENING_BALANCE)',
'                    AS OPENING_BALANCE',
'',
'            FROM',
'            (',
'',
'                /* =============================================',
'                   ACCOUNT OPENING',
'                   ============================================= */',
'',
'                SELECT',
'                    O.ACCOUNT_NO,',
'                    H.ACCOUNT_TYPE,',
'',
'                    CASE',
'',
'                        WHEN H.ACCOUNT_TYPE IN (''A'',''E'')',
'                        THEN',
'                            NVL(O.OPENING_DEBIT,0)',
'                            -',
'                            NVL(O.OPENING_CREDIT,0)',
'',
'                        WHEN H.ACCOUNT_TYPE IN (''L'',''C'',''I'')',
'                        THEN',
'                            NVL(O.OPENING_CREDIT,0)',
'                            -',
'                            NVL(O.OPENING_DEBIT,0)',
'',
'                        ELSE',
'                            0',
'',
'                    END AS OPENING_BALANCE',
'',
'                FROM ACC_OPENING_BALANCE O',
'',
'                JOIN MST_ACCOUNT_HEAD H',
'                  ON H.ACCOUNT_NO = O.ACCOUNT_NO',
'',
'                WHERE O.APPROVAL_STATUS = ''A''',
'',
'                  AND',
'                  (',
'                      :P303_ACCOUNT_NO IS NULL',
'',
'                      OR TO_CHAR(O.ACCOUNT_NO) =',
'                         TO_CHAR(:P303_ACCOUNT_NO)',
'                  )',
'',
'',
'                UNION ALL',
'',
'',
'                /* =============================================',
'                   PREVIOUS TRANSACTIONS',
'                   ============================================= */',
'',
'                SELECT',
'                    D.ACCOUNT_NO,',
'                    H.ACCOUNT_TYPE,',
'',
'                    CASE',
'',
'                        WHEN H.ACCOUNT_TYPE IN (''A'',''E'')',
'                        THEN',
'                            NVL(D.DEBIT_AMOUNT,0)',
'                            -',
'                            NVL(D.CREDIT_AMOUNT,0)',
'',
'                        WHEN H.ACCOUNT_TYPE IN (''L'',''C'',''I'')',
'                        THEN',
'                            NVL(D.CREDIT_AMOUNT,0)',
'                            -',
'                            NVL(D.DEBIT_AMOUNT,0)',
'',
'                        ELSE',
'                            0',
'',
'                    END AS OPENING_BALANCE',
'',
'                FROM ACC_VOUCHER_MST M',
'',
'                JOIN ACC_VOUCHER_DTL D',
'                  ON D.VOUCHER_NO = M.VOUCHER_NO',
'',
'                JOIN MST_ACCOUNT_HEAD H',
'                  ON H.ACCOUNT_NO = D.ACCOUNT_NO',
'',
'                WHERE M.APPROVAL_STATUS = ''A''',
'',
'                  AND :P303_FROM_DATE IS NOT NULL',
'',
'                  AND M.VOUCHER_DATE <',
'                      TO_DATE(',
'                          :P303_FROM_DATE,',
'                          ''DD-MON-YYYY''',
'                      )',
'',
'                  AND',
'                  (',
'                      :P303_ACCOUNT_NO IS NULL',
'',
'                      OR TO_CHAR(D.ACCOUNT_NO) =',
'                         TO_CHAR(:P303_ACCOUNT_NO)',
'                  )',
'',
'            )',
'',
'            GROUP BY',
'                ACCOUNT_NO,',
'                ACCOUNT_TYPE',
'        ),',
'',
'',
'        /* =====================================================',
'           RUNNING BALANCE',
'           ===================================================== */',
'',
'        RUNNING AS',
'        (',
'            SELECT',
'                T.*,',
'',
'                NVL(',
'                    O.OPENING_BALANCE,',
'                    0',
'                ) AS OPENING_BALANCE,',
'',
'',
'                SUM(',
'',
'                    CASE',
'',
'                        WHEN T.ACCOUNT_TYPE IN (''A'',''E'')',
'                        THEN',
'                            T.DEBIT_AMOUNT',
'                            -',
'                            T.CREDIT_AMOUNT',
'',
'                        WHEN T.ACCOUNT_TYPE IN (''L'',''C'',''I'')',
'                        THEN',
'                            T.CREDIT_AMOUNT',
'                            -',
'                            T.DEBIT_AMOUNT',
'',
'                        ELSE',
'                            0',
'',
'                    END',
'',
'                )',
'                OVER',
'                (',
'                    PARTITION BY T.ACCOUNT_NO',
'',
'                    ORDER BY',
'                        T.VOUCHER_DATE,',
'                        T.VOUCHER_NO,',
'                        T.VOUCHER_DTL_NO',
'',
'                    ROWS BETWEEN',
'                        UNBOUNDED PRECEDING',
'                        AND CURRENT ROW',
'',
'                ) AS MOVEMENT_BALANCE',
'',
'            FROM TXN T',
'',
'            LEFT JOIN OPENING O',
'              ON O.ACCOUNT_NO = T.ACCOUNT_NO',
'        )',
'',
'',
'        /* =====================================================',
'           FINAL DATA',
'           ===================================================== */',
'',
'        SELECT',
'',
'            ROW_NUMBER()',
'            OVER',
'            (',
'                ORDER BY',
'                    ACCOUNT_NO,',
'                    VOUCHER_DATE,',
'                    VOUCHER_NO,',
'                    VOUCHER_DTL_NO',
'            ) AS SL,',
'',
'            VOUCHER_NO,',
'            VOUCHER_CODE,',
'            VOUCHER_DATE,',
'            VOUCHER_TYPE,',
'',
'            ACCOUNT_NO,',
'            ACCOUNT_CODE,',
'            ACCOUNT_NAME,',
'            ACCOUNT_TYPE,',
'',
'            REF_TYPE,',
'            REF_NO,',
'            PARTICULARS,',
'',
'            DEBIT_AMOUNT,',
'            CREDIT_AMOUNT,',
'',
'            OPENING_BALANCE,',
'',
'            OPENING_BALANCE',
'            +',
'            MOVEMENT_BALANCE',
'                AS RUNNING_BALANCE,',
'',
'',
'            CASE',
'',
'                WHEN',
'                    OPENING_BALANCE',
'                    +',
'                    MOVEMENT_BALANCE >= 0',
'',
'                THEN',
'',
'                    CASE',
'',
'                        WHEN ACCOUNT_TYPE IN (''A'',''E'')',
'                        THEN ''DR''',
'',
'                        ELSE ''CR''',
'',
'                    END',
'',
'                ELSE',
'',
'                    CASE',
'',
'                        WHEN ACCOUNT_TYPE IN (''A'',''E'')',
'                        THEN ''CR''',
'',
'                        ELSE ''DR''',
'',
'                    END',
'',
'            END AS BALANCE_TYPE',
'',
'        FROM RUNNING',
'',
'        ORDER BY',
'            ACCOUNT_NO,',
'            VOUCHER_DATE,',
'            VOUCHER_NO,',
'            VOUCHER_DTL_NO',
'',
'    )',
'',
'    LOOP',
'',
'',
'        /* =====================================================',
'           ACCOUNT CHANGE',
'           ===================================================== */',
'',
'        IF v_last_account IS NULL',
'           OR v_last_account <>',
'              TO_CHAR(R.ACCOUNT_NO)',
'        THEN',
'',
'',
'            /* ================================================',
'               CLOSE PREVIOUS ACCOUNT',
'               ================================================ */',
'',
'            IF v_last_account IS NOT NULL',
'            THEN',
'',
'                v_html :=',
'                    v_html',
'                    || q''[',
'                        </tbody>',
'',
'                        <tfoot>',
'',
'                            <tr class="gl-total">',
'',
'                                <td colspan="4">',
'                                    Account Total',
'                                </td>',
'',
'                                <td class="right gl-dr">',
unistr('                                    \09F3 ]'''),
'                    || TO_CHAR(',
'                           v_account_total_dr,',
'                           ''FM999G999G999G990D00''',
'                       )',
'                    || q''[</td>',
'',
'                                <td class="right gl-cr">',
unistr('                                    \09F3 ]'''),
'                    || TO_CHAR(',
'                           v_account_total_cr,',
'                           ''FM999G999G999G990D00''',
'                       )',
'                    || q''[</td>',
'',
'                                <td class="right">',
unistr('                                    \09F3 ]'''),
'                    || TO_CHAR(',
'                           ABS(v_account_closing),',
'                           ''FM999G999G999G990D00''',
'                       )',
'                    || q''[</td>',
'',
'                                <td class="center ]''',
'',
'                    || CASE',
'',
'                           WHEN v_account_closing >= 0',
'                           THEN',
'',
'                               CASE',
'',
'                                   WHEN v_account_type IN (''A'',''E'')',
'                                   THEN ''gl-dr''',
'',
'                                   ELSE ''gl-cr''',
'',
'                               END',
'',
'                           ELSE',
'',
'                               CASE',
'',
'                                   WHEN v_account_type IN (''A'',''E'')',
'                                   THEN ''gl-cr''',
'',
'                                   ELSE ''gl-dr''',
'',
'                               END',
'',
'                       END',
'',
'                    || q''[">',
'',
'                                ]''',
'',
'                    || CASE',
'',
'                           WHEN v_account_closing >= 0',
'                           THEN',
'',
'                               CASE',
'',
'                                   WHEN v_account_type IN (''A'',''E'')',
'                                   THEN ''DR''',
'',
'                                   ELSE ''CR''',
'',
'                               END',
'',
'                           ELSE',
'',
'                               CASE',
'',
'                                   WHEN v_account_type IN (''A'',''E'')',
'                                   THEN ''CR''',
'',
'                                   ELSE ''DR''',
'',
'                               END',
'',
'                       END',
'',
'                    || q''[',
'',
'                                </td>',
'',
'                            </tr>',
'',
'                        </tfoot>',
'',
'                    </table>',
'',
'                    </div>',
'',
'                </div>',
']'';',
'',
'            END IF;',
'',
'',
'            /* ================================================',
'               SAVE CURRENT ACCOUNT',
'               ================================================ */',
'',
'            v_last_account :=',
'                TO_CHAR(R.ACCOUNT_NO);',
'',
'            v_account_type :=',
'                TO_CHAR(R.ACCOUNT_TYPE);',
'',
'            v_account_code :=',
'                TO_CHAR(R.ACCOUNT_CODE);',
'',
'            v_account_name :=',
'                TO_CHAR(R.ACCOUNT_NAME);',
'',
'            v_account_opening :=',
'                NVL(R.OPENING_BALANCE,0);',
'',
'            v_account_total_dr :=',
'                0;',
'',
'            v_account_total_cr :=',
'                0;',
'',
'            v_account_closing :=',
'                NVL(R.OPENING_BALANCE,0);',
'',
'',
'            /* ================================================',
'               ACCOUNT HEADER',
'               ================================================ */',
'',
'            v_html :=',
'                v_html',
'                || q''[',
'',
'                <div class="gl-account">',
'',
'                    <div class="gl-account-header">',
'',
