'                           THEN ''gl-cr''',
'',
'                           ELSE ''gl-dr''',
'',
'                       END',
'',
'               END',
'',
'            || q''[">',
'',
'                                ]''',
'',
'            || CASE',
'',
'                   WHEN v_account_closing >= 0',
'                   THEN',
'',
'                       CASE',
'',
'                           WHEN v_account_type IN (''A'',''E'')',
'                           THEN ''DR''',
'',
'                           ELSE ''CR''',
'',
'                       END',
'',
'                   ELSE',
'',
'                       CASE',
'',
'                           WHEN v_account_type IN (''A'',''E'')',
'                           THEN ''CR''',
'',
'                           ELSE ''DR''',
'',
'                       END',
'',
'               END',
'',
'            || q''[',
