wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(10862214866344537)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form VOUCHER MST'
,p_static_id=>'process-form-voucher-mst'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'    v_code VARCHAR2(30);',
'',
'BEGIN',
'',
'    IF :P303_VOUCHER_DATE IS NULL THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Please enter voucher date.''',
'        );',
'    END IF;',
'',
'    IF :P303_VOUCHER_TYPE IS NULL THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Please select voucher type.''',
'        );',
'    END IF;',
'',
'    --------------------------------------------------',
'    -- INSERT',
'    --------------------------------------------------',
'',
'    IF :P303_VOUCHER_NO IS NULL THEN',
'',
'        :P303_VOUCHER_NO :=',
'            SEQ_VOUCHER_NO.NEXTVAL;',
'',
'        v_code :=',
'            :P303_VOUCHER_TYPE',
'            || ''-''',
'            || LPAD(:P303_VOUCHER_NO,6,''0'');',
'',
'        INSERT INTO ACC_VOUCHER_MST',
'        (',
'            VOUCHER_NO,',
'            VOUCHER_CODE,',
'            VOUCHER_DATE,',
'            VOUCHER_TYPE,',
'            NARRATION,',
'            APPROVAL_STATUS,',
'            CREATED_BY,',
'            CREATED_DATE',
'        )',
'        VALUES',
'        (',
'            :P303_VOUCHER_NO,',
'            v_code,',
'            :P303_VOUCHER_DATE,',
'            :P303_VOUCHER_TYPE,',
'            :P303_NARRATION,',
'            ''P'',',
'            :APP_USER,',
'            SYSDATE',
'        ) RETURNING VOUCHER_NO INTO :P303_VOUCHER_NO ;',
'',
'    --------------------------------------------------',
'    -- UPDATE',
'    --------------------------------------------------',
'',
'    ELSE',
'',
'        UPDATE ACC_VOUCHER_MST',
'           SET VOUCHER_DATE = :P303_VOUCHER_DATE,',
'               VOUCHER_TYPE = :P303_VOUCHER_TYPE,',
'               NARRATION    = :P303_NARRATION,',
'               UPDATED_BY   = :APP_USER,',
'               UPDATED_DATE = SYSDATE',
'         WHERE VOUCHER_NO = :P303_VOUCHER_NO;',
'',
'    END IF;',
'',
'    apex_application.g_print_success_message :=',
'        ''Voucher saved successfully.'';',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(10853242725344485)
,p_internal_uid=>10862214866344537
,p_created_on=>wwv_flow_imp.dz('20260819181712Z')
,p_updated_on=>wwv_flow_imp.dz('20260819181712Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
end;
