,p_name=>'P304_INVOICE'
,p_item_sequence=>110
,p_item_plug_id=>wwv_flow_imp.id(14627660090653207233)
,p_prompt=>'Invoice'
,p_source_type=>'ALWAYS_NULL'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_named_lov=>'LOV_304_INVOICE_LIST'
,p_lov_display_null=>'YES'
,p_lov_cascade_parent_items=>'P304_PARTY_NO'
,p_ajax_items_to_submit=>'P304_PARTY_NO'
,p_ajax_optimize_refresh=>'Y'
,p_cSize=>30
,p_grid_label_column_span=>4
,p_field_template=>2320077351817916916
,p_item_template_options=>'#DEFAULT#:t-Form-fieldContainer--stretchInputs:t-Form-fieldContainer--large:t-Form-fieldContainer--radioButtonGroup:t-Form-fieldContainer--slimPadding'
,p_lov_display_extra=>'NO'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'additional_outputs', 'PAYMENT_AMOUNT:P304_PAYMENT_AMOUNT,INVOICE_AMOUNT:P304_TOTAL_AMOUNT,RECEIVED_AMOUNT:P304_PREVIOUS_PAYMNET,DUE_AMOUNT:P304_DUE_AMOUNT',
  'case_sensitive', 'N',
  'display_as', 'POPUP',
  'fetch_on_search', 'Y',
  'initial_fetch', 'FIRST_ROWSET',
