wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(14788224143006350212)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'APPROVE_TRANSACTION'
,p_static_id=>'approve-purchase'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 9/1/2026 12:31:01 PM (QP5 v5.388) */',
'DECLARE',
'    V_TRANSACTION_NO     NUMBER;',
'    V_TRANSACTION_TYPE   VARCHAR2 (1);',
'BEGIN',
'    -- Get AJAX parameters',
'    V_TRANSACTION_NO := TO_NUMBER (APEX_APPLICATION.G_X01);',
'    V_TRANSACTION_TYPE := UPPER (TRIM (APEX_APPLICATION.G_X02));',
'',
'    -- Validation',
'    IF V_TRANSACTION_NO IS NULL',
'    THEN',
'        RAISE_APPLICATION_ERROR (-20001, ''Transaction No is required.'');',
'    END IF;',
'',
'    IF V_TRANSACTION_TYPE NOT IN (''P'', ''R'')',
'    THEN',
'        RAISE_APPLICATION_ERROR (-20002, ''Invalid transaction type.'');',
'    END IF;',
'',
'    -- Post Transaction',
'    IF V_TRANSACTION_TYPE = ''P''',
'    THEN',
'        PKG_FINANCE.POST_PAYMENT (P_TRANSACTION_NO => V_TRANSACTION_NO);',
'    ELSE',
'        PKG_FINANCE.POST_RECEIVE (P_TRANSACTION_NO => V_TRANSACTION_NO);',
'    END IF;',
'',
'    -- Success Response',
'    APEX_JSON.OPEN_OBJECT;',
'',
'    APEX_JSON.WRITE (''status'', ''SUCCESS'');',
'    APEX_JSON.WRITE (''message'', ''Transaction approved successfully.'');',
'',
'    APEX_JSON.CLOSE_OBJECT;',
'EXCEPTION',
'    WHEN OTHERS',
'    THEN',
'        APEX_JSON.OPEN_OBJECT;',
'',
'        APEX_JSON.WRITE (''status'', ''ERROR'');',
'        APEX_JSON.WRITE (''message'', SQLERRM);',
'',
'        APEX_JSON.CLOSE_OBJECT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_internal_uid=>14788224143006350212
,p_updated_on=>wwv_flow_imp.dz('20260901123128Z')
,p_updated_by=>'ADMIN'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(14788224563551350213)
