'BEGIN',
'',
'    UPDATE TRN_PURCHASE_MST',
'       SET APPROVAL_STATUS = ''R'',',
'           APPROVED_BY     = :APP_USER,',
'           APPROVED_DATE   = SYSDATE',
'     WHERE PURCHASE_NO = APEX_APPLICATION.G_X01;',
'',
'    COMMIT;',
'',
'    HTP.P(''SUCCESS'');',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        HTP.P(SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>14788224563551350213
);
