wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(10866988310388840)
,p_plug_name=>'Summery Balance Sheet HTM'
,p_static_id=>'voucher-mst_1'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>40
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 8/25/2026 3:50:57 PM (QP5 v5.388) */',
'DECLARE',
'    v_html   CLOB;',
'BEGIN',
'    WITH',
'        OPENING_BALANCE',
'        AS',
'            (  SELECT ACCOUNT_NO,',
'                      NVL (SUM (OPENING_DEBIT), 0)      AS OPENING_DEBIT,',
'                      NVL (SUM (OPENING_CREDIT), 0)     AS OPENING_CREDIT',
'                 FROM ACC_OPENING_BALANCE',
'                WHERE APPROVAL_STATUS = ''A''',
'             GROUP BY ACCOUNT_NO),',
'        VOUCHER_BALANCE',
'        AS',
'            (  SELECT D.ACCOUNT_NO,',
'                      NVL (SUM (D.DEBIT_AMOUNT), 0)      AS VOUCHER_DEBIT,',
'                      NVL (SUM (D.CREDIT_AMOUNT), 0)     AS VOUCHER_CREDIT',
'                 FROM ACC_VOUCHER_DTL D',
'                      JOIN ACC_VOUCHER_MST M ON M.VOUCHER_NO = D.VOUCHER_NO',
'                WHERE     M.APPROVAL_STATUS = ''A''',
'                      AND M.VOUCHER_DATE <= TO_DATE(:P306_AS_OF_DATE, ''MM/DD/YYYY'')',
'             GROUP BY D.ACCOUNT_NO),',
'        ACCOUNT_BALANCE',
'        AS',
'            (SELECT H.ACCOUNT_NO,',
'                    H.ACCOUNT_TYPE,',
'                    NVL (O.OPENING_DEBIT, 0) + NVL (V.VOUCHER_DEBIT, 0)',
'                        AS TOTAL_DEBIT,',
'                    NVL (O.OPENING_CREDIT, 0) + NVL (V.VOUCHER_CREDIT, 0)',
'                        AS TOTAL_CREDIT',
'               FROM MST_ACCOUNT_HEAD  H',
'                    LEFT JOIN OPENING_BALANCE O',
'                        ON O.ACCOUNT_NO = H.ACCOUNT_NO',
'                    LEFT JOIN VOUCHER_BALANCE V',
'                        ON V.ACCOUNT_NO = H.ACCOUNT_NO',
'              WHERE H.IS_POSTING = ''Y'' AND H.ACTIVE_STATUS = ''Y''),',
'        ACCOUNT_TOTAL',
'        AS',
'            (  SELECT ACCOUNT_TYPE,',
'                      SUM (',
'                          CASE',
'                              WHEN ACCOUNT_TYPE = ''A''',
'                              THEN',
'                                  TOTAL_DEBIT - TOTAL_CREDIT',
'                              WHEN ACCOUNT_TYPE IN (''L'', ''C'')',
'                              THEN',
'                                  TOTAL_CREDIT - TOTAL_DEBIT',
'                              ELSE',
'                                  0',
'                          END)    AS AMOUNT',
'                 FROM ACCOUNT_BALANCE',
'             GROUP BY ACCOUNT_TYPE),',
'        TOTALS',
'        AS',
'            (SELECT NVL (',
'                        SUM (',
'                            CASE',
'                                WHEN ACCOUNT_TYPE = ''A'' THEN AMOUNT',
'                                ELSE 0',
'                            END),',
'                        0)    AS TOTAL_ASSETS,',
'                    NVL (',
'                        SUM (',
'                            CASE',
'                                WHEN ACCOUNT_TYPE = ''L'' THEN AMOUNT',
'                                ELSE 0',
'                            END),',
'                        0)    AS TOTAL_LIABILITIES,',
'                    NVL (',
'                        SUM (',
'                            CASE',
'                                WHEN ACCOUNT_TYPE = ''C'' THEN AMOUNT',
'                                ELSE 0',
'                            END),',
'                        0)    AS TOTAL_CAPITAL',
'               FROM ACCOUNT_TOTAL),',
'        PROFIT_LOSS',
'        AS',
'            (SELECT NVL (',
'                        SUM (',
'                            CASE',
'                                WHEN ACCOUNT_TYPE = ''I''',
'                                THEN',
'                                    TOTAL_CREDIT - TOTAL_DEBIT',
'                                WHEN ACCOUNT_TYPE = ''E''',
'                                THEN',
'                                    TOTAL_DEBIT - TOTAL_CREDIT',
'                                ELSE',
'                                    0',
'                            END),',
'                        0)    AS NET_PROFIT',
'               FROM ACCOUNT_BALANCE',
'              WHERE ACCOUNT_TYPE IN (''I'', ''E''))',
'    SELECT    ''<div id="balance_sheet_summary" style="',
'            width:100%;',
'            max-width:320px;',
'            box-sizing:border-box;',
'            padding:10px;',
'            border:1px solid #e1e5e9;',
'            border-radius:8px;',
'            background:#fff;',
'            font-size:12px;',
'            line-height:1.6;',
'        ">',
'',
'        <!-- ================= HEADER ================= -->',
'',
'        <div style="',
'            text-align:center;',
'            font-size:14px;',
'            font-weight:700;',
'            color:#2c3e50;',
'            margin-bottom:2px;',
'        ">',
'            Balance Sheet Summary',
'        </div>',
'',
'        <div style="',
'            text-align:center;',
'            font-size:10px;',
'            color:#7f8c8d;',
'            margin-bottom:8px;',
'        ">',
'            As of ''',
'           || NVL (TO_CHAR ( TO_DATE(:P306_AS_OF_DATE, ''MM/DD/YYYY''), ''DD Mon YYYY''),',
'                   ''Current Date'')',
'           || ''',
'        </div>',
'',
'',
'        <!-- ================= ASSETS ================= -->',
'',
'        <div style="',
'            margin-top:4px;',
'            margin-bottom:4px;',
'            padding:4px 7px;',
'            border-left:4px solid #2980b9;',
'            background:#f4f8fb;',
'            color:#2471a3;',
'            font-size:11px;',
'            font-weight:700;',
'            text-transform:uppercase;',
'            letter-spacing:.4px;',
'        ">',
'            Assets',
'        </div>',
'',
'        <div style="',
'            display:flex;',
'            justify-content:space-between;',
'            align-items:center;',
'            padding:2px 2px;',
'        ">',
'            <span>Total Assets</span>',
'',
'            <b style="',
'                color:#2980b9;',
'                font-size:13px;',
'            ">',
unistr('                \09F3 '''),
'           || TO_CHAR (NVL (T.TOTAL_ASSETS, 0), ''FM999G999G999G990D00'')',
'           || ''',
'            </b>',
'        </div>',
'',
'',
'        <!-- ================= LIABILITIES ================= -->',
'',
'        <div style="',
'            margin-top:8px;',
'            margin-bottom:4px;',
'            padding:4px 7px;',
'            border-left:4px solid #e67e22;',
'            background:#fdf6ee;',
'            color:#d35400;',
'            font-size:11px;',
'            font-weight:700;',
'            text-transform:uppercase;',
'            letter-spacing:.4px;',
'        ">',
'            Liabilities & Equity',
'        </div>',
'',
'',
'        <!-- Liability -->',
'',
'        <div style="',
'            display:flex;',
'            justify-content:space-between;',
'            align-items:center;',
'            padding:2px;',
'        ">',
'            <span>Total Liabilities</span>',
'',
'            <b>',
unistr('                \09F3 '''),
'           || TO_CHAR (NVL (T.TOTAL_LIABILITIES, 0), ''FM999G999G999G990D00'')',
'           || ''',
'            </b>',
'        </div>',
'',
'',
'        <!-- Capital -->',
'',
'        <div style="',
'            display:flex;',
'            justify-content:space-between;',
'            align-items:center;',
'            padding:2px;',
'        ">',
'            <span>Capital</span>',
'',
'            <b>',
unistr('                \09F3 '''),
'           || TO_CHAR (NVL (T.TOTAL_CAPITAL, 0), ''FM999G999G999G990D00'')',
'           || ''',
'            </b>',
'        </div>',
'',
'',
'        <!-- Profit / Loss -->',
'',
'        <div style="',
'            display:flex;',
'            justify-content:space-between;',
'            align-items:center;',
'            padding:2px;',
'        ">',
'            <span>''',
'           || CASE',
'                  WHEN P.NET_PROFIT >= 0 THEN ''Current Period Profit''',
'                  ELSE ''Current Period Loss''',
'              END',
'           || ''</span>',
'',
'            <b style="',
'                color:''',
'           || CASE WHEN P.NET_PROFIT >= 0 THEN ''#27ae60'' ELSE ''#c0392b'' END',
'           || '';',
'            ">',
unistr('                \09F3 '''),
'           || TO_CHAR (ABS (NVL (P.NET_PROFIT, 0)), ''FM999G999G999G990D00'')',
'           || ''',
'            </b>',
'        </div>',
'',
'',
'        <!-- ================= TOTAL ================= -->',
'',
'        <div style="',
'            display:flex;',
'            justify-content:space-between;',
'            align-items:center;',
'            border-top:1px solid #ddd;',
'            margin-top:6px;',
'            padding-top:5px;',
'            font-weight:700;',
'        ">',
'            <span>Liabilities + Equity</span>',
'',
'            <b>',
unistr('                \09F3 '''),
'           || TO_CHAR (',
'                  NVL (T.TOTAL_LIABILITIES + T.TOTAL_CAPITAL + P.NET_PROFIT,',
'                       0),',
'                  ''FM999G999G999G990D00'')',
'           || ''',
'            </b>',
'        </div>',
'',
'',
'        <!-- ================= BALANCE STATUS ================= -->',
'',
'        <div style="',
'            margin-top:8px;',
'            padding:5px 7px;',
'            border-radius:4px;',
'            text-align:center;',
'            font-size:11px;',
'            font-weight:700;',
'            background:''',
'           || CASE',
'                  WHEN ROUND (T.TOTAL_ASSETS, 2) =',
'                       ROUND (',
'                             T.TOTAL_LIABILITIES',
'                           + T.TOTAL_CAPITAL',
'                           + P.NET_PROFIT,',
'                           2)',
'                  THEN',
'                      ''#eaf7ef''',
'                  ELSE',
'                      ''#fdeeee''',
'              END',
'           || '';',
'            color:''',
'           || CASE',
'                  WHEN ROUND (T.TOTAL_ASSETS, 2) =',
'                       ROUND (',
'                             T.TOTAL_LIABILITIES',
'                           + T.TOTAL_CAPITAL',
'                           + P.NET_PROFIT,',
'                           2)',
'                  THEN',
'                      ''#27ae60''',
'                  ELSE',
'                      ''#c0392b''',
'              END',
'           || '';',
'        ">',
'            ''',
'           || CASE',
'                  WHEN ROUND (T.TOTAL_ASSETS, 2) =',
'                       ROUND (',
'                             T.TOTAL_LIABILITIES',
'                           + T.TOTAL_CAPITAL',
'                           + P.NET_PROFIT,',
'                           2)',
'                  THEN',
unistr('                      ''\2713 BALANCED'''),
'                  ELSE',
unistr('                      ''\26A0 NOT BALANCED'''),
'              END',
'           || ''',
'        </div>',
'',
'        </div>''',
'      INTO v_html',
'      FROM TOTALS T CROSS JOIN PROFIT_LOSS P;',
'',
'',
'    RETURN v_html;',
'EXCEPTION',
'    WHEN OTHERS',
'    THEN    ',
'        RETURN ''',
'        <div style="',
'            padding:10px;',
'            font-size:12px;',
'            color:#c0392b;',
'            border:1px solid #f5c6cb;',
'            border-radius:5px;',
'            background:#fff5f5;',
'        ">',
'            Balance sheet summary unavailable. ',
'        </div>'' || SQLERRM;',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P306_AS_OF_DATE'
,p_required_patch=>wwv_flow_imp.id(8032859059284477852)
,p_created_on=>wwv_flow_imp.dz('20260820115742Z')
,p_updated_on=>wwv_flow_imp.dz('20260901140245Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(11276292108542547)
,p_plug_name=>'Balance Sheet'
,p_static_id=>'voucher-mst_2'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 9/2/2026 11:31:18 AM (QP5 v5.388) */',
'DECLARE',
'    v_html                CLOB;',
'    v_last_group          VARCHAR2 (30) := NULL;',
'',
'    v_total_assets        NUMBER := 0;',
'    v_cash_in_hand        NUMBER := 0;',
'    v_total_liabilities   NUMBER := 0;',
'    v_total_equity        NUMBER := 0;',
'    v_net_profit          NUMBER := 0;',
'',
'    v_total_le            NUMBER := 0;',
'    v_difference          NUMBER := 0;',
'',
'    v_as_of_date          DATE;',
'BEGIN',
'    /* ============================================================',
'    AS OF DATE',
'    ============================================================ */',
'',
'    v_as_of_date := TO_DATE ( :P306_AS_OF_DATE, ''MM/DD/YYYY'');',
'',
'',
'    /* ============================================================',
'    BALANCE SHEET SUMMARY',
'',
'    Assets / Liabilities / Equity',
'    = Opening Balance + Approved Vouchers',
'    ============================================================ */',
'',
'    WITH',
'        ACCOUNT_BALANCE',
'        AS',
'            (SELECT H.ACCOUNT_NO,',
'                    H.ACCOUNT_CODE,',
'                    H.ACCOUNT_NAME,',
'                    H.ACCOUNT_TYPE,',
'                      /* ====================================================',
'                      TOTAL DEBIT',
'                      ==================================================== */',
'',
'                      NVL (',
'                          (SELECT SUM (O.OPENING_DEBIT)',
'                            FROM ACC_OPENING_BALANCE O',
'                           WHERE     O.ACCOUNT_NO = H.ACCOUNT_NO',
'                                 AND O.APPROVAL_STATUS = ''A''),',
'                          0)',
'                    + NVL (',
'                          (SELECT SUM (D.DEBIT_AMOUNT)',
'                            FROM ACC_VOUCHER_DTL  D',
'                                 JOIN ACC_VOUCHER_MST M',
'                                     ON M.VOUCHER_NO = D.VOUCHER_NO',
'                           WHERE     D.ACCOUNT_NO = H.ACCOUNT_NO',
'                                 AND M.APPROVAL_STATUS = ''A''',
'                                 AND M.VOUCHER_DATE < v_as_of_date + 1),',
'                          0)    AS TOTAL_DEBIT,        /*====================================================TOTAL',
'CREDIT====================================================*/',
'                      NVL (',
'                          (SELECT SUM (O.OPENING_CREDIT)',
'                            FROM ACC_OPENING_BALANCE O',
'                           WHERE     O.ACCOUNT_NO = H.ACCOUNT_NO',
'                                 AND O.APPROVAL_STATUS = ''A''),',
'                          0)',
'                    + NVL (',
'                          (SELECT SUM (D.CREDIT_AMOUNT)',
'                            FROM ACC_VOUCHER_DTL  D',
'                                 JOIN ACC_VOUCHER_MST M',
'                                     ON M.VOUCHER_NO = D.VOUCHER_NO',
'                           WHERE     D.ACCOUNT_NO = H.ACCOUNT_NO',
'                                 AND M.APPROVAL_STATUS = ''A''',
'                                 AND M.VOUCHER_DATE < v_as_of_date + 1),',
'                          0)    AS TOTAL_CREDIT',
'               FROM MST_ACCOUNT_HEAD H',
'              WHERE H.IS_POSTING = ''Y'' AND H.ACTIVE_STATUS = ''Y'')',
'    /*============================================================SUMMARY',
'    CALCULATION============================================================*/',
'    SELECT /*========================================================TOTAL',
'           ASSETS========================================================*/',
'           NVL (',
'               SUM (',
'                   CASE',
'                       WHEN ACCOUNT_TYPE = ''A''',
'                       THEN',
'                           TOTAL_DEBIT - TOTAL_CREDIT',
'                       ELSE',
'                           0',
'                   END),',
'               0),                          /*========================================================CASH IN',
'HAND========================================================*/',
'           NVL (',
'               SUM (',
'                   CASE',
'                       WHEN     ACCOUNT_TYPE = ''A''',
'                            AND UPPER (TRIM (ACCOUNT_NAME)) = ''CASH IN HAND''',
'                       THEN',
'                           TOTAL_DEBIT - TOTAL_CREDIT',
'                       ELSE',
'                           0',
'                   END),',
'               0),',
'           /*========================================================TOTAL',
'           LIABILITIES========================================================*/',
'           NVL (',
'               SUM (',
'                   CASE',
'                       WHEN ACCOUNT_TYPE = ''L''',
'                       THEN',
'                           TOTAL_CREDIT - TOTAL_DEBIT',
'                       ELSE',
'                           0',
'                   END),',
'               0),                          /*========================================================TOTAL',
'EQUITY========================================================*/',
'           NVL (',
'               SUM (',
'                   CASE',
'                       WHEN ACCOUNT_TYPE = ''C''',
'                       THEN',
'                           TOTAL_CREDIT - TOTAL_DEBIT',
'                       ELSE',
'                           0',
'                   END),',
'               0)',
'      INTO v_total_assets,',
'           v_cash_in_hand,',
'           v_total_liabilities,',
'           v_total_equity',
'      FROM ACCOUNT_BALANCE; /*============================================================CURRENT PERIOD PROFIT IMPORTANT:',
'      Opening balance is NOT included. Income=Credit - Debit Expense=Credit - Debit Therefore: Revenue +620 COGS -550',
'      Profit +70============================================================*/',
'',
'    SELECT NVL (',
'               SUM (',
'                   CASE                                                                          /*',
'------------------------------------------------ INCOME Credit=Positive Debit=Negative',
'------------------------------------------------ */',
'                       WHEN H.ACCOUNT_TYPE = ''I''',
'                       THEN',
'                           NVL (D.CREDIT_AMOUNT, 0) - NVL (D.DEBIT_AMOUNT, 0) /* ------------------------------------------------ EXPENSE Debit Expense must reduce Profit',
'                                                          Credit - Debit Example: Debit 550 Credit 0=-550 ------------------------------------------------ */',
'                       WHEN H.ACCOUNT_TYPE = ''E''',
'                       THEN',
'                           NVL (D.CREDIT_AMOUNT, 0) - NVL (D.DEBIT_AMOUNT, 0)',
'                       ELSE',
'                           0',
'                   END),',
'               0)',
'      INTO v_net_profit',
'      FROM ACC_VOUCHER_DTL  D',
'           JOIN ACC_VOUCHER_MST M ON M.VOUCHER_NO = D.VOUCHER_NO',
'           JOIN MST_ACCOUNT_HEAD H ON H.ACCOUNT_NO = D.ACCOUNT_NO',
'     WHERE     M.APPROVAL_STATUS = ''A''',
'           AND M.VOUCHER_DATE < v_as_of_date + 1',
'           AND H.ACCOUNT_TYPE IN (''I'', ''E''); /*============================================================TOTAL LIABILITIES + EQUITY +',
'                                PROFIT============================================================*/',
'',
'    v_total_le := v_total_liabilities + v_total_equity + v_net_profit; /*============================================================BALANCE',
'                                        DIFFERENCE============================================================*/',
'    v_difference := v_total_assets - v_total_le;',
'    /*============================================================HTML',
'    HEADER============================================================*/',
'    v_html :=',
'           ''<div style="',
'                width:100%;',
'                box-sizing:border-box;',
'                font-family:Arial,sans-serif;',
'                background:#fff;',
'                border:1px solid #e1e5e9;',
'                border-radius:8px;',
'                overflow:hidden;',
'            ">',
'',
'            <div style="',
'                padding:14px 16px;',
'                border-bottom:1px solid #e5e9ed;',
'                background:#fafbfc;',
'            ">',
'',
'                <div style="',
'                    font-size:20px;',
'                    font-weight:700;',
'                    color:#26343f;',
'                ">',
'                    Balance Sheet',
'                </div>',
'',
'                <div style="',
'                    margin-top:4px;',
'                    font-size:11px;',
'                    color:#7a8793;',
'                ">',
'                    Financial Position as of ''',
'        || TO_CHAR (v_as_of_date, ''DD Mon YYYY'')',
'        || ''',
'                </div>',
'',
'            </div>',
'',
'',
'            <!-- =====================================================',
'                 KPI CARDS',
'                 ===================================================== -->',
'',
'            <div style="',
'                display:flex;',
'                gap:10px;',
'                padding:12px;',
'                flex-wrap:wrap;',
'            ">',
'',
'',
'                <!-- TOTAL ASSETS -->',
'',
'                <div style="',
'                    flex:1;',
'                    min-width:180px;',
'                    padding:10px 12px;',
'                    border:1px solid #dce4ea;',
'                    border-radius:6px;',
'                    background:#f7fafc;',
'                ">',
'',
'                    <div style="',
'                        font-size:11px;',
'                        color:#71808d;',
'                    ">',
'                        Total Assets',
'                    </div>',
'',
'                    <div style="',
'                        margin-top:4px;',
'                        font-size:17px;',
'                        font-weight:700;',
'                        color:#286090;',
'                    ">',
unistr('                        \09F3 '''),
'        || TO_CHAR (v_total_assets, ''FM999G999G999G990D00'')',
'        || ''',
'                    </div>',
'',
'                </div>',
'',
'',
'                <!-- CASH -->',
'',
'                <div style="',
'                    flex:1;',
'                    min-width:180px;',
'                    padding:10px 12px;',
'                    border:1px solid #dce4ea;',
'                    border-radius:6px;',
'                    background:#fffdf5;',
'                ">',
'',
'                    <div style="',
'                        font-size:11px;',
'                        color:#71808d;',
'                    ">',
'                        Cash in Hand',
'                    </div>',
'',
'                    <div style="',
'                        margin-top:4px;',
'                        font-size:17px;',
'                        font-weight:700;',
'                        color:#b7791f;',
'                    ">',
unistr('                        \09F3 '''),
'        || TO_CHAR (v_cash_in_hand, ''FM999G999G999G990D00'')',
'        || ''',
'                    </div>',
'',
'                </div>',
'',
'',
'                <!-- LIABILITIES -->',
'',
'                <div style="',
'                    flex:1;',
'                    min-width:180px;',
'                    padding:10px 12px;',
'                    border:1px solid #dce4ea;',
'                    border-radius:6px;',
'                    background:#fff8f8;',
'                ">',
'',
'                    <div style="',
'                        font-size:11px;',
'                        color:#71808d;',
'                    ">',
'                        Total Liabilities',
'                    </div>',
'',
'                    <div style="',
'                        margin-top:4px;',
'                        font-size:17px;',
'                        font-weight:700;',
'                        color:#c0392b;',
'                    ">',
unistr('                        \09F3 '''),
'        || TO_CHAR (v_total_liabilities, ''FM999G999G999G990D00'')',
'        || ''',
'                    </div>',
'',
'                </div>',
'',
'',
'                <!-- EQUITY -->',
'',
'                <div style="',
'                    flex:1;',
'                    min-width:180px;',
'                    padding:10px 12px;',
'                    border:1px solid #dce4ea;',
'                    border-radius:6px;',
'                    background:#f7fcf9;',
'                ">',
'',
'                    <div style="',
'                        font-size:11px;',
'                        color:#71808d;',
'                    ">',
'                        Equity',
'                    </div>',
'',
'                    <div style="',
'                        margin-top:4px;',
'                        font-size:17px;',
'                        font-weight:700;',
'                        color:#218c4b;',
'                    ">',
unistr('                        \09F3 '''),
'        || TO_CHAR (v_total_equity, ''FM999G999G999G990D00'')',
'        || ''',
'                    </div>',
'',
'                </div>',
'',
'            </div>',
'',
'',
'            <!-- =====================================================',
'                 ACCOUNT TABLE',
'                 ===================================================== -->',
'',
'            <div style="',
'                margin:0 12px 12px 12px;',
'                border:1px solid #e1e5e9;',
'                border-radius:6px;',
'                overflow:hidden;',
'            ">',
'',
'',
'                <!-- TABLE HEADER -->',
'',
'                <div style="',
'                    display:grid;',
'                    grid-template-columns:120px 1fr 170px;',
'                    padding:9px 10px;',
'                    background:#f1f4f7;',
'                    font-size:11px;',
'                    font-weight:700;',
'                    color:#526170;',
'                ">',
'',
'                    <div>Code</div>',
'',
'                    <div>Account Name</div>',
'',
'                    <div style="text-align:right;">',
'                        Amount',
'                    </div>',
'',
'                </div>''; /*============================================================ACCOUNT',
'  DETAILS============================================================*/',
'',
'    FOR R',
'        IN (WITH',
'                ACCOUNT_BALANCE',
'                AS',
'                    (SELECT H.ACCOUNT_NO,',
'                            H.ACCOUNT_CODE,',
'                            H.ACCOUNT_NAME,',
'                            H.ACCOUNT_TYPE,                  /* TOTAL DEBIT */',
'                              NVL (',
'                                  (SELECT SUM (O.OPENING_DEBIT)',
'                                    FROM ACC_OPENING_BALANCE O',
'                                   WHERE     O.ACCOUNT_NO = H.ACCOUNT_NO',
'                                         AND O.APPROVAL_STATUS = ''A''),',
'                                  0)',
'                            + NVL (',
'                                  (SELECT SUM (D.DEBIT_AMOUNT)',
'                                    FROM ACC_VOUCHER_DTL  D',
'                                         JOIN ACC_VOUCHER_MST M',
'                                             ON M.VOUCHER_NO = D.VOUCHER_NO',
'                                   WHERE     D.ACCOUNT_NO = H.ACCOUNT_NO',
'                                         AND M.APPROVAL_STATUS = ''A''',
'                                         AND M.VOUCHER_DATE <',
'                                             v_as_of_date + 1),',
'                                  0)    AS TOTAL_DEBIT,                                                        /*',
'TOTAL CREDIT */',
'                              NVL (',
'                                  (SELECT SUM (O.OPENING_CREDIT)',
'                                    FROM ACC_OPENING_BALANCE O',
'                                   WHERE     O.ACCOUNT_NO = H.ACCOUNT_NO',
'                                         AND O.APPROVAL_STATUS = ''A''),',
'                                  0)',
'                            + NVL (',
'                                  (SELECT SUM (D.CREDIT_AMOUNT)',
'                                    FROM ACC_VOUCHER_DTL  D',
'                                         JOIN ACC_VOUCHER_MST M',
'                                             ON M.VOUCHER_NO = D.VOUCHER_NO',
'                                   WHERE     D.ACCOUNT_NO = H.ACCOUNT_NO',
'                                         AND M.APPROVAL_STATUS = ''A''',
'                                         AND M.VOUCHER_DATE <',
'                                             v_as_of_date + 1),',
'                                  0)    AS TOTAL_CREDIT',
'                       FROM MST_ACCOUNT_HEAD H',
'                      WHERE H.IS_POSTING = ''Y'' AND H.ACTIVE_STATUS = ''Y''),',
'                BALANCE_SHEET',
'                AS',
'                    (SELECT ACCOUNT_CODE,',
'                            ACCOUNT_NAME,',
'                            ACCOUNT_TYPE,',
'                            CASE',
'                                WHEN ACCOUNT_TYPE = ''A''',
'                                THEN',
'                                    TOTAL_DEBIT - TOTAL_CREDIT',
'                                WHEN ACCOUNT_TYPE IN (''L'', ''C'')',
'                                THEN',
'                                    TOTAL_CREDIT - TOTAL_DEBIT',
'                            END    AS AMOUNT',
'                       FROM ACCOUNT_BALANCE',
'                      WHERE ACCOUNT_TYPE IN (''A'', ''L'', ''C''))',
'              SELECT CASE',
'                         WHEN ACCOUNT_TYPE = ''A'' THEN ''Assets''',
'                         WHEN ACCOUNT_TYPE = ''L'' THEN ''Liabilities''',
'                         WHEN ACCOUNT_TYPE = ''C'' THEN ''Equity''',
'                     END    AS ACCOUNT_GROUP,',
'                     ACCOUNT_CODE,',
'                     ACCOUNT_NAME,',
'                     AMOUNT',
'                FROM BALANCE_SHEET',
'               WHERE NVL (AMOUNT, 0) <> 0',
'            ORDER BY CASE ACCOUNT_TYPE',
'                         WHEN ''A'' THEN 1',
'                         WHEN ''L'' THEN 2',
'                         WHEN ''C'' THEN 3',
'                     END,',
'                     ACCOUNT_CODE)',
'    LOOP',
'        /* ========================================================',
'        GROUP HEADER',
'        ======================================================== */',
'',
'        IF v_last_group IS NULL OR v_last_group <> R.ACCOUNT_GROUP',
'        THEN',
'            v_last_group := R.ACCOUNT_GROUP;',
'',
'            v_html :=',
'                v_html || ''<div style="',
'                    padding:7px 10px;',
'                    background:#f5f7f9;',
'                    border-top:1px solid #e5e9ed;',
'                    border-bottom:1px solid #e5e9ed;',
'                    font-size:11px;',
'                    font-weight:700;',
'                    color:#4f5d68;',
'                ">'' || APEX_ESCAPE.HTML (R.ACCOUNT_GROUP) || ''</div>'';',
'        END IF;',
'',
'',
'        /* ========================================================',
'        ACCOUNT ROW',
'        ======================================================== */',
'',
'        v_html :=',
'               v_html',
'            || ''<div style="',
'                display:grid;',
'                grid-template-columns:120px 1fr 170px;',
'                padding:8px 10px;',
'                border-bottom:1px solid #f0f2f4;',
'                font-size:11px;',
'            ">',
'',
'            <div style="',
'                    color:#7a8793;',
'                ">''',
'            || APEX_ESCAPE.HTML (NVL (R.ACCOUNT_CODE, ''-''))',
'            || ''</div>',
'',
'            <div style="',
'                    color:#34424d;',
'                ">''',
'            || APEX_ESCAPE.HTML (R.ACCOUNT_NAME)',
'            || ''</div>',
'',
'            <div style="',
'                    text-align:right;',
'                    font-weight:600;',
'                ">',
unistr('                \09F3 '''),
'            || TO_CHAR (R.AMOUNT, ''FM999G999G999G990D00'')',
'            || ''</div>',
'',
'        </div>'';',
'    END LOOP;',
'',
'',
'    /* ============================================================',
'    CURRENT PERIOD PROFIT / LOSS DISPLAY',
'    ============================================================ */',
'',
'    IF v_net_profit >= 0',
'    THEN',
'        v_html :=',
'               v_html',
'            || ''<div style="',
'                display:flex;',
'                justify-content:space-between;',
'                padding:10px;',
'                background:#f7fcf9;',
'                border-top:1px solid #dceee3;',
'            ">',
'',
'            <div>',
'                <b style="',
'                        color:#218c4b;',
'                    ">',
'                    Current Period Profit',
'                </b>',
'            </div>',
'',
'            <div style="',
'                    font-weight:700;',
'                    color:#218c4b;',
'                ">',
unistr('                \09F3 '''),
'            || TO_CHAR (v_net_profit, ''FM999G999G999G990D00'')',
'            || ''',
'            </div>',
'',
'        </div>'';',
'    ELSE',
'        v_html :=',
'               v_html',
'            || ''<div style="',
'                display:flex;',
'                justify-content:space-between;',
'                padding:10px;',
'                background:#fff7f7;',
'                border-top:1px solid #f0dddd;',
'            ">',
'',
'            <div>',
'                <b style="',
'                        color:#c0392b;',
'                    ">',
'                    Current Period Loss',
'                </b>',
'            </div>',
'',
'            <div style="',
'                    font-weight:700;',
'                    color:#c0392b;',
'                ">',
unistr('                \09F3 '''),
'            || TO_CHAR (ABS (v_net_profit), ''FM999G999G999G990D00'')',
'            || ''',
'            </div>',
'',
'        </div>'';',
'    END IF;',
'',
'',
'    /* ============================================================',
'    SUMMARY',
'    ============================================================ */',
'',
'    v_html :=',
'           v_html',
'        || ''<div style="',
'            padding:12px;',
'            background:#fafbfc;',
'            border-top:1px solid #dfe5ea;',
'        ">',
'',
'',
'            <!-- TOTAL ASSETS -->',
'',
'            <div style="',
'                display:flex;',
'                justify-content:space-between;',
'                padding:5px 0;',
'                font-size:12px;',
'            ">',
'',
'                <span>',
'                    <b>Total Assets</b>',
'                </span>',
'',
'                <b>',
unistr('                    \09F3 '''),
'        || TO_CHAR (v_total_assets, ''FM999G999G999G990D00'')',
'        || ''',
'                </b>',
'',
'            </div>',
'',
'',
'            <!-- CASH -->',
'',
'            <div style="',
'                display:flex;',
'                justify-content:space-between;',
'                padding:5px 0;',
'                font-size:12px;',
'            ">',
'',
'                <span>',
'                    <b>Cash in Hand</b>',
'                </span>',
'',
'                <b style="color:#b7791f;">',
unistr('                    \09F3 '''),
'        || TO_CHAR (v_cash_in_hand, ''FM999G999G999G990D00'')',
'        || ''',
'                </b>',
'',
'            </div>',
'',
'',
'            <!-- LIABILITIES -->',
'',
'            <div style="',
'                display:flex;',
'                justify-content:space-between;',
'                padding:5px 0;',
'                font-size:12px;',
'            ">',
'',
'                <span>',
'                    <b>Total Liabilities</b>',
'                </span>',
'',
'                <b>',
unistr('                    \09F3 '''),
'        || TO_CHAR (v_total_liabilities, ''FM999G999G999G990D00'')',
'        || ''',
'                </b>',
'',
'            </div>',
'',
'',
'            <!-- EQUITY -->',
'',
'            <div style="',
'                display:flex;',
'                justify-content:space-between;',
'                padding:5px 0;',
'                font-size:12px;',
'            ">',
'',
'                <span>',
'                    <b>Equity</b>',
'                </span>',
'',
'                <b>',
unistr('                    \09F3 '''),
'        || TO_CHAR (v_total_equity, ''FM999G999G999G990D00'')',
'        || ''',
'                </b>',
'',
'            </div>',
'',
'',
'            <!-- CURRENT PROFIT -->',
'',
'            <div style="',
'                display:flex;',
'                justify-content:space-between;',
'                padding:5px 0;',
'                font-size:12px;',
'            ">',
'',
'                <span>',
'                    <b>Current Period Profit</b>',
'                </span>',
'',
'                <b style="color:#218c4b;">',
unistr('                    \09F3 '''),
'        || TO_CHAR (v_net_profit, ''FM999G999G999G990D00'')',
'        || ''',
'                </b>',
'',
'            </div>',
'',
'',
'            <!-- TOTAL -->',
'',
'            <div style="',
'                display:flex;',
'                justify-content:space-between;',
'                padding:8px 0;',
'                margin-top:4px;',
'                border-top:1px solid #dfe5ea;',
'                font-size:13px;',
'            ">',
'',
'                <span>',
'                    <b>',
'                        Total Liabilities + Equity + Profit',
'                    </b>',
'                </span>',
'',
'                <b>',
unistr('                    \09F3 '''),
'        || TO_CHAR (v_total_le, ''FM999G999G999G990D00'')',
'        || ''',
'                </b>',
'',
'            </div>'';',
'',
'',
'    /* ============================================================',
'    BALANCE STATUS',
'    ============================================================ */',
'',
'    IF ABS (v_difference) < 0.01',
'    THEN',
'        v_html := v_html || ''<div style="',
'                margin-top:8px;',
'                padding:8px 10px;',
'                border-radius:5px;',
'                background:#eaf8ef;',
'                color:#218c4b;',
'                font-size:11px;',
'                font-weight:700;',
'                text-align:center;',
'            ">',
unistr('                \2713 BALANCED'),
'            </div>'';',
'    ELSE',
'        v_html :=',
'               v_html',
'            || ''<div style="',
'                margin-top:8px;',
'                padding:8px 10px;',
'                border-radius:5px;',
'                background:#fff1f1;',
'                color:#c0392b;',
'                font-size:11px;',
'                font-weight:700;',
'                text-align:center;',
'            ">',
unistr('                \2715 NOT BALANCED'),
'                &nbsp;&nbsp;',
unistr('                Difference: \09F3 '''),
'            || TO_CHAR (ABS (v_difference), ''FM999G999G999G990D00'')',
'            || ''',
'            </div>'';',
'    END IF;   /*============================================================HTML',
'END============================================================*/',
'',
'    v_html := v_html || ''</div></div>'';',
'    RETURN v_html;',
'EXCEPTION',
'    WHEN OTHERS',
'    THEN',
'        RETURN ''<div style="',
'                    padding:12px;',
'                    border:1px solid #f1cccc;',
'                    border-radius:6px;',
'                    background:#fff5f5;',
'                    color:#c0392b;',
'                    font-size:12px;',
'                ">',
'                    <b>Balance Sheet Error</b>',
'                    <br><br>'' || APEX_ESCAPE.HTML (SQLERRM) || ''</div>'';',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P306_AS_OF_DATE'
,p_created_on=>wwv_flow_imp.dz('20260825162205Z')
,p_updated_on=>wwv_flow_imp.dz('20260902113131Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
