,p_cSize=>30
,p_field_template=>3033038003750078790
,p_item_template_options=>'#DEFAULT#:t-Form-fieldContainer--stretchInputs:t-Form-fieldContainer--large:t-Form-fieldContainer--slimPadding'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
