wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(11518266794620404)
,p_plug_name=>'Profit & Loss'
,p_static_id=>'voucher-mst_1'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>70
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH PL AS',
'(',
'    SELECT',
'           H.ACCOUNT_NO,',
'           H.ACCOUNT_CODE,',
'           H.ACCOUNT_NAME,',
'           H.ACCOUNT_TYPE,',
'',
'           NVL(SUM(D.DEBIT_AMOUNT),0)  DEBIT_AMOUNT,',
'           NVL(SUM(D.CREDIT_AMOUNT),0) CREDIT_AMOUNT',
'',
'    FROM MST_ACCOUNT_HEAD H',
'',
'    JOIN ACC_VOUCHER_DTL D',
'      ON D.ACCOUNT_NO = H.ACCOUNT_NO',
'',
'    JOIN ACC_VOUCHER_MST M',
'      ON M.VOUCHER_NO = D.VOUCHER_NO',
'',
'    WHERE H.IS_POSTING = ''Y''',
'      AND H.ACTIVE_STATUS = ''Y''',
'      AND H.ACCOUNT_TYPE IN (''I'',''E'')',
'      AND M.APPROVAL_STATUS = ''A''',
'',
'    --  AND M.VOUCHER_DATE BETWEEN :P310_FROM_DATE',
'    --                         AND :P310_TO_DATE',
'',
'    GROUP BY',
'           H.ACCOUNT_NO,',
'           H.ACCOUNT_CODE,',
'           H.ACCOUNT_NAME,',
'           H.ACCOUNT_TYPE',
')',
'SELECT',
'       ACCOUNT_CODE,',
'       ACCOUNT_NAME,',
'',
'       CASE',
'           WHEN ACCOUNT_TYPE = ''I''',
'           THEN CREDIT_AMOUNT - DEBIT_AMOUNT',
'',
'           WHEN ACCOUNT_TYPE = ''E''',
'           THEN DEBIT_AMOUNT - CREDIT_AMOUNT',
'       END AMOUNT,',
'',
'       CASE',
'           WHEN ACCOUNT_TYPE = ''I''',
'           THEN ''Income''',
'',
'           WHEN ACCOUNT_TYPE = ''E''',
'           THEN ''Expense''',
'       END ACCOUNT_GROUP',
'',
'FROM PL',
'',
'ORDER BY',
'       ACCOUNT_TYPE DESC,',
'       ACCOUNT_CODE;'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P310_FROM_DATE,P310_TO_DATE'
,p_prn_content_disposition=>'ATTACHMENT'
