 p_id=>wwv_flow_imp.id(11271812897542503)
,p_name=>'P311_FIN_YEAR'
,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>10
,p_item_plug_id=>wwv_flow_imp.id(29962660960359069905)
,p_item_source_plug_id=>wwv_flow_imp.id(29962660960359069905)
,p_prompt=>'Financial Year'
,p_source=>'FIN_YEAR'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'       (start_year - (LEVEL - 1))',
'       || ''-''',
'       || (start_year + 1 - (LEVEL - 1)) AS display_value,',
'',
'       (start_year - (LEVEL - 1))',
'       || ''-''',
'       || (start_year + 1 - (LEVEL - 1)) AS return_value',
'FROM',
'(',
'    SELECT CASE',
'             WHEN EXTRACT(MONTH FROM SYSDATE) >= 7',
'             THEN EXTRACT(YEAR FROM SYSDATE)',
'             ELSE EXTRACT(YEAR FROM SYSDATE) - 1',
'           END AS start_year',
'    FROM DUAL',
')',
'CONNECT BY LEVEL <= 10',
'ORDER BY return_value DESC;'))
,p_cHeight=>1
