,p_region_id=>wwv_flow_imp.id(29962660960359069905)
,p_process_type=>'NATIVE_FORM_INIT'
,p_process_name=>'Initialize form Journal Voucher'
,p_static_id=>'initialize-form-journal-voucher'
,p_internal_uid=>11463188357787318
,p_created_on=>wwv_flow_imp.dz('20260825140302Z')
,p_updated_on=>wwv_flow_imp.dz('20260825140302Z')
,p_created_by=>'ADMIN'
