,p_process_name=>'Process form ENTRY'
,p_static_id=>'process-form-entry'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'',
'    IF :P12_PURCHASE_NO IS NULL THEN',
'',
'        INSERT INTO TRN_PURCHASE_MST',
'        (',
'            PURCHASE_NO,',
'            PURCHASE_CODE,',
'            PURCHASE_DATE,',
'            SUPPLIER_NO,',
'            REMARKS,',
'            ACTIVE_FLAG,',
'            CREATED_BY,',
'            CREATED_DATE',
'        )',
'        VALUES',
'        (',
'            SEQ_PURCHASE_NO.NEXTVAL,',
'           ''PUR-''||LPAD(SEQ_PURCHASE_NO.NEXTVAL,4,''0''),',
'            :P12_PURCHASE_DATE,',
'            :P12_SUPPLIER_NO,',
'            :P12_REMARKS,',
'            :P12_ACTIVE_FLAG,',
'            :APP_USER,',
'            SYSDATE',
'        );',
'',
'        apex_application.g_print_success_message :=',
'            ''Purchase information saved successfully.'';',
'',
'    ELSE',
'',
'        UPDATE TRN_PURCHASE_MST',
'           SET',
'               PURCHASE_DATE = :P12_PURCHASE_DATE,',
'               SUPPLIER_NO   = :P12_SUPPLIER_NO,',
'               REMARKS       = :P12_REMARKS,',
'               ACTIVE_FLAG   = :P12_ACTIVE_FLAG,',
'               UPDATED_BY    = :APP_USER,',
'               UPDATED_DATE  = SYSDATE',
'         WHERE PURCHASE_NO = :P12_PURCHASE_NO;',
'',
'        apex_application.g_print_success_message :=',
'            ''Purchase information updated successfully.'';',
'',
'    END IF;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(8268555679605693422)
,p_internal_uid=>8293113625135552030
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(8293113448145552028)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(8293112232890552016)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'REGISTER - Save Interactive Grid Data'
,p_static_id=>'register-save-interactive-grid-data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'',
'    IF :APEX$ROW_STATUS = ''C'' THEN',
'',
'        INSERT INTO TRN_PURCHASE_DTL',
'        (',
'            PURCHASE_DTL_NO,',
'            PURCHASE_NO,',
'            PRODUCT_NO,',
'            PURCHASE_QTY,',
'            PURCHASE_RATE,',
'            TOTAL_AMOUNT,',
'            CREATED_BY,',
'            CREATED_DATE',
'        )',
'        VALUES',
'        (',
'            SEQ_PURCHASE_DTL_NO.NEXTVAL,',
'            :P12_PURCHASE_NO,',
'            :PRODUCT_NO,',
'            :PURCHASE_QTY,',
'            :PURCHASE_RATE,',
'            NVL(:PURCHASE_QTY,0) * NVL(:PURCHASE_RATE,0),',
'            :APP_USER,',
'            SYSDATE',
'        );',
'',
'        apex_application.g_print_success_message :=',
'            ''Purchase detail saved successfully.'';',
'',
'    ELSIF :APEX$ROW_STATUS = ''U'' THEN',
'',
'        UPDATE TRN_PURCHASE_DTL',
'           SET PRODUCT_NO    = :PRODUCT_NO,',
'               PURCHASE_QTY  = :PURCHASE_QTY,',
'               PURCHASE_RATE = :PURCHASE_RATE,',
'               TOTAL_AMOUNT  = NVL(:PURCHASE_QTY,0) * NVL(:PURCHASE_RATE,0)--,',
'               --UPDATED_BY    = :APP_USER,',
'           --    UPDATED_DATE  = SYSDATE',
'         WHERE PURCHASE_DTL_NO = :PURCHASE_DTL_NO;',
'',
'        apex_application.g_print_success_message :=',
'            ''Purchase detail updated successfully.'';',
'',
'    ELSIF :APEX$ROW_STATUS = ''D'' THEN',
'',
'        DELETE',
'          FROM TRN_PURCHASE_DTL',
'         WHERE PURCHASE_DTL_NO = :PURCHASE_DTL_NO;',
'',
'        apex_application.g_print_success_message :=',
'            ''Purchase detail deleted successfully.'';',
'',
'    END IF;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>8293113448145552028
);
end;
